		$this->load->library('encryption');

		//load user agent class
		$this->load->library('user_agent');

	}

	/**NEW CODING STARTS HERE--**/
	/***default function, redirects to login page if no admin logged in yet***/
	public function index() {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$user_level = $this->db->get_where('admin', array('admin_id' => $this->session->userdata('admin_id')))->row()->level;
		if ($user_level == 3) {
			redirect(site_url('admin/pos'), 'refresh');
		}

		if ($this->session->userdata('admin_login') == 1) {
			redirect(site_url('admin/dashboard'), 'refresh');
		}
	}

	// Details of searched query
	function search_results($param1 = "") {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'));
		}

		$search_identifier = $this->input->post('search_identifier');
		$query_by_code = $this->db->get_where('payment_with_goods', array('so_code' => $search_identifier));

		if ($query_by_code->num_rows() == 0) {
			$this->db->like('waybill_code', $search_identifier);
			$this->db->or_like('item_name', $search_identifier);
			$this->db->or_like('invoice_code', $search_identifier);
			$this->db->join('items', 'items.item_id = payment_with_goods.item_id');
			$this->db->join('invoice', 'invoice.so_code = payment_with_goods.so_code');
			$query_by_name = $this->db->get('payment_with_goods');

			if ($query_by_name->num_rows() == 0) {
				$this->session->set_flashdata('error_message', get_phrase('no_record_found'));
				redirect(site_url('admin/dashboard'));
			} else {
				$page_data['search_information'] = $query_by_name->result_array();
			}
		} else {
			$page_data['search_information'] = $query_by_code->result_array();
		}
		$page_data['page_name'] = 'search_result';
		$page_data['page_title'] = get_phrase('search_result');
		$page_data['account_type'] = $this->session->userdata('login_type');
		$this->load->view('backend/index', $page_data);
	}

	/****MANAGE ADMINS*****/

	/******MANAGE OWN PROFILE AND CHANGE PASSWORD***/
	function manage_profile($param1 = '', $param2 = '', $param3 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		if ($param1 == 'update_profile_info') {
			$data['name'] = strtoupper($this->input->post('name'));
			$data['email'] = strtolower($this->input->post('email'));

			$this->load->helper('email');
			if (!valid_email($data['email'])) {
				$errors['invalid_email'] = 'Invalid Email Found';
				echo json_encode($errors);
			}

			$admin_id = $param2;

			$validation = email_validation_for_edit($data['email'], $admin_id, 'admin');
			if ($validation == 1) {
				$this->db->where('admin_id', $this->session->userdata('admin_id'));
				$this->db->update('admin', $data);
				move_uploaded_file($_FILES['userfile']['tmp_name'], 'uploads/admin_image/' . $this->session->userdata('admin_id') . '.jpg');

				$ajax_data['success'] = true;
				$ajax_data['message'] = get_phrase('account_updated');

				echo json_encode($ajax_data);
			} else {
				$errors['duplicate'] = get_phrase('this_email_id_is_not_available');
				echo json_encode($errors);
			}

		}

		if ($param1 == 'change_password') {
			$data['password'] = $this->input->post('password');
			$data['new_password'] = password_hash($this->input->post('new_password'), PASSWORD_BCRYPT);
			$data['confirm_new_password'] = $this->input->post('confirm_new_password');

			$current_password = $this->db->get_where('admin', array(
				'admin_id' => $this->session->userdata('admin_id'),
			))->row()->password;
			if (password_verify($data['password'], $current_password) == 1 && password_verify($data['confirm_new_password'], $data['new_password']) == 1) {
				$this->db->where('admin_id', $this->session->userdata('admin_id'));
				$this->db->update('admin', array(
					'password' => $data['new_password'],
				));

				$ajax_data['success'] = true;
				$ajax_data['message'] = get_phrase('password_updated_successfully. You will be logged out. Please use the current password to login again.');

				//before we send the response, let's destroy the current session and force the user to relog in using the new password
				$this->session->sess_destroy();

				echo json_encode($ajax_data);

			} else {
				$errors['mismatch'] = get_phrase('password_mismatch');
				echo json_encode($errors);
			}

		}
	}

	function admin_list() {
		redirect(site_url('admin/admins'), 'refresh');
	}

	function admins($param1 = '', $param2 = '', $param3 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$this->load->helper('form');
		$this->load->library('form_validation');

		if ($param1 == 'create') {
			$data['name'] = trim(strtoupper($this->input->post('name')));
			$data['designation'] = trim(ucwords(strtolower($this->input->post('designation'))));
			$data['phone'] = trim($this->input->post('phone'));
			$data['email'] = trim(strtolower($this->input->post('email')));
			$data['password'] = password_hash($this->input->post('password'), PASSWORD_BCRYPT);
			if ($this->input->post('level') != null) {
				$data['level'] = $this->input->post('level');
			}

			$data['authentication_key'] = substr(sha1(md5(mt_rand(1054200000, 1059999999))), 0, 5);

			$this->form_validation->set_rules('name', 'Full Name', 'trim|required|min_length[5]');
			$this->form_validation->set_rules('designation', 'Designation', 'trim|required');
			$this->form_validation->set_rules('email', 'Email Address', 'trim|required|min_length[5]');
			$this->form_validation->set_rules('password', 'Password Address', 'trim|required|min_length[6]');

			if ($this->form_validation->run() == FALSE) {
				$this->session->set_flashdata('error_message', 'Some required fields are empty.');
				redirect(site_url('admin/dashboard'), 'refresh');
			}

			$this->load->helper('email');
			if (!valid_email($data['email'])) {
				$this->session->set_flashdata('error_message', 'Invalid Email Found!');
				redirect(site_url('admin/dashboard'), 'refresh');
			}

			/*if($data['level'] == 1) {
				                $admin = 'Super Administrator';
				              } else if($data['level'] == 2){
				                $admin = 'Administrator';
				              } else if($data['level'] == 3){
				                $admin = 'Cashier';
			*/

			$data2['password'] = $this->input->post('password');

			$validation = email_validation($data['email']);

			if ($validation == 1) {
				$this->db->insert('admin', $data);
				$admin_id = $this->db->insert_id();

				//send sms
				$system_name = $this->db->get_where('settings', array('type' => 'system_name'))->row()->description;
				$active_sms_service = $this->db->get_where('settings', array('type' => 'active_sms_service'))->row()->description;

				if ($active_service != 'disabled') {
					$account_opening_sms = 'Welcome to ' . $system_name . '. Your account type is ' . $data['designation'] . '. Here are your login credentials; Your Username: ' . $data['email'] . ', Password: ' . $data2['password'] . ' and Authentication Key: ' . $data['authentication_key'] . '. Thank you.';

					$phone[] = $data['phone'];
					$this->sms_model->send_sms($account_opening_sms, $phone);
				} //SEND SMS ENDED

				$this->email_model->account_opening_email($data['designation'], $data['email'], $data2['password'], $data['authentication_key']); //SEND EMAIL ACCOUNT OPENING EMAIL

				$this->session->set_flashdata('flash_message', get_phrase('admin_added_successfully'));
			} else {
				$this->session->set_flashdata('error_message', get_phrase('this_email_id_is_not_available'));
			}

			//clear the cached database
			$this->db->cache_delete();

			redirect(site_url('admin/dashboard'), 'refresh');
		}
		if ($param1 == 'do_update') {
			$data['name'] = trim(strtoupper($this->input->post('name')));
			$data['designation'] = trim(ucwords(strtolower($this->input->post('designation'))));
			$data['phone'] = trim($this->input->post('phone'));
			$data['email'] = trim(strtolower($this->input->post('email')));

			if ($this->input->post('level') != null) {
				$data['level'] = $this->input->post('level');
			}

			$this->form_validation->set_rules('name', 'Full Name', 'trim|required|min_length[5]');
			$this->form_validation->set_rules('designation', 'Designation', 'trim|required');
			$this->form_validation->set_rules('email', 'Email Address', 'trim|required|min_length[5]');
			$this->form_validation->set_rules('phone', 'Phone', 'trim|required|min_length[10]');

			if ($this->form_validation->run() == FALSE) {
				$this->session->set_flashdata('error_message', 'Some required fields are empty.');
			}

			$this->load->helper('email');
			if (!valid_email($data['email'])) {
				$this->session->set_flashdata('error_message', 'Could Not Update Your Data. Invalid Email Found!');
				redirect(site_url('admin/dashboard'), 'refresh');
			}

			$validation = email_validation_for_edit($data['email'], $param2, 'admin');
			if ($validation == 1) {
				$this->db->where('admin_id', $param2);
				$this->db->update('admin', $data);
				$this->session->set_flashdata('flash_message', get_phrase('admin_updated'));
			} else {
				$this->session->set_flashdata('error_message', get_phrase('this_email_id_is_not_available'));
			}

			//clear the cached database
			$this->db->cache_delete();

			redirect(site_url('admin/dashboard'), 'refresh');
		} else if ($param1 == 'personal_profile') {
			$page_data['personal_profile'] = true;
			$page_data['current_admin_id'] = $param2;

			//clear the cached database
			$this->db->cache_delete();

		} else if ($param1 == 'edit') {
			$page_data['edit_data'] = $this->db->get_where('admin', array(
				'admin_id' => $param2,
			))->result_array();

			//clear the cached database
			$this->db->cache_delete();
		}
		if ($param1 == 'delete') {
			$this->db->where('admin_id', $param2);
			$this->db->delete('admin');

			//clear the cached database
			$this->db->cache_delete();

			$this->session->set_flashdata('flash_message', get_phrase('data_deleted'));
			redirect(site_url('admin/dashboard'), 'refresh');
		} else if ($param1 == 'block') {
			$this->db->where('admin_id', $param2);
			$this->db->set('block_limit', 3);
			$this->db->update('admin');

			//clear the cached database
			$this->db->cache_delete();

			$this->session->set_flashdata('flash_message', get_phrase('user_account_blocked_successfully'));
			redirect(site_url('admin/dashboard'), 'refresh');

		} else if ($param1 == 'unblock') {
			$this->db->where('admin_id', $param2);
			$this->db->set('block_limit', 0);
			$this->db->update('admin');

			//clear the cached database
			$this->db->cache_delete();

			//send authentication code via sms and email
			$owner_email = $this->db->get_where('settings', array('type' => 'system_email'))->row()->description;
			$active_sms_service = $this->db->get_where('settings', array('type' => 'active_sms_service'))->row()->description;

			$user_rows = $this->db->get_where('admin', array('admin_id' => $param2))->row();
			$user_name = $user_rows->name;
			$user_mail = $user_rows->email;
			$user_phone[] = $user_rows->phone;
			$user_auth_key = $user_rows->authentication_key;

			//prepare the message
			$message_sms = 'Hello ' . $user_name . ', thank you for your request to unblock your account. Your account has been unblocked successfully. Use this authentication key to login: ' . $user_auth_key . '.';

			$message_email = 'Hello ' . $user_name . ', thank you for your request to unblock your account. Your account has been unblocked successfully. Use this authentication key to login: <strong>' . $user_auth_key . '.</strong>';

			//sms first
			if ($active_sms_service != 'disabled') {
				// send sms
				$this->sms_model->send_sms($message_sms, $user_phone);
			}

			//send email
			$this->email_model->do_email($message_email, 'Account Status', $user_mail, $owner_email);

			$this->session->set_flashdata('flash_message', get_phrase('user_account_unblocked_successfully'));
			redirect(site_url('admin/dashboard'), 'refresh');
		}
		$page_data['admin'] = $this->db->get('admin')->result_array();
		$page_data['page_name'] = 'admin_list';
		$page_data['page_title'] = get_phrase('manage_admin');
		$this->load->view('backend/index', $page_data);
	}

	function get_admin() {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$columns = array(
			0 => 'admin_id',
			1 => 'name',
			2 => 'email',
			3 => 'auth_key',
			4 => 'phone',
			5 => 'designation',
			6 => 'account_status',
			7 => 'options',
			8 => 'online',
			9 => 'level',
			10 => 'admin_id',
		);

		$limit = $this->input->post('length');
		$start = $this->input->post('start');
		$order = $columns[$this->input->post('order')[0]['column']];
		$dir = $this->input->post('order')[0]['dir'];

		$totalData = $this->ajaxload->all_admin_count();
		$totalFiltered = $totalData;

		if (empty($this->input->post('search')['value'])) {
			$admin = $this->ajaxload->all_admin($limit, $start, $order, $dir);
		} else {
			$search = $this->input->post('search')['value'];
			$admin = $this->ajaxload->admin_search($limit, $start, $search, $order, $dir);
			$totalFiltered = $this->ajaxload->admin_search_count($search);
		}

		$data = array();
		if (!empty($admin)) {
			foreach ($admin as $row) {

				$options = '<div class="dropdown"><button type="button" class="btn btn-info btn-sm dropdown-toggle" data-toggle="dropdown">
                                    Action </button><ul class="dropdown-menu dropdown-default pull-right" role="menu"><li><a class="dropdown-item" href="#" onclick="admin_edit_modal(' . $row->admin_id . ')" style="color: green;"><i class="entypo-pencil"></i>&nbsp;' . get_phrase('edit') . '</a></li><li class="divider"></li><li><a class="dropdown-item" href="#" onclick="admin_delete_confirm(' . $row->admin_id . ')" style="color: red;"><i class="entypo-trash"></i>&nbsp;' . get_phrase('delete') . '</a></li></ul></div>';

				if ($row->block_limit == 3) {
					$as_btn = 'Blocked';
					$btn_style = 'danger';
					$btn_cont = '</button><ul class="dropdown-menu dropdown-default pull-right" role="menu"><li><a class="dropdown-item" href="#" onclick="account_unblock(' . $row->admin_id . ')" style="color: green;"><i class="fa fa-unlock"></i>&nbsp;' . get_phrase('unblock') . '</a></li></li></ul>';
				} else {
					$as_btn = 'Active';
					$btn_style = 'success';
					$btn_cont = '</button><ul class="dropdown-menu dropdown-default pull-right" role="menu"><li><a class="dropdown-item" href="#" onclick="account_block(' . $row->admin_id . ')" style="color: red;"><i class="glyphicon glyphicon-lock"></i>&nbsp;' . get_phrase('block') . '</a></li></li></ul>';
				}

				$account_status = '<div class="dropdown"><button type="button" class="btn btn-' . $btn_style . ' btn-sm dropdown-toggle" data-toggle="dropdown">
                                    ' . $as_btn . ' ' . $btn_cont . '</div>';

				if ($row->online_status == 1) {
					$btn_color = 'success';
					$text = 'Online';
				} else {

					$btn_color = 'default';
					$text = 'Offline';
				}
				$online = '<button type="button" class="btn btn-' . $btn_color . ' btn-sm">' . $text . '</button>';

				$nestedData['admin_id'] = $row->admin_id;
				$nestedData['name'] = $row->name;
				$nestedData['email'] = '<a href="mailto:' . $row->email . '" style="color: blue;">' . $row->email . '</a>';
				$nestedData['auth_key'] = '<strong style="letter-spacing: 3px">' . $row->authentication_key . '</strong>';
				$nestedData['phone'] = '<a href="tel:' . $row->phone . '" style="color: blue;">' . $row->phone . '</a>';
				$nestedData['designation'] = $row->designation;

				if ($row->level == 1) {
					$nestedData['level'] = 'Super Administrator';
				} else if ($row->level == 2) {
					$nestedData['level'] = 'Administrator';
				} else if ($row->level == 3) {
					$nestedData['level'] = 'Cashier';
				}

				$nestedData['account_status'] = $account_status;
				$nestedData['options'] = $options;
				$nestedData['online'] = $online;

				$data[] = $nestedData;
			}
		}

		$json_data = array(
			"draw" => intval($this->input->post('draw')),
			"recordsTotal" => intval($totalData),
			"recordsFiltered" => intval($totalFiltered),
			"data" => $data,
		);

		echo json_encode($json_data);
	}

	//get user attendance
	function get_attendance() {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$columns = array(
			0 => 'attendance_id',
			1 => 'date_timestamp',
			2 => 'user_id',
			3 => 'in_timestamp',
			4 => 'out_timestamp',
			5 => 'attendance_id',
		);

		$limit = $this->input->post('length');
		$start = $this->input->post('start');
		$order = $columns[$this->input->post('order')[0]['column']];
		$dir = $this->input->post('order')[0]['dir'];

		$totalData = $this->ajaxload->all_att_count();
		$totalFiltered = $totalData;

		if (empty($this->input->post('search')['value'])) {
			$att = $this->ajaxload->all_att($limit, $start, $order, $dir);
		} else {
			$search = $this->input->post('search')['value'];
			$att = $this->ajaxload->att_search($limit, $start, $search, $order, $dir);
			$totalFiltered = $this->ajaxload->att_search_count($search);
		}

		$data = array();
		if (!empty($att)) {
			foreach ($att as $row) {

				$nestedData['attendance_id'] = $row->attendance_id;
				$nestedData['date'] = date('d-m-Y', $row->date_timestamp);
				$nestedData['name'] = $this->db->get_where('admin', array('admin_id' => $row->user_id))->row()->name;
				$nestedData['phone'] = $this->db->get_where('admin', array('admin_id' => $row->user_id))->row()->phone;

				$nestedData['designation'] = $this->db->get_where('admin', array('admin_id' => $row->user_id))->row()->designation;
				/*if($user_level == 1) {
					                    $nestedData['level'] = 'Super Administrator';
					                } else if($user_level == 2) {
					                    $nestedData['level'] = 'Administrator';
					                } else if($user_level == 3){
					                    $nestedData['level'] = 'Cashier';
				*/

				$nestedData['in_timestamp'] = $row->in_timestamp != null ? '<button type="button" class="btn btn-success btn-lg">' . date('H:i:s', $row->in_timestamp) . '</button>' : '<button type="button" class="btn btn-success btn-lg">N/A</button>';
				$nestedData['out_timestamp'] = $row->out_timestamp != null ? '<button type="button" class="btn btn-danger btn-lg">' . date('H:i:s', $row->out_timestamp) . '</button>' : '<button type="button" class="btn btn-danger btn-lg">pending...</button>';

				$data[] = $nestedData;

			}
		}

		$json_data = array(
			"draw" => intval($this->input->post('draw')),
			"recordsTotal" => intval($totalData),
			"recordsFiltered" => intval($totalFiltered),
			"data" => $data,
		);

		echo json_encode($json_data);
	}


	function loadContents($type='', $param='') {
	

		if($param != 'freshLoad') {
			//load main page
			$page_data['page_name'] = $type;
			$page_data['page_title'] = get_phrase('admin_'.$type);
			$ajaxData['mainPage'] = $this->load->view('backend/admin/pages/' . $type, $page_data, true);
			
		}

		//load nav menu
		$ajaxData['navMenu'] = $this->load->view('backend/admin/navs/'.$type.'-nav', '', true);

		echo json_encode($ajaxData);

	}

	/***ADMIN DASHBOARD***/
	function dashboard($param = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//restrict Cashiers from accessing this page
		$user_level = $this->db->get_where('admin', array('admin_id' => $this->session->userdata('admin_id')))->row()->level;
		if ($user_level == 3) {
			redirect(site_url('admin/pos'), 'refresh');
		}

		if ($param == 'ajax') {
			$page_data['page_name'] = 'dashboard';
			$page_data['page_title'] = get_phrase('admin_dashboard');
			$this->load->view('backend/admin/pages/' . $page_data['page_name'] . '.php', $page_data);
		} else {
			$page_data['page_name'] = 'dashboard';
			$page_data['page_title'] = get_phrase('admin_dashboard');
			$this->load->view('backend/index', $page_data);
		}

	}

	/***ADMIN SALES PAGE***/
	function sales($param = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

