	//for calculating margins
	function stock_margin_report($param = '0', $sentPeriods='', $sentCategory='', $sentTo='', $sentYear='') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$errors = [];
		$ajaxData = [];

		$periods = $this->input->post('search_by_periods');

		$category_id = '';

		$searchByCategoryId = $this->input->post('search_by_category');

		if(isset($searchByCategoryId) && is_array($searchByCategoryId) && count($searchByCategoryId) > 0) {
			$category_id = implode('-', $this->input->post('search_by_category'));
		}
		
	
		$to = $this->input->post('date_view');
		$year = $this->input->post('year');



		if($param == '0') {

			//////////////////////validate selected date, week or month///////

			if(empty($periods) || $periods == '') {
				$errors['periods'] = 'Select a period!';
			}

			if($category_id == '') {
				$errors['category_id'] = 'Select at least one category!';
			}

			if(empty($to) || $to == '') {
				$errors['date_view'] = 'Date must be selected';
			} 

			if($periods == 'd' && (strtotime($to) > strtotime('today'))) {
				$errors['date_view'] = 'Invalid date selected. Please select date not greater than today\'s date';
			}

			///////////////////////////////end//////////////////////////
			
			if(!empty($errors)) {
				//error
				echo json_encode($errors);
				return false;

			}

			$ajaxData['periods'] = $periods;
			$ajaxData['category_id'] = $category_id;
			$ajaxData['to'] = $to;
			$ajaxData['year'] = $year;

			$ajaxData['status'] = 'success';
			$ajaxData['message'] = 'Successful! Redirecting you...';

			echo json_encode($ajaxData);
			return;

		}

		if($param == '1') {

			//no error
			//switch pages here

			$page_data['periods'] = $sentPeriods;
			$page_data['category_id'] = $sentCategory;
			$page_data['to'] = $sentTo;
			$page_data['year'] = $sentYear;


			if($page_data['periods'] == 'd') {
				$page_data['page_name'] = 'stock_margin_report_daily';

			} else if($page_data['periods'] == 'w') {
				$page_data['page_name'] = 'stock_margin_report_weekly';

			} else if($page_data['periods'] == 'm') {
				$page_data['page_name'] = 'stock_margin_report_monthly';
			}
			

			$page_data['page_title'] = get_phrase('STOCK MARGIN REPORT');
			$this->load->view('backend/admin/pages/reports/' . $page_data['page_name'], $page_data);
			
			return;
			
		}

		
	}

