	//Accounts Payable report link
	function accounts_payable_report($from = '', $to = '', $creditor_id = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		if ($from != '' && $to != '') {
			$page_data['from'] = $from;
			$page_data['to'] = $to;
		} else {
			$page_data['from'] = $this->input->post('from');
			$page_data['to'] = $this->input->post('to');
		}

		if ($creditor_id != '') {
			$page_data['customer_id'] = substr($creditor_id, 3);
			$page_data['category'] = substr($creditor_id, 0, 2);

		} else {
			$page_data['customer_id'] = $this->input->post('customer_id');
		}

		if($from == 'test') {
			$page_data['page_name'] = 'accounts_payable_report2';

		} else {

			$page_data['page_name'] = 'accounts_payable_report';
		}
		
		$page_data['page_title'] = get_phrase('ACCOUNTS PAYABLE REPORT');
		$this->load->view('backend/admin/pages/reports/' . $page_data['page_name'] . '.php', $page_data);
	}

