					$this->db->set('current_balance', 'current_balance +' . $current_bal_data['current_balance'], FALSE);
					$this->db->update('accounts');

					//update all the balances in the journal
					$account_name_j = $this->db->get_where('accounts', array('account_id' => $account_id))->row()->name;
					$this->db->where('account_name', $account_name_j);
					$this->db->set('account_balance', 'account_balance +' . $current_bal_data['current_balance'], FALSE);
					$this->db->update('general_journal');

					////return now
					$ajax_data['success'] = true;
					echo json_encode($ajax_data);

				}
			} else {
				////return now
				$ajax_data['success'] = 'duplicate';
				echo json_encode($ajax_data);
			}

		}

		//Accounts Deletion
		if ($param1 == 'account_delete') {

			//find from payment table
			$this->db->where('account_id', $param2);
			$rows_returned = $this->db->get('payment')->num_rows();

			if ($rows_returned < 1) {
