				echo $ok;
			} else {
				////return now
				$ok = false;
				echo $ok;
			}

		}
		//Change Skin
		if ($param1 == 'change_skin') {
			$data['description'] = $param2;
			$this->db->where('type', 'skin_colour');
			$this->db->update('settings', $data);

		}
	}

	//**ACCOUNTS TRANSFER CREATION, NO UPDATES AND NO DELETION**/
	function accounts_transfer($param1 = '', $param2 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'create') {

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$accounts_from_data['account_id'] = $this->input->post('account_from');
			$accounts_from_data['current_balance'] = $this->input->post('amount');

			$accounts_to_data['account_id'] = $this->input->post('account_to');
			$accounts_to_data['current_balance'] = $this->input->post('amount');

			//check for possible errors
			//empty fields sent error
			if (empty($accounts_from_data['account_id'])) {
				$errors['account_from'] = 'Please select the Account you are transferring from.';
			}

			if (empty($accounts_to_data['account_id'])) {
				$errors['account_to'] = 'Please select the Account you are transferring from.';
			}

			if (empty($this->input->post('date'))) {
				$errors['date'] = 'Make sure the date is selected.';
			}

			if (empty($this->input->post('amount'))) {
				$errors['amount'] = 'Specify the amount you want to transfer.';
			}

			if (!is_numeric($this->input->post('amount')) && $this->input->post('amount') < 1) {
				$errors['invalid_amount'] = 'Enter a valid amount. Must be greater than 0 and not contain alphabets or other characters!';
			}

			//check if there is sufficient fund for the transfer
			$from_account_current_balance = $this->db->get_where('accounts', array('account_id' => $accounts_from_data['account_id']))->row()->current_balance;

			if ($this->input->post('amount') > $from_account_current_balance) {
				$errors['insufficient_fund'] = 'You don\'t have sufficient fund for this transaction.';
			}

			//DID THE USER SELECT THE SAME ACCOUNT IN BOTH SELECTIONS?
			if ($accounts_from_data['account_id'] == $accounts_to_data['account_id']) {
				$errors['same_account'] = 'It seems you have selected the same account for both. Kindly check and try again.';
			}

			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {
				//no error found, let's insert data now

				//UPDATE ACCOUNT TRANSFERRED FROM BY REDUCING THE BALANCE
				//for account from:
				$this->db->where('account_id', $accounts_from_data['account_id']);
				$this->db->set('current_balance', 'current_balance -' . $accounts_from_data['current_balance'], FALSE);
				$this->db->update('accounts');

				//UPDATE ACCOUNT TRANSFERRED TO BY INCREASING THE BALANCE
				//for account to:
				$this->db->where('account_id', $accounts_to_data['account_id']);
				$this->db->set('current_balance', 'current_balance +' . $accounts_to_data['current_balance'], FALSE);
				$this->db->update('accounts');

				//NOW DO THE JOURNAL ENTRIES
				//for accounts from - credit entry
				//General Journal data
				$from_account_name = $this->db->get_where('accounts', array('account_id' => $accounts_from_data['account_id']))->row()->name;

				$to_account_name = $this->db->get_where('accounts', array('account_id' => $accounts_to_data['account_id']))->row()->name;

				$from_account_balance = $this->db->get_where('accounts', array('account_id' => $accounts_from_data['account_id']))->row()->current_balance;

				$to_account_balance = $this->db->get_where('accounts', array('account_id' => $accounts_to_data['account_id']))->row()->current_balance;

				//for from
				$journal_data_from['credit_amount'] = $accounts_from_data['current_balance'];
				$journal_data_from['date'] = $this->input->post('date');
				$journal_data_from['account_name'] = $from_account_name;
				$journal_data_from['account_balance'] = $from_account_balance;
				$journal_data_from['journal'] = 'Fund Transfer';
				$journal_data_from['description'] = 'Fund Transfer from ' . $from_account_name . ' to ' . $to_account_name;
				$journal_data_from['timestamp'] = strtotime($this->input->post('date'));
				$journal_data_from['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$journal_data_from['sales_person_id'] = $this->session->userdata('login_user_id');
				$this->db->insert('general_journal', $journal_data_from);

				//for to
				$journal_data_to['debit_amount'] = $accounts_to_data['current_balance'];
				$journal_data_to['date'] = $this->input->post('date');
				$journal_data_to['account_name'] = $to_account_name;
				$journal_data_to['account_balance'] = $to_account_balance;
				$journal_data_to['journal'] = 'Fund Transfer';
				$journal_data_to['description'] = 'Fund Transfer from ' . $from_account_name . ' to ' . $to_account_name;
				$journal_data_to['timestamp'] = strtotime($this->input->post('date'));
				$journal_data_to['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$journal_data_to['sales_person_id'] = $this->session->userdata('login_user_id');
				$this->db->insert('general_journal', $journal_data_to);

				$ajax_data['success'] = true;
				echo json_encode($ajax_data);

			}
		}
	}

	//**SUPPLIERS CREATION, UPDATES AND DELETION**/
	function supplier($param1 = '', $param2 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'create') {

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$supplier_create_data['supplier_name'] = strtoupper($this->input->post('supplier_name'));
			$supplier_create_data['contact_person'] = strtoupper($this->input->post('contact_person_name'));
			$supplier_create_data['address'] = $this->input->post('address');
			//$supplier_create_data['location_id'] = $this->input->post('location');
			$supplier_create_data['mobile'] = $this->input->post('mobile_number');
			$supplier_create_data['phone'] = $this->input->post('phone_number');
			$supplier_create_data['date'] = date('d-m-Y');
			$supplier_create_data['timestamp'] = strtotime(date('d-m-Y'));
			$supplier_create_data['email'] = strtolower($this->input->post('supplier_email'));
			$supplier_create_data['opening_balance'] = trim($this->input->post('opening_balance'));
			//$supplier_create_data['balance_due']  = trim($this->input->post('balance_due'));

			//check if any required field is empty
			if (empty($supplier_create_data['supplier_name'])) {
				$errors['supplier_name'] = 'Supplier\'s name cannot be empty';
			}

			if (empty($supplier_create_data['contact_person'])) {
				$errors['contact_person'] = 'Contact person name is required';
			}

			if (empty($supplier_create_data['address'])) {
				$errors['address'] = 'Supplier\'s address is required';
			}

			/*if (empty($supplier_create_data['location_id'])) {
				$errors['location_id'] = 'Supplier\'s Location is required';
			}*/

			if (empty($supplier_create_data['mobile'])) {
				$errors['mobile'] = 'Supplier\'s mobile number cannot be empty';
			} else {
				if (!validate_phone_number($supplier_create_data['mobile'])) {
					$errors['mobile_invalid'] = 'Mobile number is invalid. Avoid using +233.';
				}

			}

			if (!empty($supplier_create_data['phone'])) {
				if (!validate_phone_number($supplier_create_data['phone'])) {
					$errors['phone_invalid'] = 'Phone number is invalid. Avoid using +233.';
				}

			}

			//check if email is valid
			if (!empty($supplier_create_data['email'])) {
				if (!valid_email($supplier_create_data['email'])) {
					$ajax_data['success'] = 'invalid_email';
					echo json_encode($ajax_data);
				}
			}

			//check for duplicate
			if (supplier_validation_insert($supplier_create_data['supplier_name'], $supplier_create_data['mobile'], $supplier_create_data['email'])) {

				if (!empty($errors)) {
					//error found, let's notify the user of it
					$ajax_data = $errors;
					echo json_encode($ajax_data);
				} else {
					//no error found, let's insert data now
					//why don't we check if the vital account like Accounts Payable have been created before we create a new or the very first customer.

					if (!account_name_validation_insert('Accounts Payable')) {

						$this->db->insert('suppliers', $supplier_create_data);

						$supplier_id = $this->db->insert_id();

						if ($this->input->post('opening_balance') != 0) {
							//insert into accounts payable table
							$acc_payable_table['supplier_id'] = $supplier_id;
							$acc_payable_table['amount'] = trim($this->input->post('opening_balance'));
							$acc_payable_table['po_code'] = 'Opening-balance';
							$acc_payable_table['amount_due'] = trim($this->input->post('opening_balance'));
							$acc_payable_table['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
							$acc_payable_table['date'] = date('d-m-Y');
							$acc_payable_table['timestamp'] = strtotime(date('d-m-Y'));
							//insert
							$this->db->insert('accounts_payable', $acc_payable_table);

							$opening_accounts_payable_id = $this->db->insert_id();

							//update supplier with opening_accounts_payable_id
							$this->db->where('supplier_id', $supplier_id);
							$this->db->set('opening_accounts_payable_id', $opening_accounts_payable_id);
							$this->db->update('suppliers');
						}

						//if it is a negative opening balance-update accounts receivable
						if ($supplier_create_data['opening_balance'] < 0) {
							$receivable_from_supplier = abs($supplier_create_data['opening_balance']);
							//update accounts receivable
							$this->db->where('name', 'Accounts Receivable');
							$this->db->set('current_balance', 'current_balance +' . $receivable_from_supplier, FALSE);
							$this->db->update('accounts');

						} else if ($this->input->post('opening_balance') > 0) {

							//let's update the account payable balance in the accounts table
							$payable['current_balance'] = $supplier_create_data['opening_balance'];
							$this->db->where('name', 'Accounts Payable');
							$this->db->set('current_balance', 'current_balance + ' . $payable['current_balance'], FALSE);
							$this->db->update('accounts');
						}

						$ajax_data['success'] = true;
						echo json_encode($ajax_data);

					} else {
						$ajax_data['success'] = 'not_found';
						echo json_encode($ajax_data);
					}
				}
			} else {
