			if (empty($supplier_create_data['supplier_name'])) {
				$errors['supplier_name'] = 'Supplier\'s name cannot be empty';
			}

			if (empty($supplier_create_data['contact_person'])) {
				$errors['contact_person'] = 'Contact person name is required';
			}

			if (empty($supplier_create_data['address'])) {
				$errors['address'] = 'Supplier\'s address is required';
			}

			/*if (empty($supplier_create_data['location_id'])) {
				$errors['location_id'] = 'Supplier\'s Location is required';
			}*/

			if (empty($supplier_create_data['mobile'])) {
				$errors['mobile'] = 'Supplier\'s mobile number cannot be empty';
