				if (!validate_phone_number($supplier_create_data['mobile'])) {
					$errors['mobile_invalid'] = 'Mobile number is invalid. Avoid using +233.';
				}

			}

			//wait a minute, before that, let's get the previous current balance of this supplier first
			$prev_op_amnt_query = $this->db->get_where('accounts_payable', array('supplier_id' => $supplier_id, 'po_code' => 'Opening-balance'));

