					//update into accounts payable table

					//CHECK IF THIS SUPPLIER WITH OPENING BALANCE EXISTS OR NOT
					$n_rows = $this->db->get_where('accounts_payable', array('supplier_id' => $supplier_id, 'po_code' => 'Opening-balance'))->num_rows();
					if ($n_rows > 0) {

						$acc_payable_table['amount'] = $difference;
						//let's update
						//update
						$this->db->where('supplier_id', $supplier_id);
						$this->db->where('accounts_payable_id', $opening_accounts_payable_id);
						$this->db->where('po_code', 'Opening-balance');
						//$this->db->set('date', date('d-m-Y'));
						$this->db->set('amount', 'amount + ' . $acc_payable_table['amount'], FALSE);
						$this->db->set('amount_due', 'amount_due + ' . $acc_payable_table['amount'], FALSE);
						$this->db->update('accounts_payable');

					} else {

						if ($this->input->post('opening_balance') > 0) {
							//insert into accounts payable table
							$acc_payable_table['supplier_id'] = $supplier_id;

							if ($this->input->post('opening_balance') != 0) {
								$acc_payable_table['amount_due'] = trim($this->input->post('opening_balance'));
								$acc_payable_table['amount'] = trim($this->input->post('opening_balance'));
								$acc_payable_table['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
								$acc_payable_table['date'] = date('d-m-Y');
								$acc_payable_table['timestamp'] = strtotime(date('d-m-Y'));
								$acc_payable_table['po_code'] = 'Opening-balance';
								//insert
								$this->db->insert('accounts_payable', $acc_payable_table);

								$opening_accounts_payable_id = $this->db->insert_id();

							}
							//update supplier with opening_accounts_payable_id
							$this->db->where('supplier_id', $supplier_id);
							$this->db->set('opening_accounts_payable_id', $opening_accounts_payable_id);
							$this->db->update('suppliers');

						}
					}

					// }

					$ajax_data['success'] = true;
					echo json_encode($ajax_data);
				}
			} else {
				$ajax_data['success'] = 'duplicate';
				$ajax_data['s_name'] = $supplier_create_data['supplier_name'];
				echo json_encode($ajax_data);
			}
		}

		//Delete Supplier here'
		if ($param1 == 'delete') {
			$supplier_id = $param2;

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$this->crud_model->delete_supplier($supplier_id);
		}

	}

