					$this->db->where('item_id', $item_id);
					$this->db->update('items', $item_data);

					
					//LET'S GET ALL THE AVAILABLE ACTIVE CUSTOMERS SO WE CAN UPDATE THESE CUSTOMERS' PRICES IN THE PRICES TABLE WITH THE SELLING PRICE OF THIS ITEM(PRODUCT)

          $c_p_data['item_price'] = $item_data['selling_price'];

          $this->db->where('item_id', $item_id);
          $this->db->update('items_prices', $c_p_data);

          //for the unit prices table too
          $this->db->where('item_id', $item_id);
          $item_row = $this->db->get('items')->row();


          //if the item is sold in units, get the unit price
          $isSoldInUnit = $item_row->item_sold_in_units;

          if($isSoldInUnit > 0) {

          	for($i = 0; $i < sizeof($unit_ids_array); $i++) {

          		$this->db->where('item_id', $item_id);
          		$this->db->where('unit_id', $unit_ids_array[$i]);
	          	$unit_price_data['item_price'] = $this->db->get('units_items')->row()->unit_price;

	          	$this->db->where('item_id', $item_id);
	          	$this->db->where('unit_id', $unit_ids_array[$i]);
	          	$this->db->update('items_units_prices', $unit_price_data);

          	}
          }	//end of price update for the customers

					//Upload Item Image
					if (isset($_FILES['item_image']['name'])) {

						//check if the file exists
						$fileExists = file_exists('uploads/item_image/' . $item_id . '.jpg');

						if($fileExists) {
							//we delete it
							unlink('uploads/item_image/' . $item_id . '.jpg');

						}

						//now we upload the new one
						$upload_l = move_uploaded_file($_FILES['item_image']['tmp_name'], 'uploads/item_image/' . $item_id . '.jpg');
					}

					//all customers with credit purchases should have their prices

					////return now
					$ajax_data['success'] = true;
					echo json_encode($ajax_data);

				}
			} else {
				////return now
				$ajax_data['success'] = 'duplicate';
				echo json_encode($ajax_data);
			}

		}

		//item Deletion
		if ($param1 == 'delete') {
			$item_id = $param2;
			$po_id = $this->db->get_where('items', array('item_id' => $item_id))->row()->po_id;

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$this->crud_model->delete_item($item_id, $po_id);

			//done, show confirmation flag
			$ajax_data['success'] = true;
			$ajax_data['user'] = 'Item';
			echo json_encode($ajax_data);
		}

	}

