	//**PURCHASE ORDER CREATION, UPDATES AND DELETION**/
	function purchase_order($param1 = '', $param2 = '', $param3 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$po_prefix = $this->db->get_where('settings', array('type' => 'po_prefix'))->row()->description;
		$po_no_full = $po_prefix . $this->db->get_where('settings', array('type' => 'po_no'))->row()->description;

		//currency
		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);

		//get form data
		if ($param1 == 'create') {

			$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
			//Track errors and success
			$errors = array();
			$ajax_data = array();

			//imported ids array
			$input_ids_numeric = explode('-', $param2);

			//FOR PURCHASE ORDER TABLE
			$p_order_create_data['po_code'] = $this->input->post('purchase_order_no');
			$p_order_create_data['supplier_id'] = $this->input->post('order_from');
			$p_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
			$p_order_create_data['timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));
			$p_order_create_data['date'] = $this->input->post('order_date');
			$p_order_create_data['comment'] = $this->input->post('comments');
			$p_order_create_data['track_code'] = $paid_data['track_code'];
			$p_order_create_data['private_comment'] = $this->input->post('private_comments');
			$account_balance = $this->input->post('hidden_account_balance');

			$cash_sales = $this->input->post('instant_payment');

			if($cash_sales == 1) {
				//validate
				if ($this->input->post('amount_paid') != 0 && !empty($account_balance)) {
					if ($this->input->post('amount_paid') > $account_balance) {
						$errors['account_balance'] = 'You do not have sufficient fund in this account to perform this transaction. Please use a different account. Current Account Balance is: ' . numfmt_format_currency($fmt, $account_balance, $currency) . ' and Your payment is: ' . numfmt_format_currency($fmt, $this->input->post('amount_paid'), $currency);
					}
				} else if (!empty($account_balance)) {
					if ($this->input->post('amount_paid') < 1) {
						$errors['invalid_payment'] = 'Amount Paid is invalid! Please use a positive number';
					}
				}
			}

			//check if today's date is selected
			if ($p_order_create_data['date_timestamp'] !== strtotime(date('d-m-Y'))) {
				// $errors['mismatch_date'] = 'Creation date error. It seems your selected date is not for today. Please check and try again.';
			}

			//check if any required field is empty
			if (empty($p_order_create_data['po_code'])) {
				$errors['po_code'] = 'PO Number cannot be empty';
			}

			if (empty($p_order_create_data['supplier_id'])) {
				$errors['supplier_id'] = 'You must select a supplier';
			}

			if (empty($p_order_create_data['date'])) {
				$errors['date'] = 'Order Date cannot be empty';
			}

			//check for duplicate
			if (!p_order_validation_insert($p_order_create_data['po_code'])) {

				$ajax_data['success'] = 'duplicate';
				$ajax_data['po_code'] = $p_order_create_data['po_code'];
				echo json_encode($ajax_data);
			} else {
				if (!empty($errors)) {
					//error found, let's notify the user of it
					$ajax_data = $errors;
					echo json_encode($ajax_data);
				} else {

					//collect data for each item bought
					for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
						$p_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
						$p_order_create_data['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);
						$p_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
						$p_order_create_data['grand_total'] = $this->input->post('hidden_total');
						$p_order_create_data['html_id'] = $input_ids_numeric[$i];
						$p_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);
						$p_order_create_data['amount_paid'] = $this->input->post('amount_paid');
						$p_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance');

						if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
							$p_order_create_data['status'] = 'Unpaid';
						} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
							$p_order_create_data['status'] = 'Partially Paid';
						} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
							$p_order_create_data['status'] = 'Paid';
						}

						//FOR STOCK RECORDS TABLE
						$stock_records['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);
						$stock_records['supplier_id'] = $p_order_create_data['supplier_id'];
						$stock_records['po_code'] = $p_order_create_data['po_code'];
						$stock_records['date'] = $p_order_create_data['date'];
						$stock_records['q_bought'] = $p_order_create_data['quantity'];
						$stock_records['item_balance'] = $p_order_create_data['quantity'];
						$stock_records['cost_price'] = $p_order_create_data['price'];
						$stock_records['timestamp'] = $p_order_create_data['timestamp'];


						//check if any required field is empty
						if (empty($p_order_create_data['quantity'])) {
							$errors['quantity'] = 'Order Quantity cannot be empty';
						}

						if (empty($p_order_create_data['item_id'])) {
							$errors['item_id'] = 'You must select an Item';
						}

						if (empty($p_order_create_data['amount'])) {
							$errors['amount'] = 'Total amount cannot be empty';
						}

						if (!validate_po_no($p_order_create_data['po_code'])) {
							$errors['invalid_po_code'] = 'The Purchase Order Code [' . $p_order_create_data['po_code'] . '] is invalid. Please check the correct format in System Settings >> Company.';
						}

						//if there's error
						if (!empty($errors)) {
							//error found, let's notify the user of it
							$ajax_data = $errors;
							echo json_encode($ajax_data);
						} else {

							//No error found, now we can insert data
							$this->db->insert('purchase_order', $p_order_create_data);
							//get p order id
							$po_id = $this->db->insert_id();

							//for stock records too
							$this->db->insert('stock_record', $stock_records);							

							
							//update item table
							$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);
							$item_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
							$item_data['purchase_price'] = $p_order_create_data['price'];
							$item_data['last_modified'] = strtotime(date('d-m-Y H:i:s', strtotime($this->input->post('order_date2'))));

							//do update now
							$this->db->where('item_id', $item_id);
							$this->db->set('last_modified', $item_data['last_modified']);
							$this->db->set('purchase_price', $item_data['purchase_price']);
							$this->db->set('quantity', 'quantity + ' . $item_data['quantity'], FALSE);
							$this->db->update('items');

							//let's get the current total quantity
							$current_item_query = $this->db->get_where('items', array('item_id' => $item_id))->row();
							$current_quantity = $current_item_query->quantity;
							$current_selling_price = $current_item_query->selling_price;
							//let's update the purchase order table with it
							$this->db->where('po_id', $po_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->update('purchase_order');

							//we want to do this if a cashier or any user is already logged in before the new stock arrived
							//this will help us get the total stock available for general closing stock report and backlogs
							$this->db->where('item_id', $item_id);
							$this->db->where('date_timestamp', strtotime($this->input->post('order_date')));
							//$this->db->where('closing_stock IS NULL');
							$this->db->set('stock_in_today', 'stock_in_today +' . $item_data['quantity'], FALSE);
							$this->db->set('cost_price', $item_data['purchase_price']);
							$this->db->set('selling_price', $current_selling_price);
							$this->db->update('stock_manager');

						}
					} //End of loop

					if (empty($errors)) {

						//FOR PURCHASES ORDER

						//update general products purchases account
						$products_purchases['current_balance'] = $this->input->post('hidden_total');
						$this->db->where('name', 'General Products Purchased');
						$this->db->set('current_balance', 'current_balance + ' . $products_purchases['current_balance'], FALSE);
						$this->db->update('accounts');

						//get total account balance for General Products Purchased
						$gpp_balance = $this->db->get_where('accounts', array('name' => 'General Products Purchased'))->row()->current_balance;

						//get total account balance for Accounts Payable
						$acp_balance = $this->db->get_where('accounts', array('name' => 'Accounts Payable'))->row()->current_balance;
						$acp_balance += $products_purchases['current_balance'];

						//get total accounts payable from the table
						//  $acpp_balance = $this->db->get_where('accounts', array('name' => 'Accounts Payable'))->row()->current_balance;

						//FOR GENERAL JOURNAL ENTRY (GENERAL PRODUCTS PURCHASED) DEBIT THIS
						$journal_data_gp['timestamp'] = strtotime($this->input->post('order_date'));
						$journal_data_gp['date_timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));
						$journal_data_gp['date'] = $this->input->post('order_date');
						$journal_data_gp['supplier_id'] = $this->input->post('order_from');
						$journal_data_gp['journal'] = 'Purchases';
						$journal_data_gp['po_code'] = $this->input->post('purchase_order_no');
						$journal_data_gp['account_name'] = 'General Products Purchased';
						$journal_data_gp['account_balance'] = $gpp_balance;
						$journal_data_gp['debit_amount'] = $this->input->post('hidden_total');
						$journal_data_gp['reference'] = '';
						$journal_data_gp['description'] = 'Purchases from ' . $this->db->get_where('suppliers', array('supplier_id' => $journal_data_gp['supplier_id']))->row()->supplier_name;
						$journal_data_gp['sales_person_id'] = $this->session->userdata('login_user_id');

						//INSERT NOW
						$this->db->insert('general_journal', $journal_data_gp);

						//FOR GENERAL JOURNAL ENTRY (ACCOUNT PAYABLE) CREDIT THIS

						$journal_data_ap['timestamp'] = strtotime($this->input->post('order_date'));
						$journal_data_ap['date_timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));
						$journal_data_ap['date'] = $this->input->post('order_date');
						$journal_data_ap['supplier_id'] = $this->input->post('order_from');
						$journal_data_ap['journal'] = 'Purchases';
						$journal_data_ap['po_code'] = $this->input->post('purchase_order_no');
						$journal_data_ap['account_name'] = 'Accounts Payable';
						$journal_data_ap['account_balance'] = $acp_balance;
						$journal_data_ap['credit_amount'] = $this->input->post('hidden_total');
						$journal_data_ap['reference'] = '';
						$journal_data_ap['description'] = 'Purchases from ' . $this->db->get_where('suppliers', array('supplier_id' => $journal_data_ap['supplier_id']))->row()->supplier_name;
						$journal_data_ap['sales_person_id'] = $this->session->userdata('login_user_id');

						//INSERT NOW
						$this->db->insert('general_journal', $journal_data_ap);

						//Let's insert data into accounts payable table
						//FOR ACCOUNTS PAYABLE TABLE
						$accounts_payable['po_code'] = $this->input->post('purchase_order_no');
						$accounts_payable['supplier_id'] = $this->input->post('order_from');
						$accounts_payable['amount'] = $this->input->post('hidden_total');
						$accounts_payable['amount_paid'] = $this->input->post('amount_paid');
						$accounts_payable['amount_due'] = $this->input->post('hidden_payment_balance');
						$accounts_payable['account_id'] = $this->input->post('paid_from');
						//$accounts_payable['p_prev_paid'] = $this->input->post('amount_paid');
						//$accounts_payable['prev_paid'] = $this->input->post('amount_paid');
						$accounts_payable['creation_timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));

						if ($this->input->post('amount_paid') != 0) {
							$accounts_payable['payment_timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));
						}

						$accounts_payable['track_code'] = $paid_data['track_code'];
						$accounts_payable['date'] = $this->input->post('order_date');
						$accounts_payable['timestamp'] = strtotime($this->input->post('order_date'));

						if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
							$accounts_payable['status'] = 'Unpaid';
						} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
							$accounts_payable['status'] = 'Partially Paid';
						} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
							$accounts_payable['status'] = 'Paid';
						}

						//insert now
						$this->db->insert('accounts_payable', $accounts_payable);

						//update payable balance
						$payable_diff = $this->input->post('hidden_total') - $this->input->post('amount_paid');
						//update now
						/*$this->db->where('name', 'Accounts Payable');
	                        $this->db->set('current_balance', 'current_balance +'. $payable_diff, FALSE);
						*/

						$acpp_balance = $this->db->get_where('accounts', array('name' => 'Accounts Payable'))->row()->current_balance;

						if ($this->input->post('amount_paid') > 0) {

							//Let's insert data into payment table
							//FOR PAYMENT TABLE
							$payment_data['payment_type'] = 'Payable';
							$payment_data['po_code'] = $this->input->post('purchase_order_no');
							$payment_data['supplier_id'] = $this->input->post('order_from');
							$payment_data['amount'] = $this->input->post('amount_paid');
							$payment_data['due'] = $this->input->post('hidden_payment_balance');
							$payment_data['timestamp'] = strtotime($this->input->post('order_date'));
							$payment_data['day_timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));
							$payment_data['track_code'] = $paid_data['track_code'];
							$payment_data['date'] = $this->input->post('order_date');
							$payment_data['account_id'] = $this->input->post('paid_from');
							$payment_data['issuer_id'] = $this->session->userdata('login_user_id');

							//insert now
							$this->db->insert('payment', $payment_data);
							$payment_id = $this->db->insert_id();

							//FOR PAYMENT FOR PURCHASES ORDER

							//FOR GENERAL JOURNAL ENTRY (ACCOUNT PAYABLE) DEBIT THIS

							$journal_data_payment_ap['payment_id'] = $payment_id;
							$journal_data_payment_ap['timestamp'] = strtotime($this->input->post('order_date'));
							$journal_data_payment_ap['date_timestamp'] = strtotime(date($this->input->post('order_date') . ' H:i:s'));
