							$journal_data_payment_ac['credit_amount'] = $this->input->post('amount_paid');
							$journal_data_payment_ac['reference'] = '';
							$journal_data_payment_ac['description'] = 'Payment for order ' . $this->input->post('purchase_order_no');
							$journal_data_payment_ac['sales_person_id'] = $this->session->userdata('login_user_id');

							//UPDATE NOW
							/** $account_names_array = array(
							'General Products Purchased',
