							);

							$this->db->where_not_in('account_name', $account_names_array);**/
							$journal_id = $this->db->get_where('payment', array('payment_id' => $payment_id))->row()->journal_id;
							$this->db->where('journal_id', $journal_id);
							$this->db->where('po_code', $po_code);
