							$journal_data_payment_ac['account_name'] = $this->db->get_where('accounts', array('account_id' => $this->input->post('paid_from')))->row()->name;
							$journal_data_payment_ac['credit_amount'] = $this->input->post('amount_paid');
							$journal_data_payment_ac['reference'] = '';
							$journal_data_payment_ac['description'] = 'Payment for order ' . $this->input->post('purchase_order_no');
							$journal_data_payment_ac['sales_person_id'] = $this->session->userdata('login_user_id');

							$this->db->insert('general_journal', $journal_data_payment_ac);
							$journal_id = $this->db->insert_id();

							//update payment table with this id
							$this->db->where('payment_id', $payment_id);
							$this->db->set('journal_id', $journal_id);
							$this->db->update('payment');
						}

						//update the general products purchased account
						//subtract
						/** $this->db->where('name', 'General Products Purchased');
						$this->db->set('current_balance', 'current_balance - ' . $products_purchases['current_balance'], FALSE);
						$this->db->update('accounts');

						//update now - add
						$products_purchases_adjusted['current_balance'] = $this->input->post('hidden_total');
						$this->db->where('name', 'General Products Purchased');
						$this->db->set('current_balance', 'current_balance + ' . $products_purchases_adjusted['current_balance'], FALSE);
						$this->db->update('accounts'); **/

						//CHECK IF THERE IS A CHANGE IN THE ACCOUNT PAID TO
						if ($account_used != $this->input->post('paid_from')) {
							//a different account is chosen. Reduce the amount paid to that account before proceeding with the new entry
							//update previous account paid from - add to it
							if ($account_used != 0) {
								$account_paid_from_data['current_balance'] = $amount_paid_earlier;
								$this->db->where('account_id', $account_used);
