					/*$accounts_payable_account_payment['current_balance'] = $this->input->post('amount_paid');
	                        $this->db->where('name', 'Accounts Payable');
	                        $this->db->set('current_balance', 'current_balance -'. $accounts_payable_account_payment['current_balance'], FALSE);
*/

					//update supplier column in the suppliers table
					$supplier_id = $p_order_create_data['supplier_id'];

					//update supplier's address if there is a change in the address
					$supplier_address['address'] = $this->input->post('vendor_address');
