//**PRO FORMA INVOICE CREATION, UPDATES AND DELETION**/
	function create_proforma_invoice($param1 = '', $param2 = '', $param3 = '', $param4 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'create') {

			$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			//imported ids array
			$input_ids_numeric = explode('-', $param2);

			//FOR SALES ORDER TABLE
			$s_order_create_data['so_code'] = $this->input->post('order_no');
			$s_order_create_data['customer_name'] = $this->input->post('order_to');
			$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
			$s_order_create_data['timestamp'] = strtotime(date('d-m-Y H:i:s'));
			$s_order_create_data['date'] = $this->input->post('order_date');
			$s_order_create_data['customer_address'] = $this->input->post('bill_to');
			$s_order_create_data['comment'] = $this->input->post('comments');
			$s_order_create_data['track_code'] = $paid_data['track_code'];
			$s_order_create_data['private_comment'] = $this->input->post('private_comments');
			$s_order_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			//check if today's date is selected
			if ($s_order_create_data['date_timestamp'] !== strtotime(date('d-m-Y'))) {
				$errors['mismatch_date'] = 'Creation date error. It seems your selected date is not for today. Please check and try again.';
			}

			//check if any required field is empty
			if (empty($s_order_create_data['so_code'])) {
				$errors['so_code'] = 'SO Number cannot be empty';
			}

			if (empty($s_order_create_data['customer_name'])) {
				$errors['customer_name'] = 'You must enter a customer';
			}

			if (empty($s_order_create_data['date'])) {
				$errors['date'] = 'Order Date cannot be empty';
			}

			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				//collect data for each item bought
				for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

					$s_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
					$s_order_create_data['item_name'] = strtoupper($this->input->post('order_item_' . $input_ids_numeric[$i]));
					$s_order_create_data['item_description'] = strtoupper($this->input->post('description_td_' . $input_ids_numeric[$i]));
					$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
					$s_order_create_data['grand_total'] = $this->input->post('hidden_total');
					$s_order_create_data['html_id'] = $input_ids_numeric[$i];
					$s_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);
					$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
					$s_order_create_data['quantity_due'] = $s_order_create_data['quantity'] - $s_order_create_data['quantity_picked'];

					$s_order_create_data['amount_paid'] = $this->input->post('amount_paid');
					$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance');
					$s_order_create_data['total_quantity'] = $this->input->post('hidden_total_quantity');

					if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
						$s_order_create_data['status'] = 'Unpaid';
					} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
						$s_order_create_data['status'] = 'Partially Paid';
					} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
						$s_order_create_data['status'] = 'Paid';
					}

					//check if any required field is empty
					if (empty($s_order_create_data['quantity'])) {
						$errors['quantity'] = 'Order Quantity cannot be empty';
					}

					if (empty($s_order_create_data['item_name'])) {
						$errors['item_name'] = 'You must select an Item';
					}

					if (empty($s_order_create_data['amount'])) {
						$errors['amount'] = 'Total amount cannot be empty';
					}

					//if there's error
					if (!empty($errors)) {
						//error found, let's notify the user of it
						$ajax_data = $errors;
						echo json_encode($ajax_data);
					} else {
						//No error found, now we can insert data
						$this->db->insert('proforma_invoice_order', $s_order_create_data);

					}

				}
			} //End of loop

			if (empty($errors)) {

				//Let's insert data into accounts receivable table
				//FOR ACCOUNTS RECEIVABLE TABLE
				$invoice['so_code'] = $this->input->post('order_no');
				$invoice['customer_name'] = $this->input->post('order_to');
				$invoice['amount'] = $this->input->post('hidden_total');
				$invoice['amount_paid'] = $this->input->post('amount_paid');
				$invoice['amount_due'] = $this->input->post('hidden_payment_balance');
				$invoice['account_id'] = $this->input->post('paid_to');
				$invoice['invoice_code'] = $this->input->post('invoice_code');
				//$invoice['p_prev_paid'] = $this->input->post('amount_paid');
				//$invoice['prev_paid'] = $this->input->post('amount_paid');
				$invoice['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$invoice['timestamp'] = strtotime($this->input->post('order_date'));

				if ($this->input->post('amount_paid') != 0) {
					$invoice['payment_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				}

				$invoice['date'] = $this->input->post('order_date');
				$invoice['track_code'] = $paid_data['track_code'];
				$invoice['sales_person_id'] = $this->session->userdata('login_user_id');

				if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
					$invoice['status'] = 'Unpaid';
				} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
					$invoice['status'] = 'Partially Paid';
				} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
					$invoice['status'] = 'Paid';
				}

				//insert now
				$this->db->insert('proforma_invoice', $invoice);

				////return now
				$ajax_data['success'] = true;
				echo json_encode($ajax_data);
			}
		}

	}


	//**SALES ORDER POS CREATION, UPDATES AND DELETION**/
	function sales_order_pos($param1 = '', $param2 = '', $param3 = '', $param4 = '', $param5 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'create') {

			$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			//imported ids array
			$input_ids_numeric = explode('-', $param2);

			$payment_ids = explode('-', $param3);
			sort($payment_ids);

			//FOR SALES ORDER TABLE
			$s_order_create_data['so_code'] = $this->input->post('order_no_pos');
			$s_order_create_data['customer_id'] = $this->input->post('order_to_pos');
			$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date_pos'));
			$s_order_create_data['timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
			$s_order_create_data['date'] = $this->input->post('order_date_pos');
			$s_order_create_data['comment'] = $this->input->post('comments');
			$s_order_create_data['track_code'] = $paid_data['track_code'];
			$s_order_create_data['private_comment'] = $this->input->post('private_comments');
			$s_order_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			$s_order_create_data['discount'] = $this->input->post('discount_pos');


			//check if today's date is selected
			if ($s_order_create_data['date_timestamp'] !== strtotime(date('d-m-Y'))) {
				 // $errors['mismatch_date'] = '<p>Creation date error. It seems your selected date is not for today. Back-dated transactions are also not allowed! Please check and try again.</p><p>If you think this is an error, then contact the system administrator for assistance</p>';
			}


			//check if any required field is empty
			if (empty($s_order_create_data['so_code'])) {
				$errors['so_code'] = 'SO Number cannot be empty';
			}

			if (!empty($this->input->post('amount_tendered_pos')) && $this->input->post('amount_paid_pos') != 0) {
				if ($this->input->post('amount_tendered_pos') < $this->input->post('amount_paid_pos')) {
					$errors['invalid_payment'] = 'Amount Tendered cannot be less than amount paid!';
				}
			}

			if (!empty($this->input->post('amount_tendered_pos'))) {
				if ($this->input->post('amount_paid_pos') < 1) {
					$errors['invalid_amount_paid'] = 'Amount Paid is invalid! Use a positive number or a number greater than zero.';
				}
			}

			if (empty($s_order_create_data['customer_id'])) {
				$errors['customer_id'] = 'You must select a customer';
			}

			if (empty($s_order_create_data['date'])) {
				$errors['date'] = 'Order Date cannot be empty';
			}

			if (!validate_so_no($s_order_create_data['so_code'])) {
				$errors['invalid_so_code'] = 'The Sales Order Code [' . $s_order_create_data['so_code'] . '] is invalid. Please check the correct format in System Settings >> Company.';
			}

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$s_item_ids = array();
			$s_counter2 = 0;
			$s_item_ids2 = array();

			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$s_quantity = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
				$s_quantity_picked = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
				$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

				$quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->quantity;
				

				//checking to see if this item is sold in unit or ton
				$item_unit_id = $this->input->post('item_unit_id_' . $input_ids_numeric[$i]);

				if($item_unit_id > 0) {

					$unit_quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->unit_quantity;

					if ($s_quantity_picked > $unit_quantity_left && $quantity_left < 1) { //if unit quantity left is less than total being picked and also main package quantity is zero, then we can't sell this item now.
						$s_counter2++;
						array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
					}
				}

				

				if ($s_quantity_picked > $s_quantity) {
					$s_counter++;
					array_push($s_item_ids, $s_item_id);
				}
			}

			if ($s_counter > 0) {
				$errors['over'] = 'Quantity picked for some items are more than the quantity bought. Please check and try again!.';
			}

			//if($item_unit_id == '' || $item_unit_id == null || empty($item_unit_id)) {
				//if it is a unit sales, skip this error
				if ($s_counter2 > 0) {
					$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transaction.';
					//$errors['item_ids'] = $s_item_ids2
				}
			//}

			//check for duplicate

			if (!s_order_validation_insert($s_order_create_data['so_code'])) {

				$ajax_data['success'] = 'duplicate';
				$ajax_data['duplicate'] = 'Duplicate found: Sales Order with the same SO No [' . $s_order_create_data['so_code'] . '] already exists';
				echo json_encode($ajax_data);
			} else if (!invoice_code_validation_insert($this->input->post('invoice_code_pos'))) {

				$ajax_data['success'] = 'duplicate';
				$ajax_data['duplicate'] = 'Duplicate found: Invoice Code [' . $this->input->post('invoice_code_pos') . '] already exists';
				echo json_encode($ajax_data);
			} else {
				if (!empty($errors)) {
					//error found, let's notify the user of it
					$ajax_data = $errors;
					echo json_encode($ajax_data);
				} else {

					$priceData = [];
					$batchPriceData = [];
					$customer_id = $s_order_create_data['customer_id'];

					$priceData['customer_id'] = $customer_id ;

					//collect data for each item bought
					for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

						$s_order_create_data['order_item_has_unit_sales'] = '0';
						$s_order_create_data['bundle_quantity'] = '0';
						$s_order_create_data['bundle_price'] = '0';
						$s_order_create_data['unit_id'] = NULL;
						/*
							** 0 = Not sold in unit but in package eg bags
							** 1 = Sold in unit eg from box to pound (nails)
							** 2 = Bought the item in unit:pieces and decides to sell in bundle. eg Iron rods are bought in pieces but can be sold in ton
						*/

						$isInTon = $this->input->post('isInTon_' . $input_ids_numeric[$i]);
						//checking to see if this item is sold in unit
						$item_unit_id = $this->input->post('item_unit_id_' . $input_ids_numeric[$i]);

						if($isInTon == 'yes') { //we are selling this item in ton - from pieces to bundle
							$s_order_create_data['unit_id'] = $this->input->post('ton_item_unit_id_' . $input_ids_numeric[$i]);
							$s_order_create_data['bundle_quantity'] = $this->input->post('order_bundle_quantity_' . $input_ids_numeric[$i]);
							$s_order_create_data['bundle_price'] = $this->input->post('order_bundle_price_' . $input_ids_numeric[$i]);
							$s_order_create_data['order_item_has_unit_sales'] = '2';

						} //end of ton


						$s_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
						$s_order_create_data['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);
						$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
						$s_order_create_data['grand_total'] = $this->input->post('hidden_total_pos');
						$s_order_create_data['html_id'] = $input_ids_numeric[$i];
						$s_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);
						$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);

						$s_order_create_data['quantity_due'] = $s_order_create_data['quantity'] - $s_order_create_data['quantity_picked'];

						//FOR STOCK RECORDS TABLE
						/*if($item_unit_id == '') { //we don't do this with items sold in smaller units
							$stock_records['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);
							$stock_records['supplier_id'] = $this->input->post('item_supplier_id_' . $input_ids_numeric[$i]);
							$stock_records['so_code'] = $s_order_create_data['so_code'];
							$stock_records['date'] = $s_order_create_data['date'];
							$stock_records['q_sold'] = $s_order_create_data['quantity_picked'];

							//to update the item balance, let's get recent entry into the stock record table
							$this->db->select_max('record_id');
							$this->db->where('item_id', $stock_records['item_id']);
							$this->db->where('supplier_id', $stock_records['supplier_id']);
							$last_record_id = $this->db->get('stock_record')->row()->record_id;
							$item_balance_record = $this->db->get_where('stock_record', ['record_id' => $last_record_id])->row()->item_balance;

							$stock_records['item_balance'] = $item_balance_record - $s_order_create_data['quantity_picked'];
							$stock_records['selling_price'] = $s_order_create_data['price'];
							$stock_records['timestamp'] = $s_order_create_data['timestamp'];
						}*/


						

						//item sold in unit
						if($item_unit_id > 0) {

							/*start if item unit transfer adjustment*/
							$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);
							$s_order_create_data['unit_id'] = $item_unit_id;

							//we need to check and see if we have some of this item left in the unit_transfer table
							//this will inform us whether we need to transfer another quantity or continue to sell from the previous transfer made
							$this->db->order_by('transfer_id', 'desc');
							$unit_transfer_query = $this->db->get_where('unit_transfer', [
								'item_id' => $item_id, 'unit_id' => $item_unit_id
							]);
							$unit_quantity = $this->crud_model->getItemUnitQuantity($item_id, $item_unit_id);

							//let's see if the item is in stock
							$item_quantity_avail = $this->crud_model->getItemBalance($item_id);

							if($unit_transfer_query->num_rows() < 1) {

								if($item_quantity_avail > 0) { //we have some packages so we can transfer for the unit sales
									//this is the first time we will transfer item there
									$transferData['item_id'] = $item_id;
									$transferData['unit_id'] = $item_unit_id;
									$transferData['package_quantity'] = 1;
									$transferData['unit_quantity'] = $unit_quantity;
									$transferData['package_quantity_balance'] = 1;
									$transferData['unit_quantity_balance'] = $unit_quantity;
									$transferData['transfer_date'] = date('Y-m-d h:i:s');

									$this->db->insert('unit_transfer', $transferData);
									$transfer_id = $this->db->insert_id();

									//reduce the main item quantity by 1
									$this->db->where('item_id', $item_id);
									$this->db->set('quantity', 'quantity - 1', false);
									$this->db->update('items');

									//update the current entry of the item unit balance and package balances
									$this->db->where('transfer_id', $transfer_id);
									$this->db->set('unit_quantity_balance', 'unit_quantity_balance - ' . $s_order_create_data['quantity_picked'], false);
									$this->db->update('unit_transfer');

								} else {

									$errors['unit_item_outofstiock'] = 'The items you are selling in unit are out of stock';

									$ajax_data = $errors;
									echo json_encode($ajax_data);
									return false;
								}
								

							} else {
								//not the first time, so item transfer transaction exists
								//let's get the last row
								$unit_transfer_row = $this->db->get_where('unit_transfer', [
									'item_id' => $item_id, 'unit_id' => $item_unit_id
								])->last_row();

								//if the current unit quantity is not enough,then we need to set it off and transfer another
								$available_unit_q = $unit_transfer_row->unit_quantity_balance;
								$prev_transfer_id = $unit_transfer_row->transfer_id;
								


								if($available_unit_q < $s_order_create_data['quantity_picked']) {

									if($item_quantity_avail < 1) { 
										$errors['quantity_not_enough'] = 'Some items you are selling in unit seem to be out of stock. Restock and try again';

										$ajax_data = $errors;
										echo json_encode($ajax_data);
										return false;
									}

									$balance = $s_order_create_data['quantity_picked'] - $available_unit_q;

									//it's not enough so lets transfer another quantity
									$transferData['item_id'] = $item_id;
									$transferData['unit_id'] = $item_unit_id;
									$transferData['package_quantity'] = 1;
									$transferData['unit_quantity'] = $unit_quantity;
									$transferData['package_quantity_balance'] = 1;
									$transferData['unit_quantity_balance'] = $unit_quantity;
									$transferData['transfer_date'] = date('Y-m-d h:i:s');

									$this->db->insert('unit_transfer', $transferData);
									$current_transfer_id = $this->db->insert_id();

									//reduce the main item quantity by 1
									$this->db->where('item_id', $item_id);
									$this->db->set('quantity', 'quantity - 1', false);
									$this->db->update('items');

									//let's update the transfer table now

									//update the previous entry of the item unit balance and package balances to 0

									$this->db->where('transfer_id', $prev_transfer_id);
									$this->db->set('package_quantity_balance', 0);
									$this->db->set('unit_quantity_balance', 0);
									$this->db->update('unit_transfer');

									//update the current entry of the item unit balance and package balances
									$this->db->where('transfer_id', $current_transfer_id);
									$this->db->set('unit_quantity_balance', 'unit_quantity_balance - '. $balance, false);
									$this->db->update('unit_transfer');


								} else {

									if($available_unit_q == $s_order_create_data['quantity_picked']) {
										//if they are equall, set balances to 0
										$this->db->where('transfer_id', $prev_transfer_id);
										$this->db->set('package_quantity_balance', 0);
										$this->db->set('unit_quantity_balance', 0);
										$this->db->update('unit_transfer');
									} else {

										//let's update the transfer table now 
										$this->db->where('transfer_id', $prev_transfer_id);
										$this->db->set('unit_quantity_balance', 'unit_quantity_balance - '. $s_order_create_data['quantity_picked'], false);
										$this->db->update('unit_transfer');
									}

									
								}
							} /*end if item unit transfer adjustment*/

							$s_order_create_data['order_item_has_unit_sales'] = '1'; //data for sales order table and payment with goods table

							//collect the data for the items_in_units_order table
							$unitOrderData['customer_id'] = $customer_id;
							$unitOrderData['item_id'] = $item_id;
							$unitOrderData['unit_id'] = $item_unit_id;
							$unitOrderData['quantity'] = $s_order_create_data['quantity_picked'];
							$unitOrderData['unit_price'] = $s_order_create_data['price'];
							$unitOrderData['total_amount'] = $s_order_create_data['quantity'] * $unitOrderData['unit_price'];

							$unitOrderData['unit_balance'] = $this->crud_model->getUnitItemBalance($item_id);

							$unitOrderData['sales_order_code'] = $s_order_create_data['so_code'];
							$unitOrderData['updated_date'] = date('Y-m-d h:i:s');
							$unitOrderData['timestamp'] = date('Y-m-d', strtotime($this->input->post('order_date_pos')));

							$this->db->insert('items_in_units_order', $unitOrderData);

							//update the unit quantity
							$this->db->where('item_id', $item_id);
							$this->db->set('unit_quantity', $unitOrderData['unit_balance']);
							$this->db->update('items');

						}
						//end of item sold in unit						

						$s_order_create_data['amount_paid'] = $this->input->post('amount_paid_pos');
						$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance_pos');
						$s_order_create_data['total_quantity'] = $this->input->post('hidden_total_quantity_pos');

						if ($this->input->post('amount_paid_pos') == 0 || $this->input->post('amount_paid_pos') == 0.00) {
							$s_order_create_data['type_of_sales'] = 'Receivables';
							$s_order_create_data['status'] = 'Unpaid';
						} else if ($this->input->post('amount_paid_pos') < $this->input->post('hidden_total_pos')) {
							$s_order_create_data['status'] = 'Partially Paid';
							$s_order_create_data['type_of_sales'] = 'Receivables';
						} else if ($this->input->post('amount_paid_pos') === $this->input->post('hidden_total_pos')) {
							$s_order_create_data['status'] = 'Paid';
							$s_order_create_data['type_of_sales'] = 'Cash';

							if($s_order_create_data['quantity_due'] > 0) {
								$s_order_create_data['type_of_sales'] = 'Payables';
							}
						}


						//check if any required field is empty
						if (empty($s_order_create_data['quantity'])) {
							$errors['quantity'] = 'Order Quantity cannot be empty';
						}

						if (empty($s_order_create_data['item_id'])) {
							$errors['item_id'] = 'You must select an Item';
						}

						if (empty($s_order_create_data['amount'])) {
							$errors['amount'] = 'Total amount cannot be empty';
						}

						//if there's error
						if (!empty($errors)) {
							//error found, let's notify the user of it
							$ajax_data = $errors;
							echo json_encode($ajax_data);
						} else {
							//No error found, now we can insert data
							$this->db->insert('sales_order', $s_order_create_data);

							//get s order id
							$so_id = $this->db->insert_id();

							//for stock record
							//$this->db->insert('stock_record', $stock_records);
							

							//update item table
							$item_data['quantity'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
							$item_data['last_used_timestamp'] = strtotime($this->input->post('order_date_pos2'));
							$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

							//do update now
							if($item_unit_id == '' || $item_unit_id == null || empty($item_unit_id)) {
								//we only update item if this item is not sold in unit, else we take care of this at the top already

								$this->db->where('item_id', $item_id);
								$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
								$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
								$this->db->update('items');
							}
							

							//let's get the current total quantity
							$item_current_query = $this->db->get_where('items', array('item_id' => $item_id))->row();
							$current_quantity = $item_current_query->quantity;
							$current_cost_price = $item_current_query->purchase_price;

							//let's update the sales order table with it
							$this->db->where('so_id', $so_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('sales_order');

							//if($s_order_create_data['quantity_due'] > 0) {//only if quantity due is greater than 0
							//into the payment with goods table
							if ($s_order_create_data['quantity_due'] > 0) {
								$s_order_create_data['negative_or_goods'] = 'goods';
							}
							$this->db->insert('payment_with_goods', $s_order_create_data);
							//get sg order id
							$sog_id = $this->db->insert_id();

							$this->db->where('so_id', $sog_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('payment_with_goods');

							//RESET IT TO NULL SO THAT SALES ORDER TABLE WOULD NOT USE THE ALLOCATED VALUE AT THE TOP
							$s_order_create_data['negative_or_goods'] = NULL;
							//}

						}

						//checking if this item exists in the prices table for this customer
						$price_data_row = $this->db->get_where('items_prices', ['item_id' => $item_id, 'customer_id' => $customer_id])->num_rows();
						 if($price_data_row < 1) {
						 	//does not exist
						 	$priceData['item_id'] = $item_id;
						 	$priceData['item_price'] = $s_order_create_data['price'];

						 	$hasUnisSales = $this->db->get_where('items', ['item_id' => $item_id])->row()->item_sold_in_units;

						 	if($hasUnisSales == 1) {
						 		//if this item is sold in unit, get the main price and insert it into the items_prices table instead
						 		$priceData['item_price'] = $this->db->get_where('items', ['item_id' => $item_id])->row()->selling_price;

					 	}
					 	

					 	$batchPriceData[] = $priceData;
					 }

				} //End of loop

				if (empty($errors)) {

					if($price_data_row < 1) {
						//insert into items_prices table
						$this->db->insert_batch('items_prices', $batchPriceData);
					}

					//update general sales account (credit)
					$general_sales['current_balance'] = $this->input->post('hidden_total_pos');
					$this->db->where('name', 'General Sales');
					$this->db->set('current_balance', 'current_balance + ' . $general_sales['current_balance'], FALSE);
					$this->db->update('accounts');

					//get total account balance for General Sales
					$gs_balance = $this->db->get_where('accounts', array('name' => 'General Sales'))->row()->current_balance;

					//get total account balance for Accounts Receivable
					$this->db->where('name', 'Accounts Receivable');
					$this->db->set('current_balance', 'current_balance +' . $general_sales['current_balance'], FALSE);
					$this->db->update('accounts');

					$acr_balance = $this->db->get_where('accounts', array('name' => 'Accounts Receivable'))->row()->current_balance;

					//FOR SALES ORDER
					//FOR GENERAL JOURNAL ENTRY (GENERAL SALES) DEBIT THIS
					$journal_data_gs['timestamp'] = strtotime($this->input->post('order_date_pos'));
					$journal_data_gs['date_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
					$journal_data_gs['date'] = $this->input->post('order_date_pos');
					$journal_data_gs['customer_id'] = $this->input->post('order_to_pos');
					$journal_data_gs['journal'] = 'Sales';
					$journal_data_gs['so_code'] = $this->input->post('order_no_pos');
					$journal_data_gs['invoice_code'] = $this->input->post('invoice_code_pos');
					$journal_data_gs['account_name'] = 'General Sales';
					$journal_data_gs['account_balance'] = $gs_balance;
					$journal_data_gs['credit_amount'] = $this->input->post('hidden_total_pos');
					$journal_data_gs['reference'] = '';
					$journal_data_gs['description'] = 'Sales to ' . $this->db->get_where('customers', array('customer_id' => $journal_data_gs['customer_id']))->row()->customer_name;
					$journal_data_gs['sales_person_id'] = $this->session->userdata('login_user_id');

					//INSERT NOW
					$this->db->insert('general_journal', $journal_data_gs);

					//FOR GENERAL JOURNAL ENTRY (ACCOUNT RECEIVABLE) DEBIT THIS
					$journal_data_ar['timestamp'] = strtotime($this->input->post('order_date_pos'));
					$journal_data_ar['date_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
					$journal_data_ar['date'] = $this->input->post('order_date_pos');
					$journal_data_ar['customer_id'] = $this->input->post('order_to_pos');
					$journal_data_ar['journal'] = 'Sales';
					$journal_data_ar['so_code'] = $this->input->post('order_no_pos');
					$journal_data_ar['invoice_code'] = $this->input->post('invoice_code_pos');
					$journal_data_ar['account_name'] = 'Accounts Receivable';
					$journal_data_ar['account_balance'] = $acr_balance;
					$journal_data_ar['debit_amount'] = $this->input->post('hidden_total_pos');
					$journal_data_ar['reference'] = '';
					$journal_data_ar['description'] = 'Sales to ' . $this->db->get_where('customers', array('customer_id' => $journal_data_ar['customer_id']))->row()->customer_name;
					$journal_data_ar['sales_person_id'] = $this->session->userdata('login_user_id');

					//INSERT NOW
					$this->db->insert('general_journal', $journal_data_ar);

					//Let's insert data into accounts receivable table
					//FOR ACCOUNTS RECEIVABLE TABLE
					$invoice['so_code'] = $this->input->post('order_no_pos');
					$invoice['customer_id'] = $this->input->post('order_to_pos');
					$invoice['amount'] = $this->input->post('hidden_total_pos');
					$invoice['amount_paid'] = $this->input->post('amount_paid_pos');
					$invoice['amount_due'] = $this->input->post('hidden_payment_balance_pos');
					//$invoice['account_id'] = $this->input->post('paid_to_pos');
					$invoice['invoice_code'] = $this->input->post('invoice_code_pos');
					//$invoice['p_prev_paid'] = $this->input->post('amount_paid_pos');
					//$invoice['prev_paid'] = $this->input->post('amount_paid_pos');
					$invoice['creation_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
					$invoice['timestamp'] = strtotime($this->input->post('order_date_pos'));

					$invoice['discount'] = $this->input->post('discount_pos');

					if ($this->input->post('amount_paid_pos') != 0) {
						$invoice['payment_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
					}

					$invoice['date'] = $this->input->post('order_date_pos');
					$invoice['track_code'] = $paid_data['track_code'];
					$invoice['sales_person_id'] = $this->session->userdata('login_user_id');

