			//let's check if it is a normal update. If it is, we need to check if this so order has received more than one payment. If so, we nned to deny the update untill one of the payment transactions is deleted
			
			$payment_rows_query = $this->db->get_where('payment', array('so_code' => $so_code));

			$payment_rows = $payment_rows_query->num_rows();
			$old_payment_methods = array_column($payment_rows_query->result_array(), 'account_id');

			if ($payment_rows > count($old_payment_methods)) {
				$errors['so_update'] = 'This Sales Order Code [' . $so_code . '] is associated with more than one payment. Any update to it will cause discrepancies in your accounts. To do an update, kindly go to View Payments and delete all related payments with this SO CODE.';
			}

			//FOR SALES ORDER TABLE
			$s_order_create_data['so_code'] = $this->input->post('order_no');
			$s_order_create_data['customer_id'] = $this->input->post('order_to');
			//$s_order_create_data['timestamp'] = strtotime(date('d-m-Y H:i:s'));
			
			
			//$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
			//$s_order_create_data['date'] = $this->input->post('order_date');
			$s_order_create_data['comment'] = $this->input->post('comments');
			$s_order_create_data['track_code'] = $track_code;
			$s_order_create_data['private_comment'] = $this->input->post('private_comments');
			$s_order_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			$s_order_create_data['discount'] = $this->input->post('discount');

			$invoice_row = $this->db->get_where('invoice', array('so_code' => $so_code, 'invoice_code' => $this->input->post('invoice_code')))->row();
			
			$invoice_code = $invoice_row->invoice_code;
			$invoice_id = $invoice_row->invoice_id;

			$amount_received_earlier = $this->db
				->where('so_code', $so_code)
				->get('sales_order')->first_row()->amount_paid;

			//check the previous amount paid
			$sOrderQuery = $this->db->get_where('sales_order', array('so_code' => $so_code))->row();
			$account_adjust['current_balance'] = $sOrderQuery->amount_paid;
			//update general products sales account
			//get the earlier balance and subtract it before effecting the new update
			$journal_adjust['current_balance'] = $sOrderQuery->grand_total;

			//get previous prev_paid amount from the accounts_payable table
			//$prev_paid['prev_paid'] = $this->db->get_where('invoice', array('so_code' => $so_code, 'customer_id' => $s_order_create_data['customer_id']))->row()->prev_paid;

			//get the earlier balance and subtract it before effecting the new update
			//$receivable_adjust_paid['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->amount_paid;
			//$receivable_adjust['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->grand_total;

			//check if any required field is empty
			$user_level = $this->db->get_where('admin', array('admin_id' => $this->session->userdata('admin_id')))->row()->level;
			if ($user_level > 2) {
				if ($dateTimestamp != $today) {
					$errors['outdated'] = 'Sorry! You cannot edit an entry that is a day old. Contact your system Administrator.';
				}
			}

			if (empty($s_order_create_data['so_code'])) {
				$errors['so_code'] = 'SO Number cannot be empty';
			}

			if (empty($s_order_create_data['customer_id'])) {
				$errors['customer_id'] = 'You must select a customer';
			}

			if (empty($s_order_create_data['date'])) {
				//$errors['date'] = 'Order Date cannot be empty';
			}

			if ($param4 != 'goods') {
				if (!validate_so_no($s_order_create_data['so_code'])) {
					$errors['invalid_so_code'] = 'The Sales Order Code [' . $s_order_create_data['so_code'] . '] is invalid. Please check the correct format in System Settings >> Company.';
				}
			}

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$s_item_ids = array();
			$s_counter2 = 0;
			$s_item_ids2 = array();
			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$s_quantity = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
				$s_quantity_picked = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
				$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

				//previous quantity
				$previousOrderQuery = $this->db->get_where('sales_order', array('so_code' => $so_code, 'item_id' => $s_item_id))->row();
				$s_quantity_prev = $previousOrderQuery->quantity;

				$actual_item_q = $s_quantity - $s_quantity_prev;

				$quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->quantity;


				//checking to see if this item is sold in unit or ton
				$item_unit_id = $previousOrderQuery->unit_id;
				//$customerId = $previousOrderQuery->customer_id;

				if($item_unit_id > 0) { /*if item was sold in unit*/

					$unit_quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->unit_quantity;
					
					/*$prevUnitQuantity = $this->db->get_where('items_in_units_order', array('so_code' => $so_code, 'item_id' => $s_item_id, 'unit_id' => $item_unit_id, 'customer_id' => $customerId))->row()->quantity;*/


					//if unit quantity left is less than total being picked and also main package quantity is zero, then we can't sell this item now.
					if ($actual_item_q > $unit_quantity_left && $quantity_left < 1) {
						$s_counter2++;
						array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
					}

					if ($s_quantity_picked > $s_quantity) {
						$s_counter++;
						array_push($s_item_ids, $s_item_id);
					}
					
				} else { /*item was sold in pack*/

					if ($actual_item_q > $quantity_left) {
						$s_counter2++;
						array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
					}

					if ($s_quantity_picked > $s_quantity) {
						$s_counter++;
						array_push($s_item_ids, $s_item_id);
					}
				}
			}

			if ($s_counter > 0) {
				$errors['over'] = 'Quantity picked for some items are more than the quantity bought. Please check and try again!.';
			}

			if ($s_counter2 > 0) {
				$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transaction.';
				//$errors['item_ids'] = $s_item_ids2
			}

			//check for duplicate
			/**if(!p_order_validation_update($this->input->post('order_no'))) {

	                    $ajax_data['success'] = 'duplicate';
	                    $ajax_data['so_code'] = $s_order_create_data['so_code'];
	                    echo json_encode($ajax_data);
			*/
			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				//collect data for each item bought
				for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

					$s_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);

					$s_order_create_data['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);

					$s_order_create_data['html_id'] = $input_ids_numeric[$i];
					$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
					$s_order_create_data['quantity_due'] = $s_order_create_data['quantity'] - $s_order_create_data['quantity_picked'];

					$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
					$s_order_create_data['grand_total'] = $this->input->post('hidden_total');
					$s_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);

					$s_order_create_data['amount_paid'] = $this->input->post('amount_paid');
					$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance');

					$s_order_create_data['total_quantity'] = $this->input->post('hidden_total_quantity');

					if ($param4 == 'goods') {
						
						//do this if request is coming from payment with goods edit page
						$s_order_create_data['amount_paid'] = $this->input->post('hidden_total');
						$s_order_create_data['status'] = 'Paid';
					} else {
						if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
							$s_order_create_data['status'] = 'Unpaid';
							$s_order_create_data['type_of_sales'] = 'Receivables';

						} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
							$s_order_create_data['status'] = 'Partially Paid';
							$s_order_create_data['type_of_sales'] = 'Receivables';

						} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
							$s_order_create_data['status'] = 'Paid';
							$s_order_create_data['type_of_sales'] = 'Cash';

							if($s_order_create_data['quantity_due'] > 0) {
								$s_order_create_data['type_of_sales'] = 'Payables';
							}
						}


					}

					//check if any required field is empty
					if (empty($s_order_create_data['quantity'])) {
						$errors['quantity'] = 'Order Quantity cannot be empty';
					}

					if (empty($s_order_create_data['item_id'])) {
						$errors['item_id'] = 'You must select an Item';
					}

					if (empty($s_order_create_data['amount'])) {
						$errors['amount'] = 'Total amount cannot be empty';
					}

					//if there's error
					if (!empty($errors)) {
						//error found, let's notify the user of it
						$ajax_data = $errors;
						echo json_encode($ajax_data);
					} else {
						//No error found, now we can update data
						$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);
						//get previous quantity picked from the sales order table
						$item_quantity['quantity'] = $this->db->get_where('sales_order', array('so_code' => $so_code, 'item_id' => $item_id))->row()->quantity_picked;

						//incase the user added another item, let's insert it...
						$item_rows = $this->db->get_where('sales_order', array('so_code' => $so_code, 'item_id' => $item_id))->num_rows();

						if ($item_rows < 1) {

							$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
							$s_order_create_data['timestamp'] = $timestamp; //use the old one strtotime(date('d-m-Y H:i:s'));
							$s_order_create_data['date'] = $this->input->post('order_date');

							//$s_order_create_data['track_code'] = $track_code;
							$this->db->insert('sales_order', $s_order_create_data);

							//get s order id
							$so_id = $this->db->insert_id();

							//update accounts payable if quantity due > 0
							//if($s_order_create_data['quantity_due']  > 0) {
							$payable_to_customer = $s_order_create_data['quantity_due'] * $s_order_create_data['price'];

							$payable_to_customer = abs($amount_due);
							$this->db->where('name', 'Accounts Payable');
							$this->db->set('current_balance', 'current_balance +' . $payable_to_customer, FALSE);
							$this->db->update('accounts');
							//}

							//update item table
							$item_data['quantity'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
							$item_data['last_used_timestamp'] = strtotime($this->input->post('order_date2'));
							$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);
							//do update now
							$this->db->where('item_id', $item_id);
							$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
							$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
							$this->db->update('items');

							//let's get the current total quantity
							$item_current_query = $this->db->get_where('items', array('item_id' => $item_id))->row();
							$current_quantity = $item_current_query->quantity;
							$current_cost_price = $item_current_query->purchase_price;
							//let's update the sales order table with it
							$this->db->where('so_id', $so_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('sales_order');

							$this->db->insert('payment_with_goods', $s_order_create_data);

							//get  order id
							$sog_id = $this->db->insert_id();

							//let's update the payment_with_goods table with it
							$this->db->where('so_id', $sog_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('payment_with_goods');

						} else {

							//BEFORE UPDATE
							//update accounts payable if quantity due > 0
							$prev_qd = $this->db->get_where('sales_order', array('item_id' => $item_id, 'so_code' => $so_code))->row()->quantity_due;
							$prev_price = $this->db->get_where('sales_order', array('item_id' => $item_id, 'so_code' => $so_code))->row()->price;

							if ($prev_qd > 0) {
								//subtract the total from accounts payable first
								$prev_payable = $prev_qd * $prev_price;

								$this->db->where('name', 'Accounts Payable');
								$this->db->set('current_balance', 'current_balance -' . $prev_payable, FALSE);
								$this->db->update('accounts');
							}

							//or let's do normal updates

							$this->db->where('so_code', $so_code);
							$this->db->where('item_id', $item_id);
							$this->db->update('sales_order', $s_order_create_data);

							//reupdate THE ACCOUNTS PAYABLE again with the current info
							$payable_to_customer = $s_order_create_data['quantity_due'] * $s_order_create_data['price'];
							if ($s_order_create_data['quantity_due'] > 0) {
								$this->db->where('name', 'Accounts Payable');
								$this->db->set('current_balance', 'current_balance +' . $payable_to_customer, FALSE);
								$this->db->update('accounts');
							}

							//normal editing...
							if ($s_order_create_data['quantity_due'] > 0) {
								$s_order_create_data['negative_or_goods'] = 'goods';
							}

							$this->db->where('so_code', $so_code);
							$this->db->where('track_code', $track_code);
							$this->db->where('item_id', $item_id);
							$this->db->update('payment_with_goods', $s_order_create_data);

							//RESET IT TO NULL SO THAT SALES ORDER TABLE WOULD NOT USE THE ALLOCATED VALUE AT THE TOP
							$s_order_create_data['negative_or_goods'] = NULL;

							//update item table
							//get the earlier quantity and add it before effecting the new update

							//add it back
							$this->db->where('item_id', $item_id);
							$this->db->set('quantity', 'quantity + ' . $item_quantity['quantity'], FALSE);
							$this->db->update('items');
							//end of adjustment

							$item_data['quantity'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
							$item_data['last_used_timestamp'] = strtotime($this->input->post('order_date2'));

							//do update now Subtract
							$this->db->where('item_id', $item_id);
							$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
							$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
							$this->db->update('items');

							//let's get the current total quantity
							$current_quantity = $this->db->get_where('items', array('item_id' => $item_id))->row()->quantity;
							//let's update the sales order table with it
							/*$this->db->where('so_code', $so_code);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->update('sales_order');*/

							/*THE NEED TO UPDATE ALL SUBSEQUENT BALANCES DURING LATE EDITING OF A TRANSACTION*/
							//for sales order
							$item_quantity_update = $item_data['quantity'] - $item_quantity['quantity'];
							$item_query = $this->db->get_where('sales_order', array('so_code' => $so_code, 'item_id' => $item_id));
							$so_id_s = $item_query->row()->so_id;
							$date_timestamp = $item_query->row()->date_timestamp; //we get the date this transaction happened
							$item_cost_price = $item_query->row()->cost_price;
							$item_selling_price = $item_query->row()->price;


							$this->db->select('so_id');
							$this->db->from('sales_order');
							$this->db->where('so_id >= ', $so_id_s);
							$so_ids_s_array = $this->db->get()->result_array();

							foreach ($so_ids_s_array as $soi) {
								$this->db->where('so_id', $soi['so_id']);
								$this->db->where('item_id', $item_id);
								$this->db->set('item_balance', 'item_balance - ' . $item_quantity_update, FALSE);
								$this->db->update('sales_order');
							} //update all the subsequent item balances


							//for payment with goods table
							$so_id_p = $this->db->get_where('payment_with_goods', array('so_code' => $so_code, 'item_id' => $item_id))->row()->so_id;

							$this->db->select('so_id');
							$this->db->from('payment_with_goods');
							$this->db->where('so_id >=', $so_id_p);
							$so_ids_p_array = $this->db->get()->result_array();

							foreach ($so_ids_p_array as $poi) {
								$this->db->where('so_id', $poi['so_id']);
								$this->db->where('item_id', $item_id);
								$this->db->set('item_balance', 'item_balance - ' . $item_quantity_update, FALSE);
								$this->db->update('payment_with_goods');
							} //update all the subsequent item balances


							//some adjustments in the stock manager table as well
							//For that particular day, it won't affect opening stock but only closing stock
							//FOR THAT PARTICULAR DAY --- ONLY CLOSING STOCK IS AFFECTED
							//FOR CLOSING STOCK
							
							$this->db->where('date_timestamp', $date_timestamp);
							$this->db->where('item_id', $item_id);
							$this->db->where('closing_stock IS NOT NULL');
							$this->db->set('closing_stock', 'closing_stock - ' . $item_quantity_update, FALSE);
							$this->db->set('cost_price', $item_cost_price);
							$this->db->set('selling_price', $item_selling_price);
							$this->db->update('stock_manager');

							//FOR ANY OTHER DAY AFTER THAT, BOTH OPENING AND CLOSING STOCKS ARE AFFECTED
							//FOR OPENING STOCK
							$this->db->where('date_timestamp >', $date_timestamp);
							$this->db->where('item_id', $item_id);
							$this->db->where('opening_stock IS NOT NULL');
							$this->db->set('opening_stock', 'opening_stock - ' . $item_quantity_update, FALSE);
							$this->db->set('cost_price', $item_cost_price);
							$this->db->set('selling_price', $item_selling_price);
							$this->db->update('stock_manager');

							//FOR CLOSING STOCK
							$this->db->where('date_timestamp >', $date_timestamp);
							$this->db->where('item_id', $item_id);
							$this->db->where('closing_stock IS NOT NULL');
							$this->db->set('closing_stock', 'closing_stock - ' . $item_quantity_update, FALSE);
							$this->db->set('cost_price', $item_cost_price);
							$this->db->set('selling_price', $item_selling_price);
							$this->db->update('stock_manager');
							//END=========================================================
						}

						//grab the current item ids
						array_push($_items_ids, $item_id);
					}

				} //End of loop

				//let's do this quick update in the payment with goods table
				//for payment with goods
				$this->db->select_sum('quantity_due');
				$pwg_query = $this->db->get_where('payment_with_goods', array('so_code' => $so_code))->row()->quantity_due;

				if ($pwg_query > 0) {

					$this->db->where('so_code', $so_code);
					$this->db->set('negative_or_goods', 'goods');
					$this->db->update('payment_with_goods');
				} //done

				if (empty($errors)) {
					//incase user used different items apart from the earlier one, let's update it and delete it from the sales order table

					$this->db->where('so_code', $so_code);
					$this->db->where('customer_id', $s_order_create_data['customer_id']);
					$this->db->where_not_in('item_id', $_items_ids);
					$items_ids_array = $this->db->get('sales_order')->result_array();

					foreach ($items_ids_array as $item) {
						//add the quantity back
						$this->db->where('item_id', $item['item_id']);
						$this->db->set('quantity', 'quantity + ' . $item['quantity_picked'], FALSE);
						$this->db->update('items');

						//Now delete this row from sales order
						$this->db->where('so_code', $item['so_code']);
						$this->db->where('customer_id', $s_order_create_data['customer_id']);
						$this->db->where('item_id', $item['item_id']);
						$this->db->delete('sales_order');

						$this->db->where('track_code', $track_code);
						$this->db->where('so_code', $item['so_code']);
						$this->db->where('customer_id', $s_order_create_data['customer_id']);
						$this->db->where('item_id', $item['item_id']);
						$this->db->delete('payment_with_goods');
					}
					//FOR SALES ORDER

					//update general sales account
					//subtract first
					$this->db->where('name', 'General Sales');
					$this->db->set('current_balance', 'current_balance - ' . $journal_adjust['current_balance'], FALSE);
					$this->db->update('accounts');

					//update now
					$general_sales['current_balance'] = $this->input->post('hidden_total');
					$this->db->where('name', 'General Sales');
					$this->db->set('current_balance', 'current_balance + ' . $general_sales['current_balance'], FALSE);
					$this->db->update('accounts');

					//get total account balance for GS
					$gs_balance = $this->db->get_where('accounts', array('name' => 'General Sales'))->row()->current_balance;

					//get total account balance for Accounts Receivable
					$acr_balance = $this->db->get_where('accounts', array('name' => 'Accounts Receivable'))->row()->current_balance;
					$acr_balance -= $journal_adjust['current_balance'];
					$acr_balance += $general_sales['current_balance'];

					$this->db->where('name', 'Accounts Receivable');
					$this->db->set('current_balance', $acr_balance);
					$this->db->update('accounts');

					//FOR GENERAL JOURNAL ENTRY (GENERAL SALES) CREDIT THIS
					//$journal_data_gs['timestamp'] = strtotime($this->input->post('order_date'));
					//$journal_data_gs['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					//$journal_data_gs['date'] = $this->input->post('order_date');
					$journal_data_gs['customer_id'] = $this->input->post('order_to');
					$journal_data_gs['journal'] = 'Sales';
					$journal_data_gs['so_code'] = $this->input->post('order_no');
					$journal_data_gs['invoice_code'] = $this->input->post('invoice_code');
					$journal_data_gs['account_name'] = 'General Sales';
					$journal_data_gs['account_balance'] = $gs_balance;
					$journal_data_gs['credit_amount'] = $this->input->post('hidden_total');
					$journal_data_gs['reference'] = '';
					$journal_data_gs['description'] = 'Sales to ' . $this->db->get_where('customers', array('customer_id' => $journal_data_gs['customer_id']))->row()->customer_name;
					$journal_data_gs['sales_person_id'] = $this->session->userdata('login_user_id');

					//UPDATE NOW
					$this->db->where('so_code', $so_code);
					$this->db->where('account_name', 'General Sales');
					$this->db->where('journal', 'Sales');
					$this->db->update('general_journal', $journal_data_gs);

					//FOR GENERAL JOURNAL ENTRY (ACCOUNT RECEIVABLE) DEBIT THIS
					//$journal_data_ar['timestamp'] = strtotime($this->input->post('order_date'));
					//$journal_data_ar['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					//$journal_data_ar['date'] = $this->input->post('order_date');
					$journal_data_ar['customer_id'] = $this->input->post('order_to');
					$journal_data_ar['journal'] = 'Sales';
					$journal_data_ar['so_code'] = $this->input->post('order_no');
					$journal_data_ar['invoice_code'] = $this->input->post('invoice_code');
					$journal_data_ar['account_name'] = 'Accounts Receivable';
					$journal_data_ar['account_balance'] = $acr_balance;
					$journal_data_ar['debit_amount'] = $this->input->post('hidden_total');
					$journal_data_ar['reference'] = '';
					$journal_data_ar['description'] = 'Sales to ' . $this->db->get_where('customers', array('customer_id' => $journal_data_ar['customer_id']))->row()->customer_name;
					$journal_data_ar['sales_person_id'] = $this->session->userdata('login_user_id');

					//UPDATE NOW
					$this->db->where('so_code', $so_code);
					$this->db->where('account_name', 'Accounts Receivable');
					$this->db->where('journal', 'Sales');
					$this->db->update('general_journal', $journal_data_ar);

					//Let's insert data into accounts receivable table
					//FOR ACCOUNTS RECEIVABLE or INVOICE TABLE
					$invoice['so_code'] = $this->input->post('order_no');
					$invoice['customer_id'] = $this->input->post('order_to');
					$invoice['amount'] = $this->input->post('hidden_total');
					$invoice['amount_paid'] = $this->input->post('amount_paid');

					if ($param4 == 'goods') {
						//do this if request is coming from payment with goods edit page
						$invoice['amount_paid'] = $this->input->post('hidden_total');
					}

					$invoice['amount_due'] = $this->input->post('hidden_payment_balance');
					//$invoice['account_id'] = $this->input->post('paid_to');

					$invoice['discount'] = $s_order_create_data['discount'];
					//$invoice['invoice_code'] = $this->input->post('invoice_code');
					//$invoice['p_prev_paid'] = $prev_paid['prev_paid'];
					//$invoice['prev_paid'] = $this->input->post('amount_paid');
					//$invoice['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));

					if ($this->input->post('amount_paid') != 0) {
						$invoice['payment_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					}

					//$invoice['date'] = $this->input->post('order_date');
					//$invoice['timestamp'] = strtotime($this->input->post('order_date'));
					$invoice['sales_person_id'] = $this->session->userdata('login_user_id');
					$invoice['track_code'] = $track_code;

					if ($param4 == 'goods') {
						//do this if request is coming from payment with goods edit page
						$invoice['status'] = 'Paid';
					} else {
						if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
							$invoice['status'] = 'Unpaid';
						} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
							$invoice['status'] = 'Partially Paid';
						} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
							$invoice['status'] = 'Paid';
						}
					}

					//update now
					$this->db->where('so_code', $so_code);
					$this->db->where('invoice_code', $this->input->post('invoice_code'));
					$this->db->update('invoice', $invoice);

					//update receivable balance

					if ($this->input->post('amount_paid') > 0 || $amount_received_earlier > 0) {

						/*Let's get the date and timestamp of the transaction*/
						$this->db->where('so_code', $so_code);
						$transactionRow = $this->db->get('sales_order')->first_row();
						$trDate = $transactionRow->date;
						$trTimestamp = $transactionRow->timestamp;
						$trDateTimestamp = $transactionRow->date_timestamp;

						//Let's update data into payment table
						//FOR PAYMENT TABLE

						/*We update the records of the previous accounts used that is not in the list of accounts currently selected and delete those transactions*/
						$this->db->where('so_code', $so_code);
						$payment_query = $this->db->get('payment');

						$receipt_code = $payment_query->first_row()->receipt_code;
						$payment_rows = $payment_query->num_rows();
						$payment_query_array = $payment_query->result_array();
						$accounts_used_array = [];
						$accounts_used_array = array_column($payment_query_array, 'account_id');
						sort($accounts_used_array);

						$accounts_changed = array_diff($accounts_used_array, $payment_ids);
						$remaining_account_used_array = array_diff($accounts_used_array, $accounts_changed); //the account ids left from the used accounts after taking out those that were changed

						//update the balances of the accounts changed

						//let remove all the accounts records in the general journal for this order
						if(sizeof($accounts_used_array) > 0):

							for($a = 0; $a < sizeof($accounts_used_array); $a++) {

								//get the amount paid into this account
								$this->db->where('track_code', $track_code);
								$this->db->where('account_id', $accounts_used_array[$a]);
								$this->db->where('so_code', $so_code);
								$accounts_changed_query = $this->db->get('payment');
								$amountForThis = $accounts_changed_query->row()->amount;
								$accounts_changed_payment_id = $accounts_changed_query->row()->payment_id;
								$accounts_changed_journal_id = $accounts_changed_query->row()->journal_id;

								//update this account's balance
								$this->db->where('account_id', $accounts_used_array[$a]);
								$this->db->set('current_balance', 'current_balance - ' . $amountForThis, False);
								$this->db->update('accounts');

								/*increase account receivables balances now*/
								$this->db->where('name', 'Accounts Receivable');
								$this->db->set('current_balance', 'current_balance + ' . $amountForThis, False);
								$this->db->update('accounts');

								//we delete records from journal and payment table
								$this->db->where('payment_id', $accounts_changed_payment_id);
								$this->db->delete('general_journal');

								$this->db->where('payment_id', $accounts_changed_payment_id);
								$this->db->delete('payment');
							}

						endif;

						/*FOR ACCOUNTS USED EARLIER*/
						/*if(sizeof($remaining_account_used_array) > 0):

							for($au = 0; $au < sizeof($remaining_account_used_array); $au++) {

								//get the amount paid into this account
								$this->db->where('track_code', $track_code);
								$this->db->where('account_id', $remaining_account_used_array[$au]);
								$this->db->where('so_code', $so_code);
								$accounts_used_query = $this->db->get('payment');
								$amountForThis = $accounts_used_query->row()->amount;
								$accounts_used_payment_id = $accounts_used_query->row()->payment_id;
								$accounts_used_journal_id = $accounts_changed_query->row()->journal_id;

								//update this account's balance
								$this->db->where('account_id', $remaining_account_used_array[$au]);
								$this->db->set('current_balance', 'current_balance - ' . $amountForThis, False);
								$this->db->update('accounts');

								//we delete records from journal and payment table
								/*$this->db->where('payment_id', $accounts_used_payment_id);
								$this->db->delete('general_journal');*/

								/*$this->db->where('payment_id', $accounts_used_payment_id);
								$this->db->delete('payment');
							}

						endif;*/


						/*WORKING ON THE MAIN THINGS NOW*/
						$weHaveCashSalesInPayables = false;

						//update payment category
						//getting the type of payment (Category)
						$this->db->select_sum('quantity_due');
						$tp_quantity_due = $this->db->get_where('sales_order', array('so_code' => $invoice['so_code']))->row()->quantity_due;

						if ($tp_quantity_due > 0) {
							$payment_update['category'] = 'Payables';
							$weHaveCashSalesInPayables = true;

							//data for cash sales in payables
							$s_order_array_cc = $this->db->get_where('sales_order', array('so_code' => $invoice['so_code'], 'customer_id' => $invoice['customer_id']))->result_array();

							//find total amount for the items picked
							$cash_sales_amount = 0;

							foreach ($s_order_array_cc as $sq) {
								$cash_sales_amount += $sq['price'] * $sq['quantity_picked'];
							}	
						} else {
							$payment_update['category'] = 'Cash Sales';
						}

						/*FOR EACH ACCOUNT SELECTED*/
						for($p = 0; $p < sizeof($payment_ids); $p++):


							$amountPaidWithThisAccount = $this->input->post('method_amount_'.$payment_ids[$p]);

							$thisAccountId = $payment_ids[$p];

							if($weHaveCashSalesInPayables) { /*if we have, then we get to work*/

								if($amountPaidWithThisAccount <= $cash_sales_amount) {

									$payment_update['cash_sales_in_payables'] = $amountPaidWithThisAccount;

									$cash_sales_amount -= $amountPaidWithThisAccount; /*We less it by the amount*/

								} else {

									//now the data to insert
									$payment_update['cash_sales_in_payables'] = $cash_sales_amount;

									$cash_sales_amount = 0; /*It's finished so we set it to 0*/
								}
							}


							//update now
							$acrr_balance = $this->db->get_where('accounts', array('name' => 'Accounts Receivable'))->row()->current_balance;

							$receivable_balance = $acrr_balance - $amountPaidWithThisAccount;


							//Let's insert data into payment table
							//FOR PAYMENT TABLE
							$payment_data['payment_type'] = 'Receivable';
							$payment_data['receipt_code'] = $receipt_code;
							$payment_data['so_code'] = $this->input->post('order_no');
							$payment_data['customer_id'] = $this->input->post('order_to');
							$payment_data['amount_tendered'] = $this->input->post('amount_tendered');
							$payment_data['change_due'] = $this->input->post('amount_tendered') - $this->input->post('amount_paid');
							$payment_data['amount'] = $amountPaidWithThisAccount;
							$payment_data['due'] = $this->input->post('hidden_payment_balance');
							$payment_data['timestamp'] = $trDateTimestamp;
							$payment_data['day_timestamp'] = $trTimestamp;
							$payment_data['date'] = $trDate;
							$payment_data['account_id'] = $thisAccountId;
							$payment_data['issuer_id'] = $this->session->userdata('login_user_id');
							$payment_data['track_code'] = $track_code;
							$payment_data['invoice_id'] = $invoice_id;
							$payment_data['invoice_code'] = $invoice_code;

							//insert now
							$this->db->insert('payment', $payment_data);
							$payment_id = $this->db->insert_id();

							

							//update the payment table
							$this->db->where('payment_id', $payment_id);
							$this->db->set('category', $payment_update['category']);
							$this->db->set('cash_sales_in_payables', $payment_update['cash_sales_in_payables']);
							$this->db->update('payment');

							//update accounts payable if customer overpaid
							$this->db->where('payment_id', $payment_id);
							$this->db->where('customer_id', $payment_data['customer_id']);
							$this->db->where('invoice_code', $payment_data['invoice_code']);
							$amount_due = $this->db->get('payment')->row()->due;

							if ($amount_due < 0) {
								$payable_to_customer = abs($amount_due);
								$this->db->where('name', 'Accounts Payable');
								$this->db->set('current_balance', 'current_balance +' . $payable_to_customer, FALSE);
								$this->db->update('accounts');
							}

							//FOR RECEIPTS FOR SALES ORDER
							//FOR GENERAL JOURNAL ENTRY (ACCOUNT RECEIVABLE) DEBIT THIS
							$journal_data_payment_ar['payment_id'] = $payment_id;
							$journal_data_payment_ar['timestamp'] = $trDateTimestamp;
							$journal_data_payment_ar['date_timestamp'] = $trTimestamp;
							$journal_data_payment_ar['date'] = $trDate;
							$journal_data_payment_ar['customer_id'] = $this->input->post('order_to');
							$journal_data_payment_ar['journal'] = 'Receipts';
							$journal_data_payment_ar['so_code'] = $this->input->post('order_no');
							$journal_data_payment_ar['invoice_code'] = $this->input->post('invoice_code');
							$journal_data_payment_ar['account_name'] = 'Accounts Receivable';
							$journal_data_payment_ar['account_balance'] = $receivable_balance;
							$journal_data_payment_ar['credit_amount'] = $amountPaidWithThisAccount;
							$journal_data_payment_ar['reference'] = '';
							$journal_data_payment_ar['description'] = 'Receipt for order ' . $this->input->post('order_no');
							$journal_data_payment_ar['sales_person_id'] = $this->session->userdata('login_user_id');

							//INSERT NOW
							$this->db->insert('general_journal', $journal_data_payment_ar);

							//FOR GENERAL JOURNAL ENTRY (ACCOUNT PAID TO) DEBIT THIS ACCOUNT
							$journal_data_payment_ac['payment_id'] = $payment_id;
							$journal_data_payment_ac['timestamp'] = $trDateTimestamp;
							$journal_data_payment_ac['date_timestamp'] = $trTimestamp;
							$journal_data_payment_ac['date'] = $trDate;
							$journal_data_payment_ac['customer_id'] = $this->input->post('order_to');
							$journal_data_payment_ac['journal'] = 'Receipts';
							$journal_data_payment_ac['so_code'] = $this->input->post('order_no');
							$journal_data_payment_ac['invoice_code'] = $this->input->post('invoice_code');
							$journal_data_payment_ac['account_name'] = $this->db->get_where('accounts', array('account_id' => $thisAccountId))->row()->name;
							$journal_data_payment_ac['debit_amount'] = $amountPaidWithThisAccount;
							$journal_data_payment_ac['reference'] = '';
							$journal_data_payment_ac['description'] = 'Receipt for order ' . $this->input->post('order_no');
							$journal_data_payment_ac['sales_person_id'] = $this->session->userdata('login_user_id');

							//INSERT NOW
							$this->db->insert('general_journal', $journal_data_payment_ac);
							$journal_id = $this->db->insert_id();

							//increase the balance of the account used for the receipt
							$paid_to_account['current_balance'] = $amountPaidWithThisAccount;
							$this->db->where('account_id', $thisAccountId);
							$this->db->set('current_balance', 'current_balance + ' . $paid_to_account['current_balance'], FALSE);
							$this->db->update('accounts');


							/*we reduce Accounts Receivable balance*/
							$this->db->where('name', 'Accounts Receivable');
							$this->db->set('current_balance', $receivable_balance);
							$this->db->update('accounts');

							//get total account balance for Accont paid to
							$acpt_balance = $this->db->get_where('accounts', array('account_id' => $thisAccountId))->row()->current_balance;
							//update journal now
							$this->db->where('account_name', $this->db->get_where('accounts', array('account_id' => $thisAccountId))->row()->name);
							$this->db->where('journal_id', $journal_id);
							// $this->db->where('so_code', $this->input->post('order_no'));
							// $this->db->where('journal', 'Receipts');
							$this->db->set('account_balance', $acpt_balance);
							$this->db->update('general_journal');

							//update payment table with this id
							$this->db->where('payment_id', $payment_id);
							$this->db->set('journal_id', $journal_id);
							$this->db->update('payment');

							/*$this->db->where('name', 'Accounts Receivable');
							$this->db->set('current_balance', $receivable_diff);
							$this->db->update('accounts');*/

						endfor;//end of each payment account used now

						//update customer's balance due column in the customer table
						$customer_id = $s_order_create_data['customer_id'];

						//update customer's address if there is a change in the address
						$customer_address['address'] = $this->input->post('bill_to');
						$this->db->where('customer_id', $customer_id);
						$this->db->set('address', $customer_address['address']);
						$this->db->update('customers');

						////return now
						$ajax_data['success'] = true;
						echo json_encode($ajax_data);
					}
				}
			}

		}

		/*DELETING SALES ORDER*/
		if ($param1 == 'delete') {

			//Delete invoices here
			if ($param2 == 'invoice') {
				$invoice_code = append_words($param3, '_');
				$invoice_id = $param4;
				$this->crud_model->delete_invoice($invoice_code, $invoice_id);

			} else {
				//Delete Sales Order here'
				$so_code = $param2;

				//Track errors and success
				$errors = array();
				$ajax_data = array();

				$this->crud_model->delete_sales_order($so_code);
			}
		}	

	}


	function sales_order_pos_alterated($param1 = '', $param2 = '', $param3 = '', $param4 = '', $param5 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'create') {

			$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			//imported ids array
			$input_ids_numeric = explode('-', $param2);
			$payment_ids = explode('-', $param3);
			sort($payment_ids);

			//FOR SALES ORDER TABLE
			$s_order_create_data['so_code'] = $this->input->post('order_no_pos');
			$s_order_create_data['customer_id'] = $this->input->post('order_to_pos');
			$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date_pos'));
			$s_order_create_data['timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
			$s_order_create_data['date'] = $this->input->post('order_date_pos');
			$s_order_create_data['comment'] = $this->input->post('comments');
			$s_order_create_data['track_code'] = $paid_data['track_code'];
			$s_order_create_data['private_comment'] = $this->input->post('private_comments');
			$s_order_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			$s_order_create_data['discount'] = $this->input->post('discount_pos');


			//check if today's date is selected
			if ($s_order_create_data['date_timestamp'] !== strtotime(date('d-m-Y'))) {
				 // $errors['mismatch_date'] = '<p>Creation date error. It seems your selected date is not for today. Back-dated transactions are also not allowed! Please check and try again.</p><p>If you think this is an error, then contact the system administrator for assistance</p>';
			}


			//check if any required field is empty
			if (empty($s_order_create_data['so_code'])) {
				$errors['so_code'] = 'SO Number cannot be empty';
			}

			if (!empty($this->input->post('amount_tendered_pos')) && $this->input->post('amount_paid_pos') != 0) {
				if ($this->input->post('amount_tendered_pos') < $this->input->post('amount_paid_pos')) {
					$errors['invalid_payment'] = 'Amount Tendered cannot be less than amount paid!';
				}
			}

			if (!empty($this->input->post('amount_tendered_pos'))) {
				if ($this->input->post('amount_paid_pos') < 1) {
					$errors['invalid_amount_paid'] = 'Amount Paid is invalid! Use a positive number or a number greater than zero.';
				}
			}

			if (empty($s_order_create_data['customer_id'])) {
				$errors['customer_id'] = 'You must select a customer';
			}

			if (empty($s_order_create_data['date'])) {
				$errors['date'] = 'Order Date cannot be empty';
			}

			if (!validate_so_no($s_order_create_data['so_code'])) {
				$errors['invalid_so_code'] = 'The Sales Order Code [' . $s_order_create_data['so_code'] . '] is invalid. Please check the correct format in System Settings >> Company.';
			}

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$s_item_ids = array();
			$s_counter2 = 0;
			$s_item_ids2 = array();
			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$s_quantity = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
				$s_quantity_picked = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
				$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

				$quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->quantity;

				//checking to see if this item is sold in unit or ton
				$item_unit_id = $this->input->post('item_unit_id_' . $input_ids_numeric[$i]);

				if ($s_quantity_picked > $quantity_left) {
					$s_counter2++;
					array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
				}

				if ($s_quantity_picked > $s_quantity) {
					$s_counter++;
					array_push($s_item_ids, $s_item_id);
				}
			}

			if ($s_counter > 0) {
				$errors['over'] = 'Quantity picked for some items are more than the quantity bought. Please check and try again!.';
			}

			if($item_unit_id == '' || $item_unit_id == null || empty($item_unit_id)) {
				//if it is a unit sales, skip this error
				if ($s_counter2 > 0) {
					$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transaction.';
					//$errors['item_ids'] = $s_item_ids2
				}
			}

			//check for duplicate

			if (!s_order_validation_insert($s_order_create_data['so_code'])) {

				$ajax_data['success'] = 'duplicate';
				$ajax_data['duplicate'] = 'Duplicate found: Sales Order with the same SO No [' . $s_order_create_data['so_code'] . '] already exists';
				echo json_encode($ajax_data);
			} else if (!invoice_code_validation_insert($this->input->post('invoice_code_pos'))) {

				$ajax_data['success'] = 'duplicate';
				$ajax_data['duplicate'] = 'Duplicate found: Invoice Code [' . $this->input->post('invoice_code_pos') . '] already exists';
				echo json_encode($ajax_data);
			} else {
				if (!empty($errors)) {
					//error found, let's notify the user of it
					$ajax_data = $errors;
					echo json_encode($ajax_data);
				} else {

					$priceData = [];
					$batchPriceData = [];
					$customer_id = $s_order_create_data['customer_id'];

					$priceData['customer_id'] = $customer_id ;

					//collect data for each item bought
					for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

						$s_order_create_data['order_item_has_unit_sales'] = '0';
						$s_order_create_data['bundle_quantity'] = '0';
						$s_order_create_data['bundle_price'] = '0';
						$s_order_create_data['unit_id'] = NULL;
						/*
							** 0 = Not sold in unit but in package eg bags
							** 1 = Sold in unit eg from box to pound (nails)
							** 2 = Bought the item in unit:pieces and decides to sell in bundle. eg Iron rods are bought in pieces but can be sold in ton
						*/

						$isInTon = $this->input->post('isInTon_' . $input_ids_numeric[$i]);
						//checking to see if this item is sold in unit
						$item_unit_id = $this->input->post('item_unit_id_' . $input_ids_numeric[$i]);

						if($isInTon == 'yes') { //we are selling this item in ton - from pieces to bundle
							$s_order_create_data['unit_id'] = $this->input->post('ton_item_unit_id_' . $input_ids_numeric[$i]);
							$s_order_create_data['bundle_quantity'] = $this->input->post('order_bundle_quantity_' . $input_ids_numeric[$i]);
							$s_order_create_data['bundle_price'] = $this->input->post('order_bundle_price_' . $input_ids_numeric[$i]);
							$s_order_create_data['order_item_has_unit_sales'] = '2';

						} //end of ton


						$s_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
						$s_order_create_data['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);
						$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
						$s_order_create_data['grand_total'] = $this->input->post('hidden_total_pos');
						$s_order_create_data['html_id'] = $input_ids_numeric[$i];
						$s_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);
						$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);

						$s_order_create_data['quantity_due'] = $s_order_create_data['quantity'] - $s_order_create_data['quantity_picked'];

						//FOR STOCK RECORDS TABLE
						/*if($item_unit_id == '') { //we don't do this with items sold in smaller units
							$stock_records['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);
							$stock_records['supplier_id'] = $this->input->post('item_supplier_id_' . $input_ids_numeric[$i]);
							$stock_records['so_code'] = $s_order_create_data['so_code'];
							$stock_records['date'] = $s_order_create_data['date'];
							$stock_records['q_sold'] = $s_order_create_data['quantity_picked'];

							//to update the item balance, let's get recent entry into the stock record table
							$this->db->select_max('record_id');
							$this->db->where('item_id', $stock_records['item_id']);
							$this->db->where('supplier_id', $stock_records['supplier_id']);
							$last_record_id = $this->db->get('stock_record')->row()->record_id;
							$item_balance_record = $this->db->get_where('stock_record', ['record_id' => $last_record_id])->row()->item_balance;

							$stock_records['item_balance'] = $item_balance_record - $s_order_create_data['quantity_picked'];
							$stock_records['selling_price'] = $s_order_create_data['price'];
							$stock_records['timestamp'] = $s_order_create_data['timestamp'];
						}*/


						

						//item sold in unit
						if($item_unit_id > 0) {

							$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);
							$s_order_create_data['unit_id'] = $item_unit_id;

							//we need to check and see if we have some of this item left in the unit_transfer table
							//this will inform us whether we need to transfer another quantity or continue to sell from the previous transfer made
							$this->db->order_by('transfer_id', 'desc');
							$unit_transfer_query = $this->db->get_where('unit_transfer', [
								'item_id' => $item_id, 'unit_id' => $item_unit_id
							]);
							$unit_quantity = $this->crud_model->getItemUnitQuantity($item_id, $item_unit_id);

							//let's see if the item is in stock
							$item_quantity_avail = $this->crud_model->getItemBalance($item_id);

							if($unit_transfer_query->num_rows() < 1) {

								if($item_quantity_avail > 0) { //we have some packages so we can transfer for the unit sales
									//this is the first time we will transfer item there
									$transferData['item_id'] = $item_id;
									$transferData['unit_id'] = $item_unit_id;
									$transferData['package_quantity'] = 1;
									$transferData['unit_quantity'] = $unit_quantity;
									$transferData['package_quantity_balance'] = 1;
									$transferData['unit_quantity_balance'] = $unit_quantity;
									$transferData['transfer_date'] = date('Y-m-d h:i:s');

									$this->db->insert('unit_transfer', $transferData);
									$transfer_id = $this->db->insert_id();

									//reduce the main item quantity by 1
									$this->db->where('item_id', $item_id);
									$this->db->set('quantity', 'quantity - 1', false);
									$this->db->update('items');

									//update the current entry of the item unit balance and package balances
									$this->db->where('transfer_id', $transfer_id);
									$this->db->set('unit_quantity_balance', 'unit_quantity_balance - ' . $s_order_create_data['quantity_picked'], false);
									$this->db->update('unit_transfer');

								} else {

									$errors['unit_item_outofstiock'] = 'The items you are selling in unit are out of stock';

									$ajax_data = $errors;
									echo json_encode($ajax_data);
									return false;
								}
								

							} else {
								//not the first time, so item transfer transaction exists
								//let's get the last row
								$unit_transfer_row = $this->db->get_where('unit_transfer', [
									'item_id' => $item_id, 'unit_id' => $item_unit_id
								])->last_row();

								//if the current unit quantity is not enough,then we need to set it off and transfer another
								$available_unit_q = $unit_transfer_row->unit_quantity_balance;
								$prev_transfer_id = $unit_transfer_row->transfer_id;
								


								if($available_unit_q < $s_order_create_data['quantity_picked']) {

									if($item_quantity_avail < 1) { 
										$errors['quantity_not_enough'] = 'Some items you are selling in unit seem to be out of stock. Restock and try again';

										$ajax_data = $errors;
										echo json_encode($ajax_data);
										return false;
									}

									$balance = $s_order_create_data['quantity_picked'] - $available_unit_q;

									//it's not enough so lets transfer another quantity
									$transferData['item_id'] = $item_id;
									$transferData['unit_id'] = $item_unit_id;
									$transferData['package_quantity'] = 1;
									$transferData['unit_quantity'] = $unit_quantity;
									$transferData['package_quantity_balance'] = 1;
									$transferData['unit_quantity_balance'] = $unit_quantity;
									$transferData['transfer_date'] = date('Y-m-d h:i:s');

									$this->db->insert('unit_transfer', $transferData);
									$current_transfer_id = $this->db->insert_id();

									//reduce the main item quantity by 1
									$this->db->where('item_id', $item_id);
									$this->db->set('quantity', 'quantity - 1', false);
									$this->db->update('items');

									//let's update the transfer table now

									//update the previous entry of the item unit balance and package balances to 0

									$this->db->where('transfer_id', $prev_transfer_id);
									$this->db->set('package_quantity_balance', 0);
									$this->db->set('unit_quantity_balance', 0);
									$this->db->update('unit_transfer');

									//update the current entry of the item unit balance and package balances
									$this->db->where('transfer_id', $current_transfer_id);
									$this->db->set('unit_quantity_balance', 'unit_quantity_balance - '. $balance, false);
									$this->db->update('unit_transfer');


								} else {

									if($available_unit_q == $s_order_create_data['quantity_picked']) {
										//if they are equall, set balances to 0
										$this->db->where('transfer_id', $prev_transfer_id);
										$this->db->set('package_quantity_balance', 0);
										$this->db->set('unit_quantity_balance', 0);
										$this->db->update('unit_transfer');
									} else {

										//let's update the transfer table now 
										$this->db->where('transfer_id', $prev_transfer_id);
										$this->db->set('unit_quantity_balance', 'unit_quantity_balance - '. $s_order_create_data['quantity_picked'], false);
										$this->db->update('unit_transfer');
									}

									
								}
							}

							$s_order_create_data['order_item_has_unit_sales'] = '1'; //data for sales order table and payment with goods table

							//collect the data for the items_in_units_order table
							$unitOrderData['customer_id'] = $customer_id;
							$unitOrderData['item_id'] = $item_id;
							$unitOrderData['unit_id'] = $item_unit_id;
							$unitOrderData['quantity'] = $s_order_create_data['quantity_picked'];
							$unitOrderData['unit_price'] = $s_order_create_data['price'];
							$unitOrderData['total_amount'] = $s_order_create_data['quantity'] * $unitOrderData['unit_price'];

							$unitOrderData['unit_balance'] = $this->crud_model->getUnitItemBalance($item_id);

							$unitOrderData['sales_order_code'] = $s_order_create_data['so_code'];
							$unitOrderData['updated_date'] = date('Y-m-d h:i:s');
							$unitOrderData['timestamp'] = date('Y-m-d', strtotime($this->input->post('order_date_pos')));

							$this->db->insert('items_in_units_order', $unitOrderData);

							//update the unit quantity
							$this->db->where('item_id', $item_id);
							$this->db->set('unit_quantity', $unitOrderData['unit_balance']);
							$this->db->update('items');

						}
						//end of item sold in unit						

						$s_order_create_data['amount_paid'] = $this->input->post('amount_paid_pos');
						$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance_pos');
						$s_order_create_data['total_quantity'] = $this->input->post('hidden_total_quantity_pos');

						if ($this->input->post('amount_paid_pos') == 0 || $this->input->post('amount_paid_pos') == 0.00) {
							$s_order_create_data['type_of_sales'] = 'Receivables';
							$s_order_create_data['status'] = 'Unpaid';
						} else if ($this->input->post('amount_paid_pos') < $this->input->post('hidden_total_pos')) {
							$s_order_create_data['status'] = 'Partially Paid';
							$s_order_create_data['type_of_sales'] = 'Receivables';
						} else if ($this->input->post('amount_paid_pos') === $this->input->post('hidden_total_pos')) {
							$s_order_create_data['status'] = 'Paid';
							$s_order_create_data['type_of_sales'] = 'Cash';

							if($s_order_create_data['quantity_due'] > 0) {
								$s_order_create_data['type_of_sales'] = 'Payables';
							}
						}


						//check if any required field is empty
						if (empty($s_order_create_data['quantity'])) {
							$errors['quantity'] = 'Order Quantity cannot be empty';
						}

						if (empty($s_order_create_data['item_id'])) {
							$errors['item_id'] = 'You must select an Item';
						}

						if (empty($s_order_create_data['amount'])) {
							$errors['amount'] = 'Total amount cannot be empty';
						}

						//if there's error
						if (!empty($errors)) {
							//error found, let's notify the user of it
							$ajax_data = $errors;
							echo json_encode($ajax_data);
						} else {
							//No error found, now we can insert data
							$this->db->insert('sales_order', $s_order_create_data);

							//get s order id
							$so_id = $this->db->insert_id();

							//for stock record
							//$this->db->insert('stock_record', $stock_records);
							

							//update item table
							$item_data['quantity'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
							$item_data['last_used_timestamp'] = strtotime($this->input->post('order_date_pos2'));
							$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

							//do update now
							if($item_unit_id == '' || $item_unit_id == null || empty($item_unit_id)) {
								//we only update item if this item is not sold in unit, else we take care of this at the top already

								$this->db->where('item_id', $item_id);
								$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
								$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
								$this->db->update('items');
							}
							

							//let's get the current total quantity
							$item_current_query = $this->db->get_where('items', array('item_id' => $item_id))->row();
							$current_quantity = $item_current_query->quantity;
							$current_cost_price = $item_current_query->purchase_price;

							//let's update the sales order table with it
							$this->db->where('so_id', $so_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('sales_order');

							//if($s_order_create_data['quantity_due'] > 0) {//only if quantity due is greater than 0
							//into the payment with goods table
							if ($s_order_create_data['quantity_due'] > 0) {
								$s_order_create_data['negative_or_goods'] = 'goods';
							}
							$this->db->insert('payment_with_goods', $s_order_create_data);
							//get sg order id
							$sog_id = $this->db->insert_id();

							$this->db->where('so_id', $sog_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('payment_with_goods');

							//RESET IT TO NULL SO THAT SALES ORDER TABLE WOULD NOT USE THE ALLOCATED VALUE AT THE TOP
							$s_order_create_data['negative_or_goods'] = NULL;
							//}

						}

						//checking if this item exists in the prices table for this customer
						$price_data_row = $this->db->get_where('items_prices', ['item_id' => $item_id, 'customer_id' => $customer_id])->num_rows();
						 if($price_data_row < 1) {
						 	//does not exist
						 	$priceData['item_id'] = $item_id;
						 	$priceData['item_price'] = $s_order_create_data['price'];

						 	$hasUnisSales = $this->db->get_where('items', ['item_id' => $item_id])->row()->item_sold_in_units;

						 	if($hasUnisSales == 1) {
						 		//if this item is sold in unit, get the main price and insert it into the items_prices table instead
						 		$priceData['item_price'] = $this->db->get_where('items', ['item_id' => $item_id])->row()->selling_price;

						 	}
						 	

						 	$batchPriceData[] = $priceData;
						 }

					} //End of loop

					if (empty($errors)) {

						if($price_data_row < 1) {
							//insert into items_prices table
							$this->db->insert_batch('items_prices', $batchPriceData);
						}

						//update general sales account (credit)
						$general_sales['current_balance'] = $this->input->post('hidden_total_pos');
						$this->db->where('name', 'General Sales');
						$this->db->set('current_balance', 'current_balance + ' . $general_sales['current_balance'], FALSE);
						$this->db->update('accounts');

						//get total account balance for General Sales
						$gs_balance = $this->db->get_where('accounts', array('name' => 'General Sales'))->row()->current_balance;

						//get total account balance for Accounts Receivable
						$acr_balance = $this->db->get_where('accounts', array('name' => 'Accounts Receivable'))->row()->current_balance;
						$acr_balance += $general_sales['current_balance'];

						//FOR SALES ORDER
						//FOR GENERAL JOURNAL ENTRY (GENERAL SALES) DEBIT THIS
						$journal_data_gs['timestamp'] = strtotime($this->input->post('order_date_pos'));
						$journal_data_gs['date_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
						$journal_data_gs['date'] = $this->input->post('order_date_pos');
						$journal_data_gs['customer_id'] = $this->input->post('order_to_pos');
						$journal_data_gs['journal'] = 'Sales';
						$journal_data_gs['so_code'] = $this->input->post('order_no_pos');
						$journal_data_gs['invoice_code'] = $this->input->post('invoice_code_pos');
						$journal_data_gs['account_name'] = 'General Sales';
						$journal_data_gs['account_balance'] = $gs_balance;
						$journal_data_gs['credit_amount'] = $this->input->post('hidden_total_pos');
						$journal_data_gs['reference'] = '';
						$journal_data_gs['description'] = 'Sales to ' . $this->db->get_where('customers', array('customer_id' => $journal_data_gs['customer_id']))->row()->customer_name;
						$journal_data_gs['sales_person_id'] = $this->session->userdata('login_user_id');

						//INSERT NOW
						$this->db->insert('general_journal', $journal_data_gs);

						//FOR GENERAL JOURNAL ENTRY (ACCOUNT RECEIVABLE) DEBIT THIS
						$journal_data_ar['timestamp'] = strtotime($this->input->post('order_date_pos'));
						$journal_data_ar['date_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
						$journal_data_ar['date'] = $this->input->post('order_date_pos');
						$journal_data_ar['customer_id'] = $this->input->post('order_to_pos');
						$journal_data_ar['journal'] = 'Sales';
						$journal_data_ar['so_code'] = $this->input->post('order_no_pos');
						$journal_data_ar['invoice_code'] = $this->input->post('invoice_code_pos');
						$journal_data_ar['account_name'] = 'Accounts Receivable';
						$journal_data_ar['account_balance'] = $acr_balance;
						$journal_data_ar['debit_amount'] = $this->input->post('hidden_total_pos');
						$journal_data_ar['reference'] = '';
						$journal_data_ar['description'] = 'Sales to ' . $this->db->get_where('customers', array('customer_id' => $journal_data_ar['customer_id']))->row()->customer_name;
						$journal_data_ar['sales_person_id'] = $this->session->userdata('login_user_id');

						//INSERT NOW
						$this->db->insert('general_journal', $journal_data_ar);

						
							//Let's insert data into invoice table
							//FOR INVOICE TABLE
							$invoice['so_code'] = $this->input->post('order_no_pos');
							$invoice['customer_id'] = $this->input->post('order_to_pos');
							$invoice['amount'] = $this->input->post('hidden_total_pos');
							$invoice['amount_paid'] = $this->input->post('amount_paid_pos');;
							$invoice['amount_due'] = $this->input->post('hidden_payment_balance_pos');
							//$invoice['account_id'] = $payment_ids[$p];
							$invoice['invoice_code'] = $this->input->post('invoice_code_pos');
							//$invoice['p_prev_paid'] = $this->input->post('amount_paid_pos');
							//$invoice['prev_paid'] = $this->input->post('amount_paid_pos');
							$invoice['creation_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
							$invoice['timestamp'] = strtotime($this->input->post('order_date_pos'));

							$invoice['discount'] = $this->input->post('discount_pos');

							if ($this->input->post('amount_paid_pos') != 0) {
								$invoice['payment_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
							}

							$invoice['date'] = $this->input->post('order_date_pos');
							$invoice['track_code'] = $paid_data['track_code'];
							$invoice['sales_person_id'] = $this->session->userdata('login_user_id');

							if ($this->input->post('amount_paid_pos') == 0 || $this->input->post('amount_paid_pos') == 0.00) {
								$invoice['status'] = 'Unpaid';
							} else if ($this->input->post('amount_paid_pos') < $this->input->post('hidden_total_pos')) {
								$invoice['status'] = 'Partially Paid';
							} else if ($this->input->post('amount_paid_pos') === $this->input->post('hidden_total_pos')) {
								$invoice['status'] = 'Paid';
							}

							//insert now
							$this->db->insert('invoice', $invoice);
							$invoice_id = $this->db->insert_id();

							

							if ($this->input->post('amount_paid_pos') > 0) {	

								/*Do this on payment account selected basis*/
								$receipt_code = 'DP1REC-' . date('Y') . date('m') . date('d') . date('H') . date('i') . date('s');

								//data for cash sales in payables
								$s_order_array_cc = $this->db->get_where('sales_order', array('so_code' => $invoice['so_code'], 'customer_id' => $invoice['customer_id'], 'quantity_picked >' => '0'))->result_array();

								//find total amount for the items picked
								$cash_sales_amount = 0;

								foreach ($s_order_array_cc as $sq) {
									$cash_sales_amount += $sq['price'] * $sq['quantity_picked'];
								}


								$cashSalesInPayablesBalance = $cash_sales_amount;
								$paidAmount = 0;
								$cashSalesCounter = 0;
								
								$cashSalesIsHigherCounter = 0;

								//getting the type of payment (Category)
								$this->db->select_sum('quantity_due');
								$tp_quantity_due = $this->db->get_where('sales_order', array('so_code' => $invoice['so_code']))->row()->quantity_due;

							for($p = 0; $p < sizeof($payment_ids); $p++):

								$amountPaidWithThisAccount = $this->input->post('method_amount_'.$payment_ids[$p]);
								$paidAmount += $amountPaidWithThisAccount;
								//Let's insert data into payment table
								//FOR PAYMENT TABLE
								$payment_data['payment_type'] = 'Receivable';
								$payment_data['receipt_code'] = $receipt_code;
								$payment_data['so_code'] = $this->input->post('order_no_pos');
								$payment_data['customer_id'] = $this->input->post('order_to_pos');
								$payment_data['amount_tendered'] = $this->input->post('amount_tendered_pos');
								$payment_data['change_due'] = $this->input->post('amount_tendered_pos') - $this->input->post('amount_paid_pos');
								$payment_data['amount'] = $amountPaidWithThisAccount;
								$payment_data['due'] = $invoice['amount'] - $paidAmount;
								$payment_data['timestamp'] = strtotime($this->input->post('order_date_pos'));
								$payment_data['day_timestamp'] = strtotime(date($this->input->post('order_date_pos') . ' H:i:s'));
								$payment_data['date'] = $this->input->post('order_date_pos');
