			//$receivable_adjust_paid['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->amount_paid;
			//$receivable_adjust['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->grand_total;

			//check if any required field is empty
			$user_level = $this->db->get_where('admin', array('admin_id' => $this->session->userdata('admin_id')))->row()->level;
			if ($user_level > 2) {
				if ($dateTimestamp != $today) {
					$errors['outdated'] = 'Sorry! You cannot edit an entry that is a day old. Contact your system Administrator.';
				}
			}

			if (empty($s_order_create_data['so_code'])) {
				$errors['so_code'] = 'SO Number cannot be empty';
			}

			if (empty($s_order_create_data['customer_id'])) {
				$errors['customer_id'] = 'You must select a customer';
			}

			if (empty($s_order_create_data['date'])) {
				//$errors['date'] = 'Order Date cannot be empty';
			}

			if ($param4 != 'goods') {
				if (!validate_so_no($s_order_create_data['so_code'])) {
					$errors['invalid_so_code'] = 'The Sales Order Code [' . $s_order_create_data['so_code'] . '] is invalid. Please check the correct format in System Settings >> Company.';
				}
			}

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$s_item_ids = array();
			$s_counter2 = 0;
			$s_item_ids2 = array();
			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$s_quantity = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
				$s_quantity_picked = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
				$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

				//previous quantity
				$s_quantity_prev = $this->db->get_where('sales_order', array('so_code' => $so_code, 'item_id' => $s_item_id))->row()->quantity;

				$actual_item_q = $s_quantity - $s_quantity_prev;

				$quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->quantity;

				if ($actual_item_q > $quantity_left) {
					$s_counter2++;
					array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
				}

				if ($s_quantity_picked > $s_quantity) {
					$s_counter++;
					array_push($s_item_ids, $s_item_id);
				}
			}

			if ($s_counter > 0) {
				$errors['over'] = 'Quantity picked for some items are more than the quantity bought. Please check and try again!.';
			}

			if ($s_counter2 > 0) {
				$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transaction.';
				//$errors['item_ids'] = $s_item_ids2
			}

			//check for duplicate
			/**if(!p_order_validation_update($this->input->post('order_no'))) {

	                    $ajax_data['success'] = 'duplicate';
	                    $ajax_data['so_code'] = $s_order_create_data['so_code'];
	                    echo json_encode($ajax_data);
				*/
			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				//collect data for each item bought
				for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

					$s_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);

					$s_order_create_data['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);

					$s_order_create_data['html_id'] = $input_ids_numeric[$i];
					$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
					$s_order_create_data['quantity_due'] = $s_order_create_data['quantity'] - $s_order_create_data['quantity_picked'];

					$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
					$s_order_create_data['grand_total'] = $this->input->post('hidden_total');
					$s_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);

					$s_order_create_data['amount_paid'] = $this->input->post('amount_paid');
					$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance');

					$s_order_create_data['total_quantity'] = $this->input->post('hidden_total_quantity');

					if ($param4 == 'goods') {
						
						//do this if request is coming from payment with goods edit page
						$s_order_create_data['amount_paid'] = $this->input->post('hidden_total');
						$s_order_create_data['status'] = 'Paid';
					} else {
						if ($this->input->post('amount_paid') == 0 || $this->input->post('amount_paid') == 0.00) {
							$s_order_create_data['status'] = 'Unpaid';
						} else if ($this->input->post('amount_paid') < $this->input->post('hidden_total')) {
							$s_order_create_data['status'] = 'Partially Paid';
						} else if ($this->input->post('amount_paid') === $this->input->post('hidden_total')) {
							$s_order_create_data['status'] = 'Paid';
						}
					}

					//check if any required field is empty
					if (empty($s_order_create_data['quantity'])) {
						$errors['quantity'] = 'Order Quantity cannot be empty';
					}

					if (empty($s_order_create_data['item_id'])) {
						$errors['item_id'] = 'You must select an Item';
					}

					if (empty($s_order_create_data['amount'])) {
						$errors['amount'] = 'Total amount cannot be empty';
					}

