							$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
							$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
							$this->db->update('items');

							//let's get the current total quantity
							$item_current_query = $this->db->get_where('items', array('item_id' => $item_id))->row();
							$current_quantity = $item_current_query->quantity;
							$current_cost_price = $item_current_query->purchase_price;
							//let's update the sales order table with it
							$this->db->where('so_id', $so_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('sales_order');

							$this->db->insert('payment_with_goods', $s_order_create_data);

							//get  order id
							$sog_id = $this->db->insert_id();

							//let's update the payment_with_goods table with it
							$this->db->where('so_id', $sog_id);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_quantity);
							$this->db->set('cost_price', $current_cost_price);
							$this->db->update('payment_with_goods');

						} else {

							//BEFORE UPDATE
							//update accounts payable if quantity due > 0
							$prev_qd = $this->db->get_where('sales_order', array('item_id' => $item_id, 'so_code' => $so_code))->row()->quantity_due;
							$prev_price = $this->db->get_where('sales_order', array('item_id' => $item_id, 'so_code' => $so_code))->row()->price;

							if ($prev_qd > 0) {
								//subtract the total from accounts payable first
