	//sales order refund
	function sales_order_refund($param1 = '', $param2 = '', $param3 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//Editing SALES ORDER here
		if ($param1 == 'create') {
			$so_code = $param2;
			$track_code = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->track_code;
			//$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$_items_ids = array();

			//imported ids array
			$input_ids_numeric = explode('-', $param3);

			//FOR SALES ORDER TABLE
			$s_order_create_data['so_code'] = $this->input->post('order_no');
			$s_order_create_data['customer_id'] = $this->input->post('order_to');
			$s_order_create_data['timestamp'] = strtotime(date('d-m-Y H:i:s'));
			//$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
			//$s_order_create_data['date'] = $this->input->post('order_date');
			$s_order_create_data['comment'] = $this->input->post('comments');
			$s_order_create_data['track_code'] = $track_code;
			$s_order_create_data['private_comment'] = $this->input->post('private_comments');
			$s_order_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			$account_used = $this->db->get_where('invoice', array('so_code' => $so_code, 'invoice_code' => $this->input->post('invoice_code')))->row()->account_id;

			$amount_received_earlier = $this->db
				->select_sum('amount')
				->where('so_code', $so_code)
				->where('account_id', $account_used)
				->where('invoice_code', $this->input->post('invoice_code'))
				->get('payment')->row()->amount;

			//check the previous amount paid
			$account_adjust['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->amount_paid;
			//update general products sales account
			//get the earlier balance and subtract it before effecting the new update
			$journal_adjust['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->grand_total;

			//get previous prev_paid amount from the accounts_payable table
			//$prev_paid['prev_paid'] = $this->db->get_where('invoice', array('so_code' => $so_code, 'customer_id' => $s_order_create_data['customer_id']))->row()->prev_paid;

			//get the earlier balance and subtract it before effecting the new update
			//$receivable_adjust_paid['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->amount_paid;
			//$receivable_adjust['current_balance'] = $this->db->get_where('sales_order', array('so_code' => $so_code))->row()->grand_total;

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$s_item_ids = array();
			$s_counter2 = 0;
			$s_item_ids2 = array();
			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$s_quantity_picked = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
				$s_quantity_returned = $this->input->post('order_returned_' . $input_ids_numeric[$i]);
				$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

				if ($s_quantity_returned > $s_quantity_picked) {
					$s_counter++;
					array_push($s_item_ids, $s_item_id);
				}
			}

			if ($s_counter > 0) {
