	//PAY WITH GOODS
	function payment_with_goods($param1 = '', $param2 = '', $param3 = '', $param4 = '', $param5 = '') {

		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//Editing SALES ORDER here
		if ($param1 == 'create') {

			$so_code = $param2;
			$track_code = $param5;
			$track_code2 = $param5; //$this->db->get_where('payment_with_goods', array('so_code' => $so_code))->row()->track_code;

			if ($this->input->post('amount_paid') > 0) {
				//use new track code
				$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
			} else {
				//use old track code
				$paid_data['track_code'] = $track_code;
			}

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$_items_ids = array();

			/*
			$errors['amount_paid'] = $this->input->post('amount_paid');
			echo json_encode($errors);
			return false;*/

			//imported ids array
			$input_ids_numeric = explode('-', $param3);

			//FOR SALES ORDER TABLE
			$order_picking_date = $this->input->post('order_date');

			$waybill_code = $this->input->post('waybill_code');

			$s_order_create_data['waybill_code'] = $waybill_code;
			$order_picking_date_timestamp = strtotime(date($order_picking_date.' H:i:s'));
			$s_order_create_data['customer_id'] = $this->input->post('order_to');
			$s_order_create_data['updated_timestamp'] = $order_picking_date_timestamp;
			$s_order_create_data['type_of_sales'] = 'Payables';
			$s_order_create_data['discount'] = $this->input->post('discount');

			$customer_id = $s_order_create_data['customer_id'];

			$order_query = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id));

			$prev_grand_total = $order_query->first_row()->grand_total;
			$timestamp_gen = $order_query->first_row()->timestamp;

			$order_date_timestamp = strtotime(date($s_order_create_data['date'].' H:i:s'));


			$s_order_create_data['comment'] = $this->input->post('comments');
			$s_order_create_data['track_code'] = $paid_data['track_code'];
			$s_order_create_data['private_comment'] = $this->input->post('private_comments');
			$s_order_create_data['sales_person_id'] = $this->session->userdata('login_user_id');
			$s_order_create_data['grand_total'] = $this->input->post('hidden_total');
			$s_order_create_data['amount_paid'] = $this->input->post('amount_paid');
			

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$s_item_ids = array();
			$s_counter2 = 0;
			$s_item_ids2 = array();
			$s_picked_counter = 0;

			$item_changed = 'No';

			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

				$s_quantity = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
				$s_quantity_picked = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
				$s_quantity_picking = $this->input->post('order_picking_' . $input_ids_numeric[$i]);
				$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);


				$soldInUnitRow = $this->db->get_where('sales_order', ['item_id' => $s_item_id, 'so_code' => $so_code])->row();

				$soldInUnit1 = $soldInUnitRow->order_item_has_unit_sales;


				//previous quantity
				$this_item_exists = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $s_item_id))->num_rows();

				if ($this_item_exists > 0) {
					//this item was not changed

					$s_quantity_prev = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $s_item_id))->row()->quantity;

					$prev_picked = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $s_item_id))->row()->quantity_picked;

					$actual_item_q = $s_quantity - $s_quantity_prev;
					$quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->quantity;

					//if the total available quantity is less than the quantity picked
					if($soldInUnit1 != '1') {//for those items sold in unit, leave them
						if ($s_quantity_picking > $quantity_left) {
							$s_counter2++;
							array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
						}
					}

					//if quantity picked now is more than quantity bought, throw an error
					if ($s_quantity_picked > $s_quantity) {
						$s_counter++;
						array_push($s_item_ids, $s_item_id);
					}

					//if previous quantity picked is more than the current, throw an error
					if ($prev_picked >= $s_quantity_picked) {
						$s_picked_counter++;
						//array_push($s_item_ids, $s_item_id);
					}

				} else {
					//this is a new item/ means it was exchanged for one of the old ones

					$item_changed = 'Yes';

					$so_id = $this->input->post('so_' . $input_ids_numeric[$i]);

					$s_quantity_prev = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'so_id' => $so_id))->row()->quantity;

					//sum of quantities previously picked
					$prev_picked = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'so_id' => $so_id))->row()->quantity_picked;

					$actual_item_q = $s_quantity - $s_quantity_prev;
					$quantity_left = $this->db->get_where('items', array('item_id' => $s_item_id))->row()->quantity;

					//if the total available quantity is less than the quantity picked
					if($soldInUnit1 != '1') {//for those items sold in unit, leave them
						if ($s_quantity_picking > $quantity_left) {
							$s_counter2++;
							array_push($s_item_ids2, $this->db->get_where('items', array('item_id' => $s_item_id))->row()->item_name);
						}
					}
					

					//if quantity picked now is more than quantity bought, throw an error
					if ($s_quantity_picked > $s_quantity) {
						$s_counter++;
						array_push($s_item_ids, $s_item_id);
					}

					//if previous quantity picked is more than the current, throw an error
					if ($prev_picked >= $s_quantity_picked) {
						$s_picked_counter++;
						//array_push($s_item_ids, $s_item_id);
					}

				}

			}

			$q_tracker = 0;
			if ($s_counter > 0) {
				$errors['over'] = 'Quantity picked for some items are more than the quantity bought. Please check and try again!.';
				$q_tracker++;
			}

			if ($s_counter2 > 0) {
				$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transaction.';
				//$errors['item_ids'] = $s_item_ids2
			}
		

			/*if($s_picked_counter > 0) {
				                $errors['picked_is_less'] = 'The current quantity picked cannot be less than or equal to the previous one. If you intend editing this order, kindly use the order editor.';
				                //$errors['item_ids'] = $s_item_ids2
			*/

			//check for duplicate
			/**if(!p_order_validation_update($this->input->post('order_no'))) {

	                    $ajax_data['success'] = 'duplicate';
	                    $ajax_data['so_code'] = $s_order_create_data['so_code'];
	                    echo json_encode($ajax_data);
			*/
			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				//collect data for each item bought
				$total_quantity_counter = 0;
				$grand_total_counter = 0; //only if quantity picked is greater than quantity bought
				$amount_paid_tracker = 0;

				for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

					$s_item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

					$soldInUnitRow = $this->db->get_where('sales_order', ['item_id' => $s_item_id, 'so_code' => $so_code])->row();

					$soldInUnit = $soldInUnitRow->order_item_has_unit_sales;

					/*					
					$s_order_create_data['order_item_has_unit_sales'] = '0';
					$s_order_create_data['bundle_quantity'] = '0';
					$s_order_create_data['bundle_price'] = '0';
					$s_order_create_data['unit_id'] = NULL;
					/*
						** 0 = Not sold in unit but in package eg bags
						** 1 = Sold in unit eg from box to pound (nails)
						** 2 = Bought the item in unit:pieces and decides to sell in bundle. eg Iron rods are bought in pieces but can be sold in ton
					*/

					$s_order_create_data['quantity'] = $this->input->post('order_quantity_' . $input_ids_numeric[$i]);
					$s_order_create_data['item_id'] = $this->input->post('order_item_' . $input_ids_numeric[$i]);

					$s_order_create_data['html_id'] = $input_ids_numeric[$i];
					$s_order_create_data['negative_or_goods'] = 'goods';
					$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
					$s_order_create_data['quantity_due'] = $s_order_create_data['quantity'] - $s_order_create_data['quantity_picked'];

					$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
					//$s_order_create_data['grand_total'] = $this->input->post('hidden_total');
					$s_order_create_data['price'] = $this->input->post('order_unit_price_' . $input_ids_numeric[$i]);

					$first_item_price = $this->input->post('price_' . $input_ids_numeric[$i]);

					$quantity_picking = $this->input->post('order_picking_' . $input_ids_numeric[$i]);


					/*
						==========================================================
						================START OF ITEMS SOLD IN UNIT===============
						==========================================================
					*/
					//checking to see if this item is sold in unit

						//item sold in unit
						
						$item_unit_id = $soldInUnitRow->unit_id;
						$s_order_create_data['unit_id'] = $item_unit_id;

						$item_id = $s_item_id;

						if($quantity_picking > 0) {
							if($soldInUnit == '1') {	

								//we need to check and see if we have some of this item left in the unit_transfer table
								//this will inform us whether we need to transfer another quantity or continue to sell from the previous transfer made
								$this->db->order_by('transfer_id', 'desc');
								$unit_transfer_query = $this->db->get_where('unit_transfer', [
									'item_id' => $item_id, 'unit_id' => $item_unit_id
								]);
								$unit_quantity = $this->crud_model->getItemUnitQuantity($item_id, $item_unit_id);

								//let's see if the item is in stock
								$item_quantity_avail = $this->crud_model->getItemBalance($item_id);

								if($unit_transfer_query->num_rows() < 1) {//item has never been transferred for unit sales

									if($item_quantity_avail > 0) { //we have some packages so we can transfer for the unit sales
										//this is the first time we will transfer item there
										$transferData['item_id'] = $item_id;
										$transferData['unit_id'] = $item_unit_id;
										$transferData['package_quantity'] = 1;
										$transferData['unit_quantity'] = $unit_quantity;
										$transferData['package_quantity_balance'] = 1;
										$transferData['unit_quantity_balance'] = $unit_quantity;
										$transferData['transfer_date'] = date_format(date_create_from_format('d-m-Y', $order_picking_date), 'Y-m-d H:i:s');


										$this->db->insert('unit_transfer', $transferData);
										$transfer_id = $this->db->insert_id();

										//reduce the main item quantity by 1
										$this->db->where('item_id', $item_id);
										$this->db->set('quantity', 'quantity - 1', false);
										$this->db->update('items');

										//update the current entry of the item unit balance and package balances
										$this->db->where('transfer_id', $transfer_id);
										$this->db->set('unit_quantity_balance', 'unit_quantity_balance - ' . $s_order_create_data['quantity_picked'], false);
										$this->db->update('unit_transfer');

									} else { //item is out of stock

										$errors['unit_item_outofstiock'] = 'The items you are selling in unit are out of stock';

										$ajax_data = $errors;
										echo json_encode($ajax_data);
										return false;
									}
									

								} else {
									//not the first time, so item transfer transaction exists
									//let's get the last row
									$unit_transfer_row = $this->db->get_where('unit_transfer', [
										'item_id' => $item_id, 'unit_id' => $item_unit_id
									])->last_row();

									//if the current unit quantity is not enough,then we need to set it off and transfer another
									$available_unit_q = $unit_transfer_row->unit_quantity_balance;
									$prev_transfer_id = $unit_transfer_row->transfer_id;
									


									if($available_unit_q < $s_order_create_data['quantity_picked']) {

										if($item_quantity_avail < 1) { 
											$errors['quantity_not_enough'] = 'Some items you are selling in unit seem to be out of stock. Restock and try again';

											$ajax_data = $errors;
											echo json_encode($ajax_data);
											return false;
										}

										$balance = $quantity_picking - $available_unit_q;

										//it's not enough so lets transfer another quantity
										$transferData['item_id'] = $item_id;
										$transferData['unit_id'] = $item_unit_id;
										$transferData['package_quantity'] = 1;
										$transferData['unit_quantity'] = $unit_quantity;
										$transferData['package_quantity_balance'] = 1;
										$transferData['unit_quantity_balance'] = $unit_quantity;
										$transferData['transfer_date'] = date_format(date_create_from_format('d-m-Y', $order_picking_date), 'Y-m-d H:i:s');

										$this->db->insert('unit_transfer', $transferData);
										$current_transfer_id = $this->db->insert_id();

										//reduce the main item quantity by 1
										$this->db->where('item_id', $item_id);
										$this->db->set('quantity', 'quantity - 1', false);
										$this->db->update('items');

										//let's update the transfer table now

										//update the previous entry of the item unit balance and package balances to 0

										$this->db->where('transfer_id', $prev_transfer_id);
										$this->db->set('package_quantity_balance', 0);
										$this->db->set('unit_quantity_balance', 0);
										$this->db->update('unit_transfer');

										//update the current entry of the item unit balance and package balances
										$this->db->where('transfer_id', $current_transfer_id);
										$this->db->set('unit_quantity_balance', 'unit_quantity_balance - '. $balance, false);
										$this->db->update('unit_transfer');


									} else {

										if($available_unit_q == $quantity_picking) {
											//if they are equall, set balances to 0
											$this->db->where('transfer_id', $prev_transfer_id);
											$this->db->set('package_quantity_balance', 0);
											$this->db->set('unit_quantity_balance', 0);
											$this->db->update('unit_transfer');
										} else {

											//let's update the transfer table now 
											$this->db->where('transfer_id', $prev_transfer_id);
											$this->db->set('unit_quantity_balance', 'unit_quantity_balance - '. $quantity_picking, false);
											$this->db->update('unit_transfer');
										}

										
									}
								}


								$s_order_create_data['order_item_has_unit_sales'] = '1'; //data for sales order table and payment with goods table

								//collect the data for the items_in_units_order table
								$unitOrderData['customer_id'] = $customer_id;
								$unitOrderData['item_id'] = $item_id;
								$unitOrderData['unit_id'] = $item_unit_id;
								$unitOrderData['quantity'] = $quantity_picking;
								$unitOrderData['unit_price'] = $s_order_create_data['price'];
								$unitOrderData['total_amount'] = $s_order_create_data['quantity'] * $unitOrderData['unit_price'];

								$unitOrderData['unit_balance'] = $this->crud_model->getUnitItemBalance($item_id);

								$unitOrderData['sales_order_code'] = $s_order_create_data['so_code'];
								$unitOrderData['updated_date'] = date_format(date_create_from_format('d-m-Y', $order_picking_date), 'Y-m-d H:i:s');
								$unitOrderData['timestamp'] = date_format(date_create_from_format('d-m-Y', $order_picking_date), 'Y-m-d');

								$this->db->insert('items_in_units_order', $unitOrderData);

								//update the unit quantity
								$this->db->where('item_id', $item_id);
								$this->db->set('unit_quantity', $unitOrderData['unit_balance']);
								$this->db->update('items');


							}
						} 

						if($soldInUnit == '2') { //we are selling this item in ton - from pieces to bundle
							$bundle_quantity_pw = $this->db->get_where('sales_order', ['item_id' => $item_id, 'so_code' => $so_code])->first_row()->bundle_quantity;

							$s_order_create_data['unit_id'] = $soldInUnitRow->unit_id;
							$s_order_create_data['bundle_quantity'] = $bundle_quantity_pw;
							$s_order_create_data['bundle_price'] = $this->crud_model->getItemBundlePriceByItemId($s_item_id);
							$s_order_create_data['order_item_has_unit_sales'] = '2';

						} else if($soldInUnit == '1') { //we are selling this item in units - from bundle to pieces
							$s_order_create_data['unit_id'] = $soldInUnitRow->unit_id;
							$s_order_create_data['order_item_has_unit_sales'] = '1';
							$s_order_create_data['bundle_quantity'] = 0;
							$s_order_create_data['bundle_price'] = 0;

						} else {

							$s_order_create_data['order_item_has_unit_sales'] = '0';
							$s_order_create_data['bundle_quantity'] = 0;
							$s_order_create_data['bundle_price'] = 0;
							$s_order_create_data['unit_id'] = NULL;
						} //end of ton //end of ton
						/*
						==========================================================
						================END OF ITEMS SOLD IN UNIT=================
						==========================================================
						*/

					//ADJUST HERE TO AVOID AMOUNT PAID NOW FROM ADDING UP TO THE PREVIOUS AMOUNT PAID FOR SOME OF THE ITEMS DOUBLE.....
					/*if ($amount_paid_tracker > 0) {
						//already updated the amount paid paid column. But check also if the new amount paid coming in is greater than 0
						if ($this->input->post('amount_paid') > 0) {
							$s_order_create_data['amount_paid'] -= $this->input->post('amount_paid');
						}
					}*/ //END OF ADJUSTMENT

					$real_owing = $this->input->post('hidden_payment_balance');

					if ($this->input->post('amount_paid') < $real_owing) {
						$s_order_create_data['status'] = 'Partially Paid';
					} else {
						$s_order_create_data['status'] = 'Paid';
					}

					$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance');
					//$s_order_create_data['status'] = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id))->row()->status;
					$s_order_create_data['total_quantity'] = $this->input->post('hidden_total_quantity');
					//$s_order_create_data['amount_due'] = $this->input->post('hidden_payment_balance');

					//check if the quantity picked is greater than the one bought so we can update the quantity bought to the one picked and also the total amount
					if ($q_tracker > 0) {

						//it is true
						$s_order_create_data['quantity'] = $s_order_create_data['quantity_picked'];
						$s_order_create_data['quantity_due'] = 0;
						$s_order_create_data['amount'] = $s_order_create_data['quantity'] * $s_order_create_data['price'];
						$s_order_create_data['status'] = 'Partially Paid';

						$grand_total_counter += $s_order_create_data['amount'];
						$total_quantity_counter += $s_order_create_data['quantity'];
					}

					//check if any required field is empty
					if ($s_order_create_data['quantity'] == '') {
						$errors['quantity'] = 'Order Quantity cannot be empty';
					}

					if (empty($s_order_create_data['item_id'])) {
						$errors['item_id'] = 'You must select an Item';
					}

					//if there's error
					if (!empty($errors)) {
						//error found, let's notify the user of it
						$ajax_data = $errors;
						echo json_encode($ajax_data);
					} else {
						//No error found, now we can update data
						$item_id = $this->input->post('order_item_' . $input_ids_numeric[$i]);

						$this_item_exists = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $item_id))->num_rows();


						//for stock record
						//$this->db->insert('stock_record');
						

						////////////////////////////////////////////////////////////////////////////////////////
						if ($this_item_exists > 0) {
							//item not changed so let's go ahead
							//get previous quantity picked from the sales order table

							$s_order_create_data['timestamp'] = $order_query->first_row()->timestamp;
							$s_order_create_data['date_timestamp'] = $order_query->first_row()->date_timestamp;
							$s_order_create_data['date'] = $order_query->first_row()->date; //date

							$item_quantity['quantity'] = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $item_id))->row()->quantity_picked;

							//or let's do normal updates
							$this->db->where('so_code', $so_code);
							$this->db->where('item_id', $item_id);
							$this->db->update('sales_order', $s_order_create_data);

							if ($param4 == 'goods') {

								$picked_prev = $this->db->get_where('payment_with_goods', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $item_id, 'track_code' => $track_code))->row()->quantity_picked;

								$picked_diff = $s_order_create_data['quantity_picked'] - $picked_prev;

								$due_prev = $this->db->get_where('payment_with_goods', array('so_code' => $so_code, 'customer_id' => $customer_id, 'item_id' => $item_id, 'track_code' => $track_code))->row()->quantity_due;

								$due_diff = $s_order_create_data['quantity_due'] - $due_prev;

								//or let's do normal updates
								$this->db->where('so_code', $so_code);
								$this->db->where('item_id', $item_id);
								$this->db->where('track_code', $track_code);
								$this->db->set('track_code', $paid_data['track_code']);
								$this->db->set('quantity_picked', 'quantity_picked + ' . $picked_diff, FALSE);
								$this->db->set('quantity_due', 'quantity_due + ' . $due_diff, FALSE);
								$this->db->update('payment_with_goods');

							} else {
								
								//insert new entries into the payment with goods table
								$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
								$s_order_create_data['date'] = $this->input->post('order_date');
								$s_order_create_data['quantity_picked'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]) - $item_quantity['quantity'];
								$s_order_create_data['track_code'] = $paid_data['track_code'];
								$s_order_create_data['so_code'] = $so_code;
								$s_order_create_data['timestamp'] = $order_picking_date_timestamp;
								$s_order_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
								$s_order_create_data['date'] = $this->input->post('order_date');
								$s_order_create_data['amount'] = $this->input->post('order_total_price_' . $input_ids_numeric[$i]);
								$s_order_create_data['grand_total'] = $this->input->post('hidden_total');
								$s_order_create_data['amount_due'] = $real_owing;
								$s_order_create_data['picked_by'] = $this->input->post('picked_by');



								//check if the quantity picked is greater than the one bought so we can update the quantiy bought to the one picked and also the total amount
								if ($q_tracker > 0) {
									//it is true
									$s_order_create_data['quantity'] = $s_order_create_data['quantity_picked'];
									$s_order_create_data['quantity_due'] = 0;
									$s_order_create_data['amount'] = $s_order_create_data['quantity'] * $s_order_create_data['price'];
									$s_order_create_data['status'] = 'Partially Paid';
								}

								$this->db->insert('payment_with_goods', $s_order_create_data);

								$this->db->where('so_code', $so_code);
								$this->db->where('item_id', $item_id);
								$this->db->where('track_code', $paid_data['track_code']);
								$this->db->set('amount_paid', $this->input->post('amount_paid'));
								$this->db->update('payment_with_goods');
							}

							if($soldInUnit != '1') {
								//update item table
								//get the earlier quantity and add it before effecting the new update

								//add it back
								$this->db->where('item_id', $item_id);
								$this->db->set('quantity', 'quantity + ' . $item_quantity['quantity'], FALSE);
								$this->db->update('items');
								//end of adjustment

								$item_data['quantity'] = $this->input->post('order_picked_' . $input_ids_numeric[$i]);
