	//Enter Payable creation, updating and deletion
	function enter_payable($param1 = '', $param2 = '', $param3 = '', $param4 = '') {

		if ($this->session->userdata('admin_login_level') == 4) {
			redirect(site_url('login'), 'refresh');
		}

		//Enter Payable Creation
		if ($param1 == 'create') {

			$errors = array();
			$ajax_data = array();
			$valSelected = $param2;

			if ($valSelected == 1) {
				//for supplier option selected
				$creditor_id = trim($this->input->post('supplier_name'));
				$enter_payable_data['date'] = $this->input->post('payable_date');
				$enter_payable_data['creation_timestamp'] = strtotime(date($this->input->post('payable_date') . ' H:i:s'));
				$enter_payable_data['timestamp'] = strtotime($this->input->post('payable_date'));
				$enter_payable_data['amount'] = $this->input->post('amount');
				$enter_payable_data['amount_due'] = $this->input->post('amount');
				$enter_payable_data_allocated['account_id'] = $this->input->post('allocated_account');



				//check whether it is a supplier or customer
				if(substr($creditor_id, 0, 2) == 's_') {
					$enter_payable_data['supplier_id'] = substr($creditor_id, 2);
					$enter_payable_data['po_code'] = 'LPAY-'.substr(strtotime('now'), 5);

	
				} else if(substr($creditor_id, 0, 2) == 'c_') {
					$enter_payable_data['customer_id'] = substr($creditor_id, 2);
					$enter_payable_data['invoice_code'] = 'LPAY-'.substr(strtotime('now'), 4);
					$enter_payable_data['so_code'] = 'LPAY-'.substr(strtotime('now'), 4);

