	//Pay Payable or other payments creation, updating and deletion
	function payments($param1 = '', $param2 = '', $param3 = '', $param4 = '', $param5 = '') {

		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		$current_user_id  = $this->session->userdata('login_user_id');
		$user_level = $this->db->get_where('admin', ['admin_id' => $current_user_id])->row()->level;

		//currency
		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);
		//Pay Payable Creation
		if ($param1 == 'create') {

			$errors = array();
			$ajax_data = array();

			//check if it is same date, else reject
			$creationDate = strtotime($this->input->post('payment_date'));
			$currentDate = strtotime(date('d-m-Y'));

			if($user_level != 1) { //show only for non-superadmin

				if($creationDate != $currentDate) {
					$errors['date_mismatch'] = 'This record doesn\'t seem to be for today. Please check the selected date and try again!';

					echo json_encode($errors);

					return;

				}; //exit
			}


			if ($param2 == 1) {

				$pay_payable_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
				//for payable payments
				$pay_payable_data['supplier_id'] = trim($this->input->post('supplier_name'));

				if (substr($pay_payable_data['supplier_id'], 0, 3) == 'de_') {
					//payment of debts
					$pay_payable_data['debt_id'] = substr(trim($this->input->post('supplier_name')), 3);
					$pay_payable_data['date'] = $this->input->post('payment_date');
					$pay_payable_data['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					$pay_payable_data['amount_paid'] = $this->input->post('amount_paid');
					$pay_payable_data['account_id'] = $this->input->post('account_paid_from');

					$account_balance = $this->input->post('hidden_account_balance_payment');
					$total_payable = $this->input->post('hidden_total_payable');

					//validate
					if ($pay_payable_data['amount_paid'] > $account_balance) {
						$errors['account_balance'] = 'You do not have sufficient fund in this account to perform this transaction. Please use a different account. Current Account Balance is: ' . numfmt_format_currency($fmt, $account_balance, $currency) . ' and Your payment is: ' . numfmt_format_currency($fmt, $pay_payable_data['amount_paid'], $currency);
					}

					/*if ($pay_payable_data['amount_paid'] > $total_payable) {
						                        $errors['total_payable'] = 'You are making over payment! The amount payable is: ' . numfmt_format_currency($fmt, $total_payable, $currency) . ' and Your payment is: ' . numfmt_format_currency($fmt, $pay_payable_data['amount_paid'], $currency);
					*/

					if (empty($pay_payable_data['debt_id'])) {
						$errors['debt_name'] = 'Make sure what you are paying for is selected';
					}

					if (empty($pay_payable_data['date'])) {
						$errors['date'] = 'Please select a valid date';
					}

					if (empty($pay_payable_data['amount_paid'])) {
						$errors['amount_paid'] = 'Please enter the amount';
					}

					if ($pay_payable_data['amount_paid'] < 1) {
						$errors['amount_paid_invalid'] = 'Please enter a valid amount. Must be greater than 0.';
					}

					if (empty($this->input->post('account_paid_from'))) {
						$errors['account_id'] = 'No Account was selecetd. Please select the Account you are paying from';
					}

					//check error
					if (!empty($errors)) {
						$ajax_data = $errors;
						echo json_encode($ajax_data);
					} else {

						$this->db->where('debt_id', $pay_payable_data['debt_id']);
						$this->db->set('payment_timestamp', strtotime(date('d-m-Y H:i:s')));
						$this->db->set('amount_paid', 'amount_paid +' . $pay_payable_data['amount_paid'], FALSE);
						$this->db->set('amount_due', 'amount_due -' . $pay_payable_data['amount_paid'], FALSE);
						$this->db->set('track_code', $pay_payable_data['track_code']);
						$this->db->set('account_id', $pay_payable_data['account_id']);
						//$this->db->set('p_prev_paid', $prev_paid['prev_paid']);
						$this->db->update('outstanding_debts');

						//update accounts Payable - reduce it
						$accounts_payable_data['current_balance'] = $this->input->post('amount_paid');
						$this->db->where('name', 'Accounts Payable');
						$this->db->set('current_balance', 'current_balance - ' . $accounts_payable_data['current_balance'], FALSE);
						$this->db->update('accounts');

						//get total account balance for Payable
						$acp_balance = $this->db->get_where('accounts', array('name' => 'Accounts Payable'))->row()->current_balance;

						//update account paid from - reduce it
						$account_paid_from_data['current_balance'] = $this->input->post('amount_paid');
						$this->db->where('account_id', $this->input->post('account_paid_from'));
						$this->db->set('current_balance', 'current_balance - ' . $account_paid_from_data['current_balance'], FALSE);
						$this->db->update('accounts');

						//get total account balance for Account paid from
						$acpf_balance = $this->db->get_where('accounts', array('account_id' => $this->input->post('account_paid_from')))->row()->current_balance;

						//FOR PAYMENT TABLE
						//first, let's update the previous payment track code for this debt id with with the current track code
						$rows = $this->db->get_where('payment', array('debt_id' => $pay_payable_data['debt_id']))->num_rows();

						if ($rows > 0) {
							$this->db->where('debt_id', $pay_payable_data['debt_id']);
							$this->db->set('track_code', $pay_payable_data['track_code']);
							$this->db->update('payment');
						}

						//Let's insert data into payment table
						$payment_data['payment_type'] = 'Payable';
						$payment_data['debt_id'] = $pay_payable_data['debt_id'];
						$payment_data['amount'] = $this->input->post('amount_paid');
						//$payment_data['po_code'] = $po_code_paid_for;
						$payment_data['due'] = $this->db->get_where('outstanding_debts', array('debt_id' => $payment_data['debt_id']))->row()->amount_due;
						$payment_data['timestamp'] = strtotime($this->input->post('payment_date'));
						$payment_data['day_timestamp'] = strtotime(date('d-m-Y H:i:s'));
						$payment_data['date'] = $this->input->post('payment_date');
						$payment_data['account_id'] = $this->input->post('account_paid_from');
						$payment_data['track_code'] = $pay_payable_data['track_code'];
						$payment_data['issuer_id'] = $this->session->userdata('login_user_id');

						//insert now
						$this->db->insert('payment', $payment_data);
						$payment_id = $this->db->insert_id();

						//FOR GENERAL JOURNAL ENTRY DEBIT THIS
						$journal_data_ap['payment_id'] = $payment_id;
