	//Deposits from Customers
	function deposits_received($param1 = '', $param2 = '', $param3 = '', $param4 = '') {

		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//currency
		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);
		//Pay Payable Creation
		if ($param1 == 'create') {

			$errors = array();
			$ajax_data = array();

			$receivable_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
			$code = 'Deposit-' . date('His');
			//for payable payments
			$receivable_data['customer_id'] = strtoupper(trim($this->input->post('customer_name')));
			$receivable_data['date'] = $this->input->post('payment_date');
			$receivable_data['timestamp'] = strtotime($this->input->post('payment_date'));
			$receivable_data['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			$receivable_data['amount'] = -$this->input->post('amount_received');
			$receivable_data['amount_paid'] = 0;
			$receivable_data['invoice_code'] = $code;
			$receivable_data['so_code'] = $code;
			$receivable_data['amount_due'] = -$this->input->post('amount_received');
			$receivable_data['account_id'] = $this->input->post('deposit_account');
			$receivable_data['payment_timestamp'] = strtotime(date('d-m-Y H:i:s'));

			//validate
			/*if ($receivable_data['amount_paid'] > $total_receivable) {
	                $errors['total_receivable'] = 'You are taking over payment! The amount receivable to this Invoice Code [' . $receivable_data['invoice_code'] . '] is: ' . numfmt_format_currency($fmt, $total_receivable, $currency) . ' and Your entry is: ' . numfmt_format_currency($fmt, $receivable_data['amount_paid'], $currency);
			*/

			if (empty($receivable_data['customer_id'])) {
				$errors['customer_id'] = 'Customer\'s name is required';
			}

			if (empty($receivable_data['date'])) {
				$errors['date'] = 'Please select a valid date';
			}

			if (empty($this->input->post('amount_received'))) {
				$errors['amount_paid'] = 'Please enter the amount received';
			}

			if ($this->input->post('amount_received') < 1) {
				$errors['amount_paid_invalid'] = 'Please enter a valid amount. Must be greater than 0.';
			}

			if (empty($this->input->post('deposit_account'))) {
				$errors['account_id'] = 'No Account was selecetd. Please select the Account you are depositing the money into';
			}

			//check error
			if (!empty($errors)) {
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {
				//insert into the invoice table
				//find out if this customer's info with invoice code 'Opening-balance' already exists
				$row_inv = $this->db->get_where('invoice', array('customer_id' => $receivable_data['customer_id'], 'invoice_code' => $code))->num_rows();
				if ($row_inv < 1) {
					//no record found so insert
					$this->db->insert('invoice', $receivable_data);
				} else {
					//record found so update
					$amount = $this->db->get_where('invoice', array('customer_id' => $receivable_data['customer_id'], 'invoice_code' => 'Opening-balance'))->row()->amount;

					$this->db->where('customer_id', $receivable_data['customer_id']);
					$this->db->where('invoice_code', 'Opening-balance');
					$this->db->set('timestamp', $receivable_data['timestamp']);
					$this->db->set('date', $receivable_data['date']);
					$this->db->set('payment_timestamp', $receivable_data['payment_timestamp']);

					if ($amount >= 0) {
						$this->db->set('amount', 'amount + ' . abs($receivable_data['amount']), FALSE);
					} else {
						$this->db->set('amount', 'amount + ' . $receivable_data['amount'], FALSE);
					}
					$this->db->set('amount_due', 'amount_due + ' . $receivable_data['amount_due'], FALSE);
					$this->db->update('invoice');
				}

				//update accounts Receivable - reduce it
				$accounts_payable_data['current_balance'] = $this->input->post('amount_received');
				$this->db->where('name', 'Accounts Payable');
				$this->db->set('current_balance', 'current_balance + ' . $accounts_payable_data['current_balance'], FALSE);
				$this->db->update('accounts');

				//get total account balance for account payable
				$acp_balance = $this->db->get_where('accounts', array('name' => 'Accounts Payable'))->row()->current_balance;

				//update account paid to - increase it
				$account_paid_to_data['current_balance'] = $this->input->post('amount_received');
				$this->db->where('account_id', $this->input->post('deposit_account'));
				$this->db->set('current_balance', 'current_balance + ' . $account_paid_to_data['current_balance'], FALSE);
				$this->db->update('accounts');



				//FOR PAYMENT TABLE
				/*            //generate receipt No
	        $this->db->select('receipt_code');
	        $this->db->where('receipt_code !=', NULL);
	        $this->db->order_by('receipt_code', 'desc');
	        $this->db->limit(1);
	        $rec_query = $this->db->get('payment');
	        $rec_id    = $rec_query->row()->receipt_code;

	        if($rec_query->num_rows() > 0) {
	            $receipt_code  = $rec_id + 1;
	        } else {
	            $receipt_code  = 100001; //default receipt no;
	        }
					*/
				//Let's insert data into payment table
				$payment_data['payment_type'] = 'Deposit';
				//$payment_data['receipt_code'] = $receipt_code;
				$payment_data['customer_id'] = $this->input->post('customer_name');
				$payment_data['amount'] = $this->input->post('amount_received');
				$payment_data['invoice_code'] = $code;
				$payment_data['so_code'] = $code;
				$payment_data['due'] = 0;
				$payment_data['timestamp'] = strtotime($this->input->post('payment_date'));
				$payment_data['day_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$payment_data['date'] = $this->input->post('payment_date');
				$payment_data['account_id'] = $this->input->post('deposit_account');
				$payment_data['track_code'] = $receivable_data['track_code'];
				$payment_data['issuer_id'] = $this->session->userdata('login_user_id');

				//insert now
				$this->db->insert('payment', $payment_data);
				$payment_id = $this->db->insert_id();

				//FOR GENERAL JOURNAL ENTRY CREDIT THIS
				$journal_data_ar['payment_id'] = $payment_id;
				$journal_data_ar['timestamp'] = strtotime($this->input->post('payment_date'));
				$journal_data_ar['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$journal_data_ar['date'] = $this->input->post('payment_date');
				$journal_data_ar['customer_id'] = $this->input->post('customer_name');
				$journal_data_ar['invoice_code'] = $code;
				$journal_data_ar['so_code'] = $code;
				$journal_data_ar['journal'] = 'Deposits Received';
				$journal_data_ar['account_name'] = 'Accounts Payable';
				$journal_data_ar['account_balance'] = $acp_balance;
				$journal_data_ar['credit_amount'] = $this->input->post('amount_received');
				$journal_data_ar['reference'] = $this->input->post('reference_number');
				$journal_data_ar['description'] = $this->input->post('journal_memo');
				$journal_data_ar['sales_person_id'] = $this->session->userdata('login_user_id');
				//$journal_data_g['sales_person_id']  = $this->session->userdata('login_user_id');

				//INSERT NOW
				$this->db->insert('general_journal', $journal_data_ar);

				//FOR GENERAL JOURNAL ENTRY (ACCOUNT PAID TO) DEBIT THIS
				$journal_data_apt['payment_id'] = $payment_id;
				$journal_data_apt['timestamp'] = strtotime($this->input->post('payment_date'));
				$journal_data_apt['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$journal_data_apt['date'] = $this->input->post('payment_date');
				$journal_data_apt['customer_id'] = $this->input->post('customer_name');
				$journal_data_apt['invoice_code'] = $code;
				$journal_data_apt['so_code'] = $code;
				$journal_data_apt['journal'] = 'Deposits Received';
				$journal_data_apt['account_name'] = $this->db->get_where('accounts', array('account_id' => $this->input->post('deposit_account')))->row()->name;
				//$journal_data_apt['account_balance'] = $acpt_balance;
				$journal_data_apt['debit_amount'] = $this->input->post('amount_received');
				$journal_data_apt['reference'] = $this->input->post('reference_number');
				$journal_data_apt['description'] = $this->input->post('journal_memo');
				$journal_data_apt['sales_person_id'] = $this->session->userdata('login_user_id');
				//$journal_data_ap['sales_person_id']  = $this->session->userdata('login_user_id');

				//INSERT NOW
				$this->db->insert('general_journal', $journal_data_apt);

				$journal_id = $this->db->insert_id();

				//update payment table with this id
				$this->db->where('payment_id', $payment_id);
				$this->db->set('journal_id', $journal_id);
				$this->db->update('payment');

				$ajax_data['success'] = true;
				$ajax_data['deposit_type'] = 'Deposit';
				echo json_encode($ajax_data);
			}

		}

		//update here
		if ($param1 == 'update') {

			$errors = array();
			$ajax_data = array();

			//$receivable_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
			$code = $param2;

			//for payable payments
			$receivable_data['customer_id'] = strtoupper(trim($this->input->post('customer_name')));
			$receivable_data['date'] = $this->input->post('payment_date');
			$receivable_data['timestamp'] = strtotime($this->input->post('payment_date'));
			//$receivable_data['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			$receivable_data['amount'] = -$this->input->post('amount_received');
			$receivable_data['amount_paid'] = 0;
			$receivable_data['invoice_code'] = $code;
			$receivable_data['so_code'] = $code;
			$receivable_data['amount_due'] = -$this->input->post('amount_received');
			$receivable_data['account_id'] = $this->input->post('deposit_account');
			$receivable_data['payment_timestamp'] = strtotime(date('d-m-Y H:i:s'));

			//previous records and processing
			$prev_deposit = abs($this->db->get_where('invoice', array('customer_id' => $receivable_data['customer_id'], 'invoice_code' => $code))->row()->amount_due);
			$deposit_diff = $this->input->post('amount_received') - $prev_deposit;

			$account_used = $this->db->get_where('invoice', array('customer_id' => $receivable_data['customer_id'], 'invoice_code' => $code))->row()->account_id;

			if (empty($receivable_data['customer_id'])) {
				$errors['customer_id'] = 'Customer\'s name is required';
			}

			if (empty($receivable_data['date'])) {
				$errors['date'] = 'Please select a valid date';
			}

			if (empty($this->input->post('amount_received'))) {
				$errors['amount_paid'] = 'Please enter the amount received';
			}

			if ($this->input->post('amount_received') < 1) {
				$errors['amount_paid_invalid'] = 'Please enter a valid amount. Must be greater than 0.';
			}

			if (empty($this->input->post('deposit_account'))) {
				$errors['account_id'] = 'No Account was selecetd. Please select the Account you are depositing the money into';
			}

			//check error
			if (!empty($errors)) {
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {
				//update into the invoice table
				$this->db->where('customer_id', $receivable_data['customer_id']);
				$this->db->where('invoice_code', $code);
				$this->db->set('timestamp', $receivable_data['timestamp']);
				$this->db->set('payment_timestamp', $receivable_data['payment_timestamp']);
				$this->db->set('amount', 'amount - ' . $deposit_diff, FALSE);

				$this->db->set('amount_due', 'amount_due - ' . $deposit_diff, FALSE);
				$this->db->update('invoice');
			}

			//update accounts Receivable
			$this->db->where('name', 'Accounts Payable');
			$this->db->set('current_balance', 'current_balance + ' . $deposit_diff, FALSE);
			$this->db->update('accounts');

			//get total account balance for account payable
			$acp_balance = $this->db->get_where('accounts', array('name' => 'Accounts Payable'))->row()->current_balance;

			//CHECK IF THERE IS A CHANGE IN THE ACCOUNT PAID TO
			if ($account_used != $this->input->post('deposit_account')) {
				//a different account is chosen. Deduct the amount paid to that account back before proceeding with the new entry
				//update previous account paid to - subtract from it
				$account_paid_to_data['current_balance'] = $prev_deposit;
				$this->db->where('account_id', $account_used);
				$this->db->set('current_balance', 'current_balance - ' . $account_paid_to_data['current_balance'], FALSE);
				$this->db->update('accounts');

				//update current account paid to - add to it
				$account_paid_to_data['current_balance'] = $this->input->post('amount_received');
				$this->db->where('account_id', $this->input->post('deposit_account'));
				$this->db->set('current_balance', 'current_balance + ' . $account_paid_to_data['current_balance'], FALSE);
				$this->db->update('accounts');

			} else {
				//same account is selected
				//update account paid to - increase it
				$account_paid_to_data['current_balance'] = $deposit_diff;
				$this->db->where('account_id', $this->input->post('deposit_account'));
				$this->db->set('current_balance', 'current_balance + ' . $account_paid_to_data['current_balance'], FALSE);
				$this->db->update('accounts');
			}

			//$acpt_balance = $this->db->get_where('accounts', array('account_id' => $this->input->post('deposit_account')))->row()->current_balance;

			//Let's insert data into payment table
			$payment_data['payment_type'] = 'Deposit';
			//$payment_data['receipt_code'] = $receipt_code;
			$payment_data['customer_id'] = $this->input->post('customer_name');
			$payment_data['amount'] = $this->input->post('amount_received');
			//$payment_data['invoice_code'] = $code;
			//$payment_data['so_code'] = $code;
			$payment_data['due'] = 0;
			$payment_data['timestamp'] = strtotime($this->input->post('payment_date'));
			$payment_data['day_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			//$payment_data['date'] = $this->input->post('payment_date');
			$payment_data['account_id'] = $this->input->post('deposit_account');
			//$payment_data['track_code'] = $receivable_data['track_code'];
			$payment_data['issuer_id'] = $this->session->userdata('login_user_id');

			//insert now
			$this->db->where('customer_id', $payment_data['customer_id']);
			$this->db->where('invoice_code', $code);
			$this->db->update('payment', $payment_data);

			//journal id from payment table
			$this->db->where('customer_id', $payment_data['customer_id']);
			$this->db->where('invoice_code', $code);
			$journal_id = $this->db->get('payment')->row()->journal_id;

			//FOR GENERAL JOURNAL ENTRY CREDIT THIS
			//$journal_data_ar['payment_id'] = $payment_id;
			$journal_data_ar['timestamp'] = strtotime($this->input->post('payment_date'));
			$journal_data_ar['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			//$journal_data_ar['date'] = $this->input->post('payment_date');
			//$journal_data_ar['customer_id'] = $this->input->post('customer_name');
			//$journal_data_ar['invoice_code'] = $code;
			//$journal_data_ar['so_code'] = $code;
			//$journal_data_ar['journal'] = 'Deposits Received';
			//$journal_data_ar['account_name'] = 'Accounts Payable';
			$journal_data_ar['account_balance'] = $acp_balance;
			$journal_data_ar['credit_amount'] = $this->input->post('amount_received');
			$journal_data_ar['reference'] = $this->input->post('reference_number');
			$journal_data_ar['description'] = $this->input->post('journal_memo');
			$journal_data_ar['sales_person_id'] = $this->session->userdata('login_user_id');
			//$journal_data_g['sales_person_id']  = $this->session->userdata('login_user_id');

			//UPDATE NOW
			$this->db->where('customer_id', $payment_data['customer_id']);
			$this->db->where('invoice_code', $code);
			$this->db->where('account_name', 'Accounts Payable');
			$this->db->update('general_journal', $journal_data_ar);

			//FOR GENERAL JOURNAL ENTRY (ACCOUNT PAID TO) DEBIT THIS
			//$journal_data_apt['payment_id'] = $payment_id;
			$journal_data_apt['timestamp'] = strtotime($this->input->post('payment_date'));
			$journal_data_apt['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			//$journal_data_apt['date'] = $this->input->post('payment_date');
			//$journal_data_apt['customer_id'] = $this->input->post('customer_name');
			//$journal_data_apt['invoice_code'] = $code;
			//$journal_data_apt['so_code'] = $code;
			//$journal_data_apt['journal'] = 'Deposits Received';
			$journal_data_apt['account_name'] = $this->db->get_where('accounts', array('account_id' => $this->input->post('deposit_account')))->row()->name;
			//$journal_data_apt['account_balance'] = $acpt_balance;
			$journal_data_apt['debit_amount'] = $this->input->post('amount_received');
			$journal_data_apt['reference'] = $this->input->post('reference_number');
			$journal_data_apt['description'] = $this->input->post('journal_memo');
			$journal_data_apt['sales_person_id'] = $this->session->userdata('login_user_id');
			//$journal_data_ap['sales_person_id']  = $this->session->userdata('login_user_id');

			//UPDATE NOW
			$this->db->where('customer_id', $payment_data['customer_id']);
			$this->db->where('invoice_code', $code);
			$this->db->where('journal_id', $journal_id);
			$this->db->update('general_journal', $journal_data_apt);

			$ajax_data['success'] = true;
			$ajax_data['deposit_type'] = 'Deposit';
			echo json_encode($ajax_data);
		}
	}

	//Payments from Customers
	function payments_received($param1 = '', $param2 = '', $param3 = '', $param4 = '') {

		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//currency
		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);
		//Pay Payable Creation
		if ($param1 == 'create') {

			$errors = array();
			$ajax_data = array();

			$paymentMethodsIdsPayment = $this->input->post('paymentMethodsIdsPayment');

			$payment_ids = explode(',', $paymentMethodsIdsPayment);
			sort($payment_ids);

			$receivable_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
			//for payable payments
			$receivable_data['customer_id'] = strtoupper(trim($this->input->post('customer_name')));
			$receivable_data['date'] = $this->input->post('payment_date');
			$receivable_data['timestamp'] = strtotime($this->input->post('payment_date'));
			$receivable_data['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			$receivable_data['amount_paid'] = $this->input->post('amount_received');
			$receivable_data['amount_tendered'] = $this->input->post('amount_tendered');
			$receivable_data['change_due'] = $receivable_data['amount_tendered'] - $receivable_data['amount_paid'];
			//$receivable_data['account_id'] = $this->input->post('deposit_account');
			$receivable_data['invoice_code'] = $this->input->post('invoice_code');

			$total_receivable = $this->input->post('hidden_total_receivable');

			//validate
			/*if ($receivable_data['amount_paid'] > $total_receivable) {
	                $errors['total_receivable'] = 'You are taking over payment! The amount receivable to this Invoice Code [' . $receivable_data['invoice_code'] . '] is: ' . numfmt_format_currency($fmt, $total_receivable, $currency) . ' and Your entry is: ' . numfmt_format_currency($fmt, $receivable_data['amount_paid'], $currency);
			*/

			if (empty($receivable_data['customer_id'])) {
				$errors['customer_id'] = 'Customer\'s name is required';
			}

			if (empty($receivable_data['date'])) {
				$errors['date'] = 'Please select a valid date';
			}

			if (empty($receivable_data['invoice_code'])) {
				$errors['invoice_code'] = 'Please make sure the invoice code is selected.';
			}

			if (empty($receivable_data['amount_paid'])) {
				$errors['amount_paid'] = 'Please enter the amount received';
			}

			if ($receivable_data['amount_paid'] < 1) {
				$errors['amount_paid_invalid'] = 'Please enter a valid amount. Must be greater than 0.';
			}

			if (empty($receivable_data['amount_tendered'])) {
				$errors['amount_tendered'] = 'Please enter the amount tendered';
			}

			if ($receivable_data['amount_tendered'] < 1) {
				$errors['amount_tendered_invalid'] = 'Please enter a valid amount tendered. Must be greater than 0.';
			}

			if ($receivable_data['amount_paid'] > $receivable_data['amount_tendered']) {
				$errors['received_tendered_error'] = 'Check your entries! It seems the amount tendered is less than the amount received.';
			}

			if (empty($this->input->post('deposit_account'))) {
				$errors['account_id'] = 'No Account was selecetd. Please select the Account you are depositing the money into';
			}

			//check error
			if (!empty($errors)) {
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				$receipt_code = 'DP1REC-' . date('Y') . date('m') . date('d') . date('H') . date('i') . date('s');

				$journal_data_apt['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$journal_data_ar['date_timestamp'] = $journal_data_apt['date_timestamp'];
				$payment_data['day_timestamp'] = $journal_data_apt['date_timestamp'];
				$payment_timestamp = $journal_data_apt['date_timestamp'];


				/*let's start each account selected here and do it account by account*/
				for($p = 0; $p < sizeof($payment_ids); $p++):

					/*Do this on payment account selected basis*/
					
					$total_amount_paid_now = $this->input->post('method_amount_payment_'.$payment_ids[$p]);
					

					$invoice_codes_arr = array();
					$so_codes_arr = array();


					if ($receivable_data['invoice_code'] == 'general') {
						//we are doing general payment
						

						$invoice_counter = 1;

						//WE NEED TO GET ALL THE INVOICES THAT THIS CUSTOMER IS OWING
						$invoices_owing_query = $this->db->get_where('invoice', array('customer_id' => $receivable_data['customer_id'], 'amount_due >' => 0));
						if ($invoices_owing_query->num_rows() > 0) {
							//we have some
							$invoices_owing_array = $invoices_owing_query->result_array();

							//Beginning of each invoice code's work
							foreach ($invoices_owing_array as $inc) {
								//get the previous amount paid for each invoice code
								/*$prev_paid_amount = $this->db->get_where('invoice', array('customer_id' => $inc['customer_id'], 'invoice_code' => $inc['invoice_code']))->row()->amount_paid;
								//update the prev_paid column with this amount
								$this->db->where('customer_id', $inc['customer_id']);
								$this->db->where('invoice_code', $inc['invoice_code']);
								$this->db->set('prev_paid', $prev_paid_amount);
								$this->db->update('invoice');*/

								$receivable_for_this_invoice_code = $this->db
									->select_sum('amount_due')
									->where('amount_due >', 0)
									->where('customer_id', $inc['customer_id'])
									->where('invoice_code', $inc['invoice_code'])
									->get('invoice')->row()->amount_due;

								//update INVOICE table
								if ($receivable_for_this_invoice_code >= $total_amount_paid_now) {
									//means the amount paid is not even enough to settle this invoice balance

									$this->db->where('customer_id', $inc['customer_id']);
									$this->db->where('invoice_code', $inc['invoice_code']);
									$this->db->set('payment_timestamp', strtotime(date('d-m-Y H:i:s')));
									$this->db->set('amount_paid', 'amount_paid +' . $total_amount_paid_now, FALSE);
									$this->db->set('amount_due', 'amount_due -' . $total_amount_paid_now, FALSE);
									$this->db->set('track_code', $receivable_data['track_code']);
									//$this->db->set('account_id', $receivable_data['account_id']);
									//$this->db->set('p_prev_paid', $prev_paid['prev_paid']);
									$this->db->update('invoice');

									//update status
									$bal_due = $this->db->get_where('invoice', array('track_code' => $receivable_data['track_code'], 'customer_id' => $inc['customer_id'], 'invoice_code' => $inc['invoice_code']))->row()->amount_due;

									$total_amount = $this->db->get_where('invoice', array('track_code' => $receivable_data['track_code'], 'customer_id' => $inc['customer_id'], 'invoice_code' => $inc['invoice_code']))->row()->amount;

									//status update
									if ($bal_due < $total_amount) {
										if ($bal_due == 0) {
											$so_status['status'] = 'Paid';
										} else if ($bal_due < 0) {
											$so_status['status'] = 'Over Paid';
										} else {
											$so_status['status'] = 'Partially Paid';
										}

									} else if ($bal_due == $total_amount) {
										$so_status['status'] = 'Unpaid';
									}

									//update status
									$this->db->where('track_code', $receivable_data['track_code']);
									$this->db->where('invoice_code', $inc['invoice_code']);
									$this->db->where('customer_id', $inc['customer_id']);

									$this->db->set('status', $so_status['status']);
									$this->db->update('invoice');

									//TIME FOR UPDATES ON THE SALES ORDER & PAYMENT WITH GOODS TABLE
									$this->db->where('customer_id', $inc['customer_id']);
									$this->db->where('so_code', $inc['so_code']);
									$this->db->set('status', $so_status['status']);
									$this->db->set('amount_paid', 'amount_paid +' . $total_amount_paid_now, FALSE);
									$this->db->set('amount_due', 'amount_due -' . $total_amount_paid_now, FALSE);
									$this->db->set('track_code', $receivable_data['track_code']);
									$this->db->update('sales_order');

									$this->db->where('customer_id', $inc['customer_id']);
									$this->db->where('so_code', $inc['so_code']);
									$this->db->set('status', $so_status['status']);
									$this->db->set('amount_paid', 'amount_paid +' . $total_amount_paid_now, FALSE);
									$this->db->set('amount_due', 'amount_due -' . $total_amount_paid_now, FALSE);
									$this->db->set('track_code', $receivable_data['track_code']);
									$this->db->update('payment_with_goods');

									//update accounts Receivable - reduce it
									$accounts_receivable_data['current_balance'] = $total_amount_paid_now;

									$this->db->where('name', 'Accounts Receivable');
									$this->db->set('current_balance', 'current_balance - ' . $accounts_receivable_data['current_balance'], FALSE);
									$this->db->update('accounts');

									//get total account balance for account rec
									$acr_balance = $this->db->get_where('accounts', array('name' => 'Accounts Receivable'))->row()->current_balance;

									//update account paid to - increase it
									$account_paid_to_data['current_balance'] = $total_amount_paid_now;

									$this->db->where('account_id', $payment_ids[$p]);
									$this->db->set('current_balance', 'current_balance + ' . $account_paid_to_data['current_balance'], FALSE);
									$this->db->update('accounts');

									//get total account balance for Account paid to
									$acpt_balance = $this->db->get_where('accounts', array('account_id' => $payment_ids[$p]))->row()->current_balance;

									//FOR PAYMENT TABLE
									//first, let's update the previous payment track code for this so_code with with the current track code
									$this->db->where('customer_id', $this->input->post('customer_name'));
									$this->db->where('so_code', $inc['so_code']);
									$this->db->where('invoice_code', $inc['invoice_code']);
									$this->db->set('track_code', $receivable_data['track_code']);
									$this->db->update('payment');

