	/*Worked on for multiple accounts selection but is on hold for a while*/
	function payments_received_backup($param1 = '', $param2 = '', $param3 = '', $param4 = '') {

		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//currency
		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);
		//Pay Payable Creation
		if ($param1 == 'create') {

			$errors = array();
			$ajax_data = array();

			$paymentMethodsIdsPayment = $this->input->post('paymentMethodsIdsPayment');

			$payment_ids = explode(',', $paymentMethodsIdsPayment);
			sort($payment_ids);


			$receivable_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);
			//for payable payments
			$receivable_data['customer_id'] = strtoupper(trim($this->input->post('customer_name')));
			$receivable_data['date'] = $this->input->post('payment_date');
			$receivable_data['timestamp'] = strtotime($this->input->post('payment_date'));
			$receivable_data['creation_timestamp'] = strtotime(date('d-m-Y H:i:s'));
			$receivable_data['amount_paid'] = $this->input->post('amount_received');
			$receivable_data['amount_tendered'] = $this->input->post('amount_tendered');
			$receivable_data['change_due'] = $receivable_data['amount_tendered'] - $receivable_data['amount_paid'];
			//$receivable_data['account_id'] = $this->input->post('deposit_account');
			$receivable_data['invoice_code'] = $this->input->post('invoice_code');

			$total_receivable = $this->input->post('hidden_total_receivable');

			/*$aData['test'] = $receivable_data['amount_paid'];
			echo json_encode($aData);
			return;*/

			//validate
			/*if ($receivable_data['amount_paid'] > $total_receivable) {
	                $errors['total_receivable'] = 'You are taking over payment! The amount receivable to this Invoice Code [' . $receivable_data['invoice_code'] . '] is: ' . numfmt_format_currency($fmt, $total_receivable, $currency) . ' and Your entry is: ' . numfmt_format_currency($fmt, $receivable_data['amount_paid'], $currency);
		*/

			if (empty($receivable_data['customer_id'])) {
				$errors['customer_id'] = 'Customer\'s name is required';
			}

			if (empty($receivable_data['date'])) {
				$errors['date'] = 'Please select a valid date';
			}

			if (empty($receivable_data['invoice_code'])) {
				$errors['invoice_code'] = 'Please make sure the invoice code is selected.';
			}

			if (empty($receivable_data['amount_paid'])) {
				$errors['amount_paid'] = 'Please enter the amount received';
			}

			if ($receivable_data['amount_paid'] < 1) {
				$errors['amount_paid_invalid'] = 'Please enter a valid amount. Must be greater than 0.';
			}

			if (empty($receivable_data['amount_tendered'])) {
				$errors['amount_tendered'] = 'Please enter the amount tendered';
			}

			if ($receivable_data['amount_tendered'] < 1) {
				$errors['amount_tendered_invalid'] = 'Please enter a valid amount tendered. Must be greater than 0.';
			}

			if ($receivable_data['amount_paid'] > $receivable_data['amount_tendered']) {
				$errors['received_tendered_error'] = 'Check your entries! It seems the amount tendered is less than the amount received.';
