	//for customers' unique prices
	function pricing($param1 = '', $param2 = '', $param3 = '', $param4 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'update') {
			$items_ids = explode('-', $param2);
			$customer_id = $param3;

				//get customer's id
				$price_data['customer_id'] = $customer_id;
				$price_data_unit['customer_id'] = $customer_id;
				//$price_data['customer_status'] = 1;

				//if these dates range exist, then the user just wanna make a simple update
				$date_row = $this->db->get_where('items_prices', array('customer_id' => $price_data['customer_id']))->num_rows();

				$customerData = [];
				$customerNewItemData = [];
				$customerDataUnit = [];
				$customerNewItemDataUnit = [];

				if ($date_row < 1) {
					//no match, so new entry
					//insert customer_id into the price table first

					//item's price

					

					for ($j = 0; $j < sizeof($items_ids); $j++) {

						// Goes to the main price table - items_prices
						$price_data['item_id'] = $items_ids[$j];
						$price_data['item_price'] = $this->input->post('price_' . $items_ids[$j] . $price_data['customer_id']);


						if($price_data['item_price'] == 0 || $price_data['item_price'] == '0') {
							$price_data['item_price'] = $this->db->get_where('items', ['item_id' => $items_ids[$j]])->row()->selling_price;
						}

						// Goes to the units item price table - items_units_prices
						$price_data_unit['item_id'] = $items_ids[$j];
						$price_data_unit['item_price'] = $this->input->post('unit_price_' . $items_ids[$j] . $price_data['customer_id']);
						$price_data_unit['unit_id'] = $this->input->post('unit_id_' . $items_ids[$j] . $price_data['customer_id']);

						$customerData[] = $price_data;
						$customerDataUnit[] = $price_data_unit;
					}

					//Insert the price table now with the price list for each item/goods
					$this->db->insert_batch('items_prices', $customerData);
					$this->db->insert_batch('items_units_prices', $customerDataUnit);

				} else {

					//match, so do update

					for ($j = 0; $j < sizeof($items_ids); $j++) {

						//check if this item exists in the prices table for this customer
						$prices_row = $this->db->get_where('items_prices', array('customer_id' => $price_data['customer_id'], 'item_id' => $items_ids[$j]))->num_rows();

						if($prices_row < 1) {
							//not exists
							$price_new_data['item_id'] = $items_ids[$j];
							$price_new_data['item_price'] = $this->input->post('price_' . $items_ids[$j] . $price_data['customer_id']);
							$price_new_data['customer_id'] = $customer_id;

							$customerNewItemData[] = $price_new_data;


						} else {
							$price_data_update['item_price'] = $this->input->post('price_' . $items_ids[$j] . $price_data['customer_id']);

							if($price_data_update['item_price'] == 0 || $price_data['item_price'] == '0') {
								$price_data_update['item_price'] = $this->db->get_where('items', ['item_id' => $items_ids[$j]])->row()->selling_price;
							}

							//Update the price table now with the price list for each item/goods
							$this->db->where('item_id', $items_ids[$j]);
							$this->db->where('customer_id', $customer_id);
							$this->db->update('items_prices', $price_data_update);
						}


						//for units prices table
						//check if this item exists in the prices table for this customer

						$prices_row_unit = $this->db->get_where('items_units_prices', array('customer_id' => $price_data['customer_id'], 'item_id' => $items_ids[$j]))->num_rows();

						$this->db->where('item_id', $items_ids[$j]);
						$isSoldInUnit = $this->db->get('items')->row()->item_sold_in_units;

						if($isSoldInUnit == '0' || $isSoldInUnit < 1) {
							continue; //move on to the next item since this is not sold in unit
						} 

						

						if($prices_row_unit < 1) {

							//not exists 
							$price_new_data_unit['item_id'] = $items_ids[$j];
							$price_new_data_unit['item_price'] = $this->input->post('unit_price_' . $items_ids[$j] . $price_data['customer_id']);
							$price_new_data_unit['unit_id'] = $this->input->post('unit_id_' . $items_ids[$j] . $price_data['customer_id']);
							$price_new_data_unit['customer_id'] = $customer_id;

							$customerNewItemDataUnit[] = $price_new_data_unit;

						} else {

							$price_data_update_unit['item_price'] = $this->input->post('unit_price_' . $items_ids[$j] . $price_data['customer_id']);

							//Update the price table now with the price list for each item/goods

							$this->db->where('item_id', $items_ids[$j]);
							$this->db->where('customer_id', $customer_id);
							$this->db->update('items_units_prices', $price_data_update_unit);
						}
					} //end of loop


					if($prices_row < 1 && count($customerNewItemData) > 0) {
						//Insert the price for the new items added if data exists
						$this->db->insert_batch('items_prices', $customerNewItemData);
					}

					if($prices_row_unit < 1 && count($customerNewItemDataUnit) > 0) {
						//Insert the price for the new items added if data exists
						$this->db->insert_batch('items_units_prices', $customerNewItemDataUnit);
					}
				}
			

			$ajax_data['success'] = true;
			echo json_encode($ajax_data);

		}
	}

//**ITEMS TRANSFERS CREATION, UPDATES AND DELETION**/
	function items_transfer($param1 = '', $param2 = '', $param3 = '', $param4 = '') {
		if ($this->session->userdata('admin_login') != 1) {
			redirect(site_url('login'), 'refresh');
		}

		//get form data
		if ($param1 == 'create') {

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			//imported ids array
			$input_ids_numeric = explode('-', $param2);

			//FOR ITEMS TRANSFERS TABLE
			$items_tranfers_create_data['token_no'] = $this->input->post('token_no');
			$items_tranfers_create_data['receiver'] = $this->input->post('transfer_to');
			$items_tranfers_create_data['date_timestamp'] = strtotime($this->input->post('transfer_date'));
			$items_tranfers_create_data['timestamp'] = strtotime(date('d-m-Y H:i:s'));
			$items_tranfers_create_data['date'] = $this->input->post('transfer_date');
			$items_tranfers_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			//check if any required field is empty
			if (empty($items_tranfers_create_data['token_no'])) {
				$errors['token_no'] = 'Token Number cannot be empty';
			}

			if (empty($items_tranfers_create_data['receiver'])) {
				$errors['receiver'] = 'You must select the receiver of the item(s)';
			}

			if (empty($items_tranfers_create_data['date'])) {
				$errors['date'] = 'Transfer Date cannot be empty';
			}

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$t_item_ids = array();
			$s_counter2 = 0;
			$t_item_ids2 = array();
			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$t_quantity = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);

				$t_item_id = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);

				$quantity_left = $this->db->get_where('items', array('item_id' => $t_item_id))->row()->quantity;

				if ($t_quantity > $quantity_left) {
					$s_counter2++;
					array_push($t_item_ids2, $this->db->get_where('items', array('item_id' => $t_item_id))->row()->item_name);
				}

			}

			if ($s_counter2 > 0) {
				$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transfer.';
				//$errors['item_ids'] = $t_item_ids2
			}

			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				//collect data for each item bought
				for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

					$items_tranfers_create_data['quantity'] = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);

					$items_tranfers_create_data['item_id'] = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);

					$items_tranfers_create_data['html_id'] = $input_ids_numeric[$i];

					$items_tranfers_create_data['total_quantity'] = $this->input->post('hidden_total_quantity');

					//check if any required field is empty
					if (empty($items_tranfers_create_data['quantity'])) {
						$errors['quantity'] = 'Quantity transferred cannot be empty';
					}

					if (empty($items_tranfers_create_data['item_id'])) {
						$errors['item_id'] = 'You must select an Item';
					}

					//if there's error
					if (!empty($errors)) {
						//error found, let's notify the user of it
						$ajax_data = $errors;
						echo json_encode($ajax_data);
					} else {
						//No error found, now we can insert data
						$this->db->insert('items_transfers', $items_tranfers_create_data);

						//get s order id
						$t_id = $this->db->insert_id();

						//update item table
						$item_data['quantity'] = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);
						$item_data['last_used_timestamp'] = strtotime($this->input->post('transfer_date2'));
						$item_id = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);

						//do update now
						$this->db->where('item_id', $item_id);
						$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
						$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
						$this->db->update('items');

						//do update item balance in the transfer table
						$current_item_q = $this->db->get_where('items', array('item_id' => $item_id))->row()->quantity;
						$this->db->where('t_id', $t_id);
						$this->db->set('item_balance', $current_item_q);
						$this->db->update('items_transfers');

					}
				} //End of loop

				if (empty($errors)) {

					//FOR GENERAL JOURNAL ENTRY (RECEIVER) DEBIT THIS
					$journal_data_rc['timestamp'] = strtotime($this->input->post('transfer_date'));
					$journal_data_rc['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					$journal_data_rc['date'] = $this->input->post('transfer_date');
					$journal_data_rc['token_no'] = $this->input->post('token_no');
					$journal_data_rc['item_transfer_receiver'] = $this->input->post('transfer_to');
					$journal_data_rc['journal'] = 'Item Transfer';
					$journal_data_rc['debit_amount'] = $this->input->post('hidden_total_quantity');
					$journal_data_rc['reference'] = '';
					$journal_data_rc['description'] = 'Item(s) Transferred to ' . $journal_data_rc['item_transfer_receiver'];
					$journal_data_rc['sales_person_id'] = $this->session->userdata('login_user_id');

					//INSERT NOW
					$this->db->insert('general_journal', $journal_data_rc);

					$journal_debit_id = $this->db->insert_id();

					//update the items transfers table
					$this->db->where('token_no', $journal_data_rc['token_no']);
					$this->db->set('journal_debit_id', $journal_debit_id);
					$this->db->update('items_transfers');

					//FOR GENERAL JOURNAL ENTRY (ITEM) CREDIT THIS
					$journal_data_it['timestamp'] = strtotime($this->input->post('transfer_date'));
					$journal_data_it['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					$journal_data_it['date'] = $this->input->post('transfer_date');
					$journal_data_it['token_no'] = $this->input->post('token_no');
					$journal_data_it['journal'] = 'Item Transfer';

					$journal_data_it['credit_amount'] = $this->input->post('hidden_total_quantity');
					$journal_data_it['item_transfer_receiver'] = $this->input->post('transfer_to');
					$journal_data_it['reference'] = '';
					$journal_data_it['description'] = 'Item(s) Transferred to ' . $journal_data_it['item_transfer_receiver'];
					$journal_data_it['sales_person_id'] = $this->session->userdata('login_user_id');

					//INSERT NOW
					$this->db->insert('general_journal', $journal_data_it);

					$journal_credit_id = $this->db->insert_id();

					//update the items transfers table
					$this->db->where('token_no', $journal_data_it['token_no']);
					$this->db->set('journal_credit_id', $journal_credit_id);
					$this->db->update('items_transfers');

					////return now
					$ajax_data['success'] = true;
					echo json_encode($ajax_data);
				}
			}

		}

		//Editing ITEMS TRANSFERS HERE
		if ($param1 == 'update') {
			$token_no = $param2;

			$journal_debit_id = $this->db->get_where('items_transfers', array('token_no' => $token_no))->row()->journal_debit_id;
			$journal_credit_id = $this->db->get_where('items_transfers', array('token_no' => $token_no))->row()->journal_credit_id;

			//$paid_data['track_code'] = substr(sha1(md5(mt_rand(1034200000, strtotime(date('d-m-Y H:i:s'))))), 0, 15);

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$_items_ids = array();

			//No update after a day
			$timestamp = $this->db->get_where('items_transfers', array('token_no' => $token_no))->row()->date_timestamp;
			$today = strtotime(date('d-m-Y'));

			//imported ids array
			$input_ids_numeric = explode('-', $param3);

			//FOR ITEMS TRANSFER TABLE
			$items_tranfers_create_data['receiver'] = $this->input->post('transfer_to');
			$items_tranfers_create_data['timestamp'] = strtotime(date('d-m-Y H:i:s'));
			//$items_tranfers_create_data['date_timestamp'] = strtotime($this->input->post('order_date'));
			//$items_tranfers_create_data['date'] = $this->input->post('order_date');
			$items_tranfers_create_data['sales_person_id'] = $this->session->userdata('login_user_id');

			//get previous prev_paid amount from the accounts_payable table
			//$prev_paid['prev_paid'] = $this->db->get_where('invoice', array('token_no' => $token_no, 'customer_id' => $items_tranfers_create_data['customer_id']))->row()->prev_paid;

			//get the earlier balance and subtract it before effecting the new update
			//$receivable_adjust_paid['current_balance'] = $this->db->get_where('items_transfers', array('token_no' => $token_no))->row()->amount_paid;
			//$receivable_adjust['current_balance'] = $this->db->get_where('items_transfers', array('token_no' => $token_no))->row()->grand_total;

			//check if any required field is empty

			if ($timestamp != $today) {
				// $errors['outdated'] = 'Sorry! You cannot edit an entry that is a day old. Contact your system Administrator.';
			}

			if (empty($items_tranfers_create_data['receiver'])) {
				$errors['transfer_to'] = 'You must select the receiver of the transfer';
			}

			//check if quantity picked is more than total quantity
			$s_counter = 0;
			$t_item_ids = array();
			$s_counter2 = 0;
			$t_item_ids2 = array();
			for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {
				$t_quantity = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);

				$t_item_id = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);

				//previous quantity
				$t_quantity_prev = $this->db->get_where('items_transfers', array('token_no' => $token_no, 'item_id' => $t_item_id))->row()->quantity;

				$actual_item_q = $t_quantity - $t_quantity_prev;

				$quantity_left = $this->db->get_where('items', array('item_id' => $t_item_id))->row()->quantity;

				if ($actual_item_q > $quantity_left) {
					$s_counter2++;
					array_push($t_item_ids2, $this->db->get_where('items', array('item_id' => $t_item_id))->row()->item_name);
				}

			}

			if ($s_counter2 > 0) {
				$errors['stock'] = 'Some items or goods are runnning out of stock. The quantity left is not enough for this transfer.';
				//$errors['item_ids'] = $t_item_ids2
			}

			//check for duplicate
			/**if(!p_order_validation_update($this->input->post('order_no'))) {

	                    $ajax_data['success'] = 'duplicate';
	                    $ajax_data['token_no'] = $items_tranfers_create_data['token_no'];
	                    echo json_encode($ajax_data);
*/
			if (!empty($errors)) {
				//error found, let's notify the user of it
				$ajax_data = $errors;
				echo json_encode($ajax_data);
			} else {

				//collect data for each item bought
				for ($i = 0; $i < sizeof($input_ids_numeric); $i++) {

					$items_tranfers_create_data['quantity'] = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);

					$items_tranfers_create_data['item_id'] = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);

					$items_tranfers_create_data['html_id'] = $input_ids_numeric[$i];

					$items_tranfers_create_data['total_quantity'] = $this->input->post('hidden_total_quantity');

					//check if any required field is empty
					if (empty($items_tranfers_create_data['quantity'])) {
						$errors['quantity'] = 'Quantity transferred cannot be empty';
					}

					if (empty($items_tranfers_create_data['item_id'])) {
						$errors['item_id'] = 'You must select an Item';
					}

					//if there's error
					if (!empty($errors)) {
						//error found, let's notify the user of it
						$ajax_data = $errors;
						echo json_encode($ajax_data);
					} else {
						//No error found, now we can update data
						$item_id = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);
						//get previous quantity transferred from the items transfers table
						$item_quantity['quantity'] = $this->db->get_where('items_transfers', array('token_no' => $token_no, 'item_id' => $item_id))->row()->quantity;

						//incase the user added another item, let's insert it...
						$item_rows = $this->db->get_where('items_transfers', array('token_no' => $token_no, 'item_id' => $item_id))->num_rows();

						if ($item_rows < 1) {

							//this is a new item added so let's insert it into the table
							$items_tranfers_create_data['token_no'] = $token_no;
							$items_tranfers_create_data['date_timestamp'] = strtotime($this->input->post('transfer_date'));
							$items_tranfers_create_data['date'] = $this->input->post('transfer_date');

							$this->db->insert('items_transfers', $items_tranfers_create_data);

							//get transfer id
							$t_id = $this->db->insert_id();

							//update with the debit and credit journal ids
							$this->db->where('t_id', $t_id);
							$this->db->where('token_no', $token_no);
							$this->db->set('journal_debit_id', $journal_debit_id);
							$this->db->set('journal_credit_id', $journal_credit_id);
							$this->db->update('items_transfers');

							//update item table
							$item_data['quantity'] = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);
							$item_data['last_used_timestamp'] = strtotime($this->input->post('transfer_date2'));
							$item_id = $this->input->post('item_transferred_' . $input_ids_numeric[$i]);
							//do update now
							$this->db->where('item_id', $item_id);
							$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
							$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
							$this->db->update('items');

							//do update item balance in the transfer table
							$current_item_q = $this->db->get_where('items', array('item_id' => $item_id))->row()->quantity;
							$this->db->where('t_id', $t_id);
							$this->db->set('item_balance', $current_item_q);
							$this->db->update('items_transfers');

						} else {

							//or let's do normal updates

							$this->db->where('token_no', $token_no);
							$this->db->where('item_id', $item_id);
							$this->db->update('items_transfers', $items_tranfers_create_data);

							//normal editing...

							//update item table
							//get the earlier quantity and add it before effecting the new update

							//add it back
							$this->db->where('item_id', $item_id);
							$this->db->set('quantity', 'quantity + ' . $item_quantity['quantity'], FALSE);
							$this->db->update('items');
							//end of adjustment

							$item_data['quantity'] = $this->input->post('quantity_transferred_' . $input_ids_numeric[$i]);
							$item_data['last_used_timestamp'] = strtotime($this->input->post('transfer_date2'));

							//do update now Subtract
							$this->db->where('item_id', $item_id);
							$this->db->set('last_used_timestamp', $item_data['last_used_timestamp']);
							$this->db->set('quantity', 'quantity - ' . $item_data['quantity'], FALSE);
							$this->db->update('items');

							//do update item balance in the transfer table
							$current_item_q = $this->db->get_where('items', array('item_id' => $item_id))->row()->quantity;
							$this->db->where('token_no', $token_no);
							$this->db->where('item_id', $item_id);
							$this->db->set('item_balance', $current_item_q);
							$this->db->update('items_transfers');

						}

						//Now delete this row from items transfers table
						$this->db->where('token_no', $item['token_no']);
						$this->db->where('receiver', $items_tranfers_create_data['receiver']);
						$this->db->where('item_id', $item['item_id']);
						$tRow = $this->db->get('items_transfers')->row();
						$tQ = $tRow->quantity;
						$tID = $tRow->t_id;

						if($tQ == 0) {

							$this->db->where('t_id', $tID);
							$this->db->delete('items_transfers');
						}
						

						//grab the current item ids
						array_push($_items_ids, $item_id);
					}

				} //End of loop

				if (empty($errors)) {
					//incase user used different items apart from the earlier one, let's update it and delete it from items transfers table

					$this->db->where('token_no', $token_no);
					$this->db->where('receiver', $items_tranfers_create_data['receiver']);
					$this->db->where_not_in('item_id', $_items_ids);
					$items_ids_array = $this->db->get('items_transfers')->result_array();

					foreach ($items_ids_array as $item) {
						//add the quantity back
						$this->db->where('item_id', $item['item_id']);
						$this->db->set('quantity', 'quantity + ' . $item['quantity'], FALSE);
						$this->db->update('items');

						//Now delete this row from items transfers table
						$this->db->where('token_no', $item['token_no']);
						$this->db->where('receiver', $items_tranfers_create_data['receiver']);
						$this->db->where('item_id', $item['item_id']);
						$this->db->delete('items_transfers');
					}

					//UPDATE JOURNAL FOR DEBIT QUANTITY
					$journal_data_rc['timestamp'] = strtotime($this->input->post('transfer_date'));
					$journal_data_rc['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					$journal_data_rc['item_transfer_receiver'] = $this->input->post('transfer_to');
					$journal_data_rc['journal'] = 'Item Transfer';
					$journal_data_rc['token_no'] = $this->input->post('token_no');
					$journal_data_rc['debit_amount'] = $this->input->post('hidden_total_quantity');
					$journal_data_rc['reference'] = '';
					$journal_data_rc['description'] = 'Item(s) Transferred to ' . $journal_data_rc['item_transfer_receiver'];
					$journal_data_rc['sales_person_id'] = $this->session->userdata('login_user_id');

					//UPDATE NOW
					$this->db->where('token_no', $token_no);
					$this->db->where('journal_id', $journal_debit_id);
					$this->db->update('general_journal', $journal_data_rc);

					//UPDATE JOURNAL FOR CREDIT AMOUNT
					$journal_data_it['timestamp'] = strtotime($this->input->post('transfer_date'));
					$journal_data_it['date_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					$journal_data_it['item_transfer_receiver'] = $this->input->post('transfer_to');

					$journal_data_it['token_no'] = $this->input->post('token_no');
					$journal_data_it['journal'] = 'Item Transfer';
					$journal_data_it['credit_amount'] = $this->input->post('hidden_total_quantity');
					$journal_data_it['reference'] = '';
					$journal_data_it['description'] = 'Item(s) Transferred to ' . $journal_data_it['item_transfer_receiver'];
					$journal_data_it['sales_person_id'] = $this->session->userdata('login_user_id');

					//UPDATE NOW
					$this->db->where('token_no', $token_no);
					$this->db->where('journal_id', $journal_credit_id);
					$this->db->update('general_journal', $journal_data_it);

					////return now
					$ajax_data['success'] = true;
					echo json_encode($ajax_data);
				}
				// }
			}

		}

		if ($param1 == 'delete') {
			//Delete Sales Order here'
			$token_no = $param2;

			//Track errors and success
			$errors = array();
			$ajax_data = array();

			$this->crud_model->delete_items_transfers($token_no);

		}

	}

	/**OTHER SHORT FUNCTIONS HERE**/

	//fetch price list
	function get_price_list() {
		//$page_data['from'] = strtotime($from);
		//$page_data['to'] = strtotime($to);
		$page_data['customer_id'] = $this->input->post('customer_id');

		$this->load->view('backend/admin/pages/sales/get_price_list', $page_data);
	}

	function get_supplier_address($supplier_id) {
		$sup_data['all_items_array'] = $this->db->get('items')->result_array();

		$sup_data['address'] = $this->db->get_where('suppliers', array('supplier_id' => $supplier_id))->row()->address;

		//send back to the ajax request
		$ajax_data = array();
		$ajax_data = $sup_data;
		echo json_encode($ajax_data);
	}

	function get_payable($supplier_id, $param2 = '') {

		if ($param2 == 'debt') {
			//oustanding debts
			echo $this->db->get_where('outstanding_debts', array('debt_id' => $supplier_id))->row()->amount_due;

		} else if ($param2 == 'negative_bal') {
//negative balance customers

			$customer_id = $supplier_id;

			$this->db->select_sum('amount_due');
			$this->db->where('amount_due <', 0);
			echo abs($this->db->get_where('invoice', array('customer_id' => $customer_id))->row()->amount_due);

		} else {
			if ($param2 != '0') {
				$po_code = append_words($param2, '_');

				$this->db->select_sum('amount_due');
				$this->db->where('supplier_id', $supplier_id);
				$this->db->where('amount_due > ', '0');
				$this->db->where('po_code', $po_code);
				$query = $this->db->get('accounts_payable')->row()->amount_due;

				if ($query != '') {
					$payable = $query;
				} else {
					$payable = 0;
				}
				echo $payable;
			} else {
				$this->db->select_sum('amount_due');
				$this->db->where('amount_due >', 0);
				$this->db->where('supplier_id', $supplier_id);
				$query = $this->db->get('accounts_payable')->row()->amount_due;

				if ($query != '') {
					$payable = $query;
				} else {
					$payable = 0;
				}
				echo $payable;

			}

		}

	}

	function get_receivable($customer_id, $invoice_code = '') {

		if ($invoice_code == '') {

			$this->db->select_sum('amount_due');
			$this->db->where('amount_due >', 0);
			$data['balance_due'] = $this->db->get_where('invoice', array('customer_id' => $customer_id))->row()->amount_due;
			$data['invoice_code'] = 0;

			$this->db->select_sum('amount_paid');
			$this->db->where('amount_paid >', 0);
			$data['prev_amount_received'] = $this->db->get_where('invoice', array('customer_id' => $customer_id))->row()->amount_paid;

		} else {
			$data['so_code'] = $this->db->get_where('invoice', array('invoice_code' => $invoice_code))->row()->so_code;
			$data['invoice_code'] = $invoice_code;

			$this->db->select_sum('amount_due');
			$this->db->where('amount_due >', 0);
			$data['balance_due'] = $this->db->get_where('invoice', array('customer_id' => $customer_id, 'invoice_code' => $invoice_code))->row()->amount_due;

			$data['prev_amount_received'] = $this->db->get_where('invoice', array('customer_id' => $customer_id, 'invoice_code' => $data['invoice_code']))->row()->amount_paid;
		}

		echo json_encode($data);
	}

