	function get_receivable_per_inv_code($customer_id, $inv_code = '') {

		if ($inv_code == '' || $inv_code == 'general') {
			$this->db->select_sum('amount_due');
			$this->db->where('amount_due >', 0);
			$this->db->where('customer_id', $customer_id);
			$data['amount_due'] = $this->db->get('invoice')->row()->amount_due;

			$this->db->select_sum('amount_paid');
			$this->db->where('amount_paid >', 0);
			$this->db->where('customer_id', $customer_id);
			$data['prev_amount_received'] = $this->db->get('invoice')->row()->amount_paid;

			echo json_encode($data);
		} else {

			$inv_code = append_words($inv_code, '_');

			$this->db->select_sum('amount_due');
			$this->db->where('amount_due >', 0);
			$this->db->where(array('customer_id' => $customer_id, 'invoice_code' => $inv_code));
			$data['amount_due'] = $this->db->get('invoice')->row()->amount_due;

			$this->db->where(array('customer_id' => $customer_id, 'invoice_code' => $inv_code));
			$code_query = $this->db->get('invoice');

			$data['so_code'] = $code_query->row()->so_code;
			$data['invoice_date'] = $code_query->row()->date;

			$this->db->select_sum('amount_paid');
			$this->db->where('amount_paid >', 0);
			$this->db->where(array('customer_id' => $customer_id, 'invoice_code' => $inv_code));
			$data['prev_amount_received'] = $this->db->get('invoice')->row()->amount_paid;

			echo json_encode($data);
		}
	}

	function get_po_codes($supplier_id, $param2 = '') {

		if ($param2 == 'negative_bal') {
			//search invoice table instead
			$customer_id = $supplier_id;
			$so_codes_array = $this->db->get_where('invoice', array('amount_due <' => 0, 'customer_id' => $customer_id))->result_array();

			foreach ($so_codes_array as $s_order):

				echo '<option value="' . $s_order['so_code'] . '">' . $s_order['so_code'] . '</option>';
			endforeach;

		} else {
			//search accounts payable table
			$po_codes_array = $this->db->get_where('accounts_payable', array('amount_due >' => 0, 'supplier_id' => $supplier_id))->result_array();

			foreach ($po_codes_array as $p_order):

				echo '<option value="' . $p_order['po_code'] . '">' . $p_order['po_code'] . '</option>';
			endforeach;
		}

	}

	function get_inv_codes($customer_id, $invoice_code = '') {

		if ($invoice_code == '' || empty($invoice_code)) {
			$inv_codes_query = $this->db->get_where('invoice', array('amount_due >' => 0, 'customer_id' => $customer_id));
			$inv_codes_array = $inv_codes_query->result_array();

			if ($inv_codes_query->num_rows() < 1) {
				echo 'Not';
			} else {
				foreach ($inv_codes_array as $inv_code):

					echo '<option value="' . $inv_code['invoice_code'] . '">' . $inv_code['invoice_code'] . '</option>';
				endforeach;
			}
		} else {
			$inv_codes_query = $this->db->get_where('invoice', array('amount_due >' => 0, 'customer_id' => $customer_id));
			$inv_codes_array = $inv_codes_query->result_array();
			if ($inv_codes_query->num_rows() < 1) {
				echo 'Not';
			} else {
				foreach ($inv_codes_array as $inv_code):
					if ($inv_code['invoice_code'] == $invoice_code) {
						$selected = 'selected';
					} else {
						$selected = '';
					}

					echo '<option value="' . $inv_code['invoice_code'] . '"' . $selected . '>' . $inv_code['invoice_code'] . '</option>';
				endforeach;
			}
		}

	}

