	}

	//add order row
	function add_order_row($supplier_id = '', $category = '', $amount = '', $customer_id = '', $order_date = '', $selected_item_ids = '') {
		if ($supplier_id == 'so') {

			//FOR SALES ORDER
			$selected_item_ids = explode('-', $selected_item_ids);
			//$selected_item_ids = implode(',', $selected_item_ids);

			//select all items except those already selected
			if (count($selected_item_ids) != 0) {
				$this->db->where_not_in('item_id', $selected_item_ids);
			}

			$item_data['all_items_array'] = $this->db->get('items')->result_array();
			$item_data['category'] = $category;
			$item_data['so'] = $supplier_id;
			$item_data['balance_due'] = $amount;

			$item_data['customer_id'] = $customer_id;
			$item_data['order_date'] = $order_date;
			$this->load->view('backend/admin/pages/add_order_row.php', $item_data);
		} else {

			//FOR PURCHASE ORDER
			$item_data['all_items_array'] = $this->db->get('items')->result_array();
			$item_data['category'] = $category;
			$this->load->view('backend/admin/pages/add_order_row.php', $item_data);
		}
	}

