	//is creditor checker
	function is_creditor($id = '') {
		//$this->db->like('so_code', 'Opening', 'after');
		$goods_creditor_query = $this->db->get_where('sales_order', array('customer_id' => $id, 'quantity_due >' => 0));

		//$this->db->where('so_code', 'Opening-balance');
		$negative_creditor_query = $this->db->get_where('invoice', array('customer_id' => $id, 'amount_due <' => 0));

		if ($goods_creditor_query->num_rows() > 0 && $negative_creditor_query->num_rows() > 0) {

			$so_code = $this->db->get_where('sales_order', array('customer_id' => $id, 'quantity_due >' => 0))->row()->so_code;
			$data['goods_negative'] = true;
			$data['so_code'] = $so_code;

		} else if ($goods_creditor_query->num_rows() > 0) {
			$so_code = $this->db->get_where('sales_order', array('customer_id' => $id, 'quantity_due >' => 0))->row()->so_code;
			$data['goods'] = true;
			$data['so_code'] = $so_code;

		} else if ($negative_creditor_query->num_rows() > 0) {
			$data['negative'] = true;

		}

		echo json_encode($data);
	}

