	function account_allocation($type = '', $payment_id = '') {
		if ($type == 2) {
			$accounts = $this->db->get_where('accounts', array('account_type' => 5, 'name !=' => 'General Products Purchased'))->result_array();
		} else if ($type == 3) {
			$accounts = $this->db->get_where('accounts', array('name ' => 'Accounts Receivable'))->result_array();
		} else {
			$accounts = $this->db->get_where('accounts', array('name ' => 'Accounts Payable'))->result_array();
		}

		//from payment table
		$account_id = $this->db->get_where('payment', array('payment_id ' => $payment_id))->row()->account_id;
		foreach ($accounts as $acc):
			if ($account_id == $acc['account_id']) {
				echo '<option value="' . $acc['account_id'] . '" selected>' . $acc['name'] . '</option>';
			} else {
				echo '<option value="' . $acc['account_id'] . '">' . $acc['name'] . '</option>';
			}

		endforeach;
	}

	//filter customer ids and so_codes retrieved from the payment page for the customer creditors
	function filter_values($value) {
		//the value looks like: cr_3_SO-100001
		//let's cut the cr_ part off
		$raw = $value;
		$value = substr($value, 3);
		//now let's separate the customer id from the so code
		$value = explode('_', $value);
		$data['customer_id'] = $value[0];
		$data['so_code'] = $value[1];

		if (substr($raw, 0, 3) == 'ce_') {
			$data['negative'] = true;
		} else {
			$data['negative'] = false;
		}
		echo json_encode($data); //Done. Encode with json and send back to the ajax request
	}

//GET SELECTED DATES FOR THE REPORTS
	function get_selected_dates($date_value) {

		$opening_day = $this->db->get_where('settings', array('type' => 'opening_day'))->row()->description;
		$closing_day = $this->db->get_where('settings', array('type' => 'closing_day'))->row()->description;

		if ($date_value == 2) {
			//Today
			$data['from'] = date('d-m-Y');
			$data['to'] = date('d-m-Y');

			$data['from_view'] = date('l F d, Y');
			$data['to_view'] = date('l F d, Y');

		} else if ($date_value == 3) {
			//Yesterday
			$data['from'] = date('d-m-Y', strtotime('yesterday'));
			$data['to'] = date('d-m-Y', strtotime('yesterday'));

			$data['from_view'] = date('l F d, Y', strtotime('yesterday'));
			$data['to_view'] = date('l F d, Y', strtotime('yesterday'));

		} else if ($date_value == 4) {
			//This week
			$data['from'] = date('d-m-Y', strtotime('this week ' . $opening_day));
			$data['to'] = date('d-m-Y');

			$data['from_view'] = date('l F d, Y', strtotime('this week ' . $opening_day));
			$data['to_view'] = date('l F d, Y');

		} else if ($date_value == 5) {
			//Last week
			$data['from'] = date('d-m-Y', strtotime('last week ' . $opening_day));
			$data['to'] = date('d-m-Y', strtotime('last week ' . $closing_day));

			$data['from_view'] = date('l F d, Y', strtotime('last week ' . $opening_day));
			$data['to_view'] = date('l F d, Y', strtotime('last week ' . $closing_day));

		} else if ($date_value == 6) {
			//This month
			$data['from'] = date('d-m-Y', strtotime('first day of this month'));
			$data['to'] = date('d-m-Y');

			$data['from_view'] = date('l F d, Y', strtotime('first day of this month'));
			$data['to_view'] = date('l F d, Y');

		} else if ($date_value == 7) {
			//Last month
			$data['from'] = date('d-m-Y', strtotime('first day of previous month'));
			$data['to'] = date('d-m-Y', strtotime('last day of previous month'));

			$data['from_view'] = date('l F d, Y', strtotime('first day of previous month'));
			$data['to_view'] = date('l F d, Y', strtotime('last day of previous month'));

		} else if ($date_value == 8) {
			//This Year
			$data['from'] = date('d-m-Y', strtotime('first day of january this year'));
			$data['to'] = date('d-m-Y');

			$data['from_view'] = date('l F d, Y', strtotime('first day of january this year'));
			$data['to_view'] = date('l F d, Y');

		} else if ($date_value == 9) {
			//Last Year
			$data['from'] = date('d-m-Y', strtotime('first day of january previous year'));
			$data['to'] = date('d-m-Y', strtotime('last day of december previous year'));

			$data['from_view'] = date('l F d, Y', strtotime('first day of january previous year'));
			$data['to_view'] = date('l F d, Y', strtotime('last day of december previous year'));

		} else if ($date_value == 10) {
			//Custom so reset dates to today
			/** $data['from'] = date('d-m-Y');
			$data['to'] = date('d-m-Y');

			$data['from_view'] = date('l F d, Y');
			$data['to_view'] = date('l F d, Y'); **/

		} else if ($date_value == 0) {
			//Custom so reset dates to today
			$data['from'] = 0; //date('d-m-Y');
			$data['to'] = 0; //date('d-m-Y');

			$data['from_view'] = 0; //date('l F d, Y');
			$data['to_view'] = 0; //date('l F d, Y');

		}

		//prepare the result and send it back to the ajax call
		echo json_encode($data);
	}

