				$response['response'] = 'yes';
			}
			

			/*$this->db->select('receipt_code, timestamp');
			$this->db->distinct();
			$rows_returned_query = $this->db->get_where('payment', array('so_code' => $order_code));
			$timestamp = $rows_returned_query->first_row()->timestamp;

			$payment_methods = $this->db->get_where('payment', ['timestamp' => $timestamp, 'so_code' => $so_code])->num_rows();
			$rows_returned = $rows_returned_query->num_rows();
			$rows_returned2 = $this->db->get_where('payment_with_goods', array('so_code' => $order_code, 'quantity_picked >' => 0))->num_rows();
			//even if it is payable, let's see if this transaction has any of the items picked. If not, we open the normal editing template

			if ($rows_returned > $payment_methods) {
				$response['response'] = 'yes';

				//check if this is payment with goods or normal editing
