	//get invoice balance
	function get_invoice_balance($invoice_code, $customer_id) {
		$invoice_code = append_words($invoice_code, '_');

		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);

		$bal_amount = $this->db->get_where('invoice', array('invoice_code' => $invoice_code, 'customer_id' => $customer_id, 'amount_due <' => 0))->row()->amount_due;
		$bal = 'Amount Payable to this creditor is: ' . numfmt_format_currency($fmt, abs($bal_amount), $currency) . '<input type="hidden" name="balance_due" id="balance_due" value="' . abs($bal_amount) . '">';
		echo $bal;
	}

	//get invoice balance
	function get_negative_balance($customer_id) {
		//$invoice_code = append_words($invoice_code, '_');

		$currency = $this->db->get_where('settings', array('type' => 'currency'))->row()->description;
		$fmt = new NumberFormatter('en_US', NumberFormatter::CURRENCY);

		$this->db->select_sum('amount_due');
		$bal_amount = $this->db->get_where('invoice', array('customer_id' => $customer_id, 'amount_due <' => 0))->row()->amount_due;

		$bal = 'Amount Payable to this creditor is: ' . numfmt_format_currency($fmt, abs($bal_amount), $currency) . '<input type="hidden" name="balance_due" id="balance_due" value="' . abs($bal_amount) . '">';
		echo $bal;
	}

	//get so code
	function get_so_code_for_negative_balance($invoice_code, $customer_id) {
		$invoice_code = append_words($invoice_code, '_');

		$so_code = $this->db->get_where('invoice', array('invoice_code' => $invoice_code, 'customer_id' => $customer_id))->row()->so_code;

		$so_code_rows = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id))->num_rows();

