	function get_payment_with_goods_order($so_code, $customer_id) {

		$page_data['so_code'] = $so_code;
		$page_data['customer_id'] = $customer_id;

		$date = $this->db->get_where('sales_order', array('so_code' => $so_code, 'customer_id' => $customer_id))->row()->date_timestamp;
