	//update payables and receivables whenever a modal is closed or hidden
	function update_ables($payable = '', $receivable = '') {
		//acounts table first
		//for payables
		$this->db
			->where('name', 'Accounts Payable')
			->set('current_balance', $payable)
			->update('accounts');

		//for receivables
		$this->db
			->where('name', 'Accounts Receivable')
			->set('current_balance', $receivable)
			->update('accounts');

		//general journal table
		//for payables
		$latest_payable_timestamp = $this->db
			->select('date_timestamp')
			->distinct()
			->where('account_name', 'Accounts Payable')
			->order_by('date_timestamp', 'desc')
			->limit(1)
			->get('general_journal')->row()->date_timestamp;
		$this->db
			->where('date_timestamp', $latest_payable_timestamp)
			->where('account_name', 'Accounts Payable')
			->set('account_balance', $payable)
			->update('general_journal');

		//for receivables
		$latest_receivable_timestamp = $this->db
			->select('date_timestamp')
			->distinct()
			->where('account_name', 'Accounts Receivable')
			->order_by('date_timestamp', 'desc')
			->limit(1)
			->get('general_journal')->row()->date_timestamp;
		$this->db
			->where('date_timestamp', $latest_receivable_timestamp)
			->where('account_name', 'Accounts Receivable')
			->set('account_balance', $receivable)
			->update('general_journal');
	}

