	//attendance status checking for  Cashiers only
	private function clock_in($user_id, $today_date) {
		$timestamp = strtotime(date('d-m-Y H:i:s'));
		$this->db->insert('attendance', array(
			'user_id' => $user_id,
			'date_timestamp' => $today_date,
			'in_timestamp' => $timestamp,
			'status' => 1
		));
		
		// Cache items to avoid repeated queries
		if ($this->items_cache === null) {
			$this->db->select('item_id, quantity, purchase_price, selling_price');
			$this->items_cache = $this->db->get('items')->result_array();
		}
		
		$bulkInsertNew = array();
		foreach ($this->items_cache as $item) {
			$bulkInsertNew[] = array(
				'item_id' => $item['item_id'],
				'user_id' => $user_id,
				'opening_timestamp' => $timestamp,
				'date_timestamp' => $today_date,
				'opening_stock' => $item['quantity'],
				'cost_price' => $item['purchase_price'],
				'selling_price' => $item['selling_price']
			);
		}
		if (!empty($bulkInsertNew)) {
			$this->db->insert_batch('stock_manager', $bulkInsertNew);
		}
		$this->session->set_userdata('user_clocked_in', '1');
	}


	private function clock_out($user_id, $today_date) {
		$out_timestamp = strtotime(date('d-m-Y H:i:s'));
		$this->db->where('user_id', $user_id);
		$this->db->where('date_timestamp', $today_date);
		$this->db->update('attendance', array(
			'out_timestamp' => $out_timestamp,
			'status' => 0
		));
		$this->db->select('sm.stock_id, i.quantity, i.purchase_price, i.selling_price');
		$this->db->from('stock_manager sm');
		$this->db->join('items i', 'i.item_id = sm.item_id');
		$this->db->where('sm.date_timestamp', $today_date);
		$this->db->where('sm.user_id', $user_id);
		$stock_items = $this->db->get()->result_array();
		if (!empty($stock_items)) {
			$bulkUpdate = array();
			foreach ($stock_items as $stock) {
				$bulkUpdate[] = array(
					'stock_id' => $stock['stock_id'],
					'closing_timestamp' => $out_timestamp,
					'closing_stock' => $stock['quantity'],
					'cost_price' => $stock['purchase_price'],
					'selling_price' => $stock['selling_price']
				);
			}
			$this->db->update_batch('stock_manager', $bulkUpdate, 'stock_id');
		}
		$this->session->set_userdata('user_clocked_in', '0');
	}

	

	function cronJobForClockingInClockingOut() {
		$this->db->select('admin_id');
		$this->db->from('admin');
		$this->db->where('block_limit !=', 3);
		$usersIdsArray = $this->db->get()->result_array();
		$usersIds = array_column($usersIdsArray, 'admin_id');

		if (empty($usersIds)) return;

		$today_date = strtotime(date('d-m-Y'));
		$this->db->select_max('date_timestamp');
		$this->db->where('date_timestamp !=', $today_date);
		$prev_day = $this->db->get('attendance')->row()->date_timestamp;

		if (!$prev_day) return;

		$selected_time = '18:00:00';
		$out_timestamp = strtotime(date('d-m-Y', $prev_day) . ' ' . $selected_time);

		// Batch update attendance
		$this->db->where_in('user_id', $usersIds);
		$this->db->where('date_timestamp', $prev_day);
		$this->db->where('out_timestamp IS NULL');
		$this->db->update('attendance', array('out_timestamp' => $out_timestamp, 'status' => 0));

		// Cache items once
		if ($this->items_cache === null) {
			$this->db->select('item_id, quantity, purchase_price, selling_price');
			$this->items_cache = $this->db->get('items')->result_array();
		}

		// Get stock records needing update
		$this->db->select('stock_id, item_id');
		$this->db->where('date_timestamp', $prev_day);
		$this->db->where('closing_timestamp IS NULL');
		$this->db->where_in('user_id', $usersIds);
		$stock_records = $this->db->get('stock_manager')->result_array();

		if (!empty($stock_records)) {
			$items_lookup = array();
			foreach ($this->items_cache as $item) {
				$items_lookup[$item['item_id']] = $item;
			}

			$bulkUpdate = array();
			foreach ($stock_records as $stock) {
				if (isset($items_lookup[$stock['item_id']])) {
					$item = $items_lookup[$stock['item_id']];
					$bulkUpdate[] = array(
						'stock_id' => $stock['stock_id'],
						'closing_timestamp' => $out_timestamp,
						'closing_stock' => $item['quantity'],
						'cost_price' => $item['purchase_price'],
						'selling_price' => $item['selling_price']
					);
				}
			}
			if (!empty($bulkUpdate)) {
				$this->db->update_batch('stock_manager', $bulkUpdate, 'stock_id');
			}
		}

		// Handle new clock-ins
		$this->db->select('user_id');
		$this->db->where('date_timestamp', $today_date);
		$this->db->where_in('user_id', $usersIds);
		$existing_users = array_column($this->db->get('attendance')->result_array(), 'user_id');
		$new_users = array_diff($usersIds, $existing_users);

		if (!empty($new_users)) {
			$current_timestamp = strtotime(date('d-m-Y H:i:s'));
			$bulkAttendance = array();
			$bulkStock = array();

			foreach ($new_users as $user_id) {
				$bulkAttendance[] = array(
					'user_id' => $user_id,
					'date_timestamp' => $today_date,
					'in_timestamp' => $current_timestamp,
					'status' => 1
				);

				foreach ($this->items_cache as $item) {
					$bulkStock[] = array(
						'item_id' => $item['item_id'],
						'user_id' => $user_id,
						'opening_timestamp' => $current_timestamp,
						'date_timestamp' => $today_date,
						'opening_stock' => $item['quantity'],
						'cost_price' => $item['purchase_price'],
						'selling_price' => $item['selling_price']
					);
				}
			}

			if (!empty($bulkAttendance)) $this->db->insert_batch('attendance', $bulkAttendance);
			if (!empty($bulkStock)) $this->db->insert_batch('stock_manager', $bulkStock);
		}

		echo 'Done';

		$selected_time = '18:00:00';

		$date = date('d-m-Y', $prev_day);
		$out_timestamp = strtotime(date($date . ' ' . $selected_time));
		$att_data_d['out_timestamp'] = $out_timestamp;

		//update the attendance table now
		$this->db->where_in('user_id', $usersIds);
		$this->db->where('date_timestamp', $prev_day); //the previous session date
		$this->db->set('out_timestamp', $att_data_d['out_timestamp']);
		$this->db->set('status', 0);
		//update data
		$this->db->update('attendance');

		//update the stock manager table as well
		//get the closing stocks and update the stock manager table
		$item_array = $this->db->get('items')->result_array();

		$bulkUpdateArray = [];
		$bulkStockIds = [];
		$itemIds = [];
			foreach ($item_array as $item) {

				//new query from the stock manager table
				$this->db->select('stock_id');
				$stockIdsArray = $this->db->get_where('stock_manager', array('date_timestamp' => $prev_day, 'item_id' => $item['item_id']))->result_array();

				$stockIds = array_column($stockIdsArray, 'stock_id');
				$bulkStockIds['stock_id'] = $stockIds;
				$itemIds[] = $item['item_id'];

				$stock_manager_data['closing_timestamp'] = $out_timestamp;
				$stock_manager_data['date_timestamp'] = $prev_day;
				//$stock_manager_data['item_id'] = $item['item_id'];
				$stock_manager_data['closing_stock'] = $item['quantity'];
				$stock_manager_data['cost_price'] = $item['purchase_price'];
				$stock_manager_data['selling_price'] = $item['selling_price'];

				$bulkUpdateArray[] = $stock_manager_data;
				/*$this->db->where_in('stock_id', $stockIds);
				$this->db->update('stock_manager', $stock_manager_data);*/

			} //end of loop
		var_dump($bulkStockIds);
		return;
			$this->db->where_in('stock_id', $bulkStockIds);
			$this->db->where_in('item_id', $itemIds);
			$this->db->update_batch('stock_manager', $bulkUpdateArray, 'date_timestamp');

		echo 'Done';
		return;

			/*do new clock clock in*/
			//no data found for today so enter new record - clock in
			$bulkInsertNew = [];
			$bulkInsertNewAttendance = [];

			foreach($usersIdsArray as $user):
				
				$att_data['user_id'] = $user['admin_id'];
				$att_data['date_timestamp'] = $today_date;
				$att_data['in_timestamp'] = strtotime(date('d-m-Y H:i:s'));
				$att_data['status'] = 1;

				$bulkInsertNewAttendance[] = $att_data;

				//get the opening stocks and insert into the stock manager table
				$item_array = $this->db->get('items')->result_array();

			
				foreach ($item_array as $item) {
					$stock_manager_data['item_id'] = $item['item_id'];
					$stock_manager_data['user_id'] = $user['admin_id'];
					$stock_manager_data['opening_timestamp'] = strtotime(date('d-m-Y H:i:s'));
					$stock_manager_data['date_timestamp'] = strtotime(date('d-m-Y'));
					$stock_manager_data['opening_stock'] = $item['quantity'];
					$stock_manager_data['cost_price'] = $item['purchase_price'];
					$stock_manager_data['selling_price'] = $item['selling_price'];

					$bulkInsertNew[] = $stock_manager_data;

					
				} //end of loop

			endforeach;

			//insert now
			if(count($bulkInsertNew) > 0) {
				$stockResp = $this->db->insert_batch('stock_manager', $bulkInsertNew);
				//$this->session->set_userdata('user_clocked_in', '1');
			}

			if(count($bulkInsertNewAttendance) > 0) {
				//insert data
				//$attResp = $this->db->insert_batch('attendance', $bulkInsertNewAttendance);
			}

			echo $attResp;
	}

	//check session
