	//add items units
	function addItemUnits($param, $param2 = '', $param3 = '') {

		$this->db->select_max('item_id');
		$max_item_id = $this->db->get('items')->row()->item_id;
		$item_id = intVal($max_item_id) + 1;

		if($param3 > 0) { //meaning we are coming from the edit page so we use the real item id, not the calculated one
			$item_id = $param3;

			//quickly update the items table with this info
			$this->db->where('item_id', $item_id);
			$this->db->set('item_sold_in_units', '1');
			$this->db->update('items');
		}

		if($param2 == '0') { //coming from edit page
			$pageData3['isEdit'] = 1;
		}

		if($param == 'create') {

			$data['unit_id'] = $this->input->post('item_unit');
			$data['unit_total'] = $this->input->post('unit_total');
			$data['unit_price'] = $this->input->post('unit_price');
			$data['timestamp'] = $this->input->post('timestamp');
			$data['item_id'] = $item_id;

			$this->db->insert('units_items', $data);

					

		} else if($param == 'remove') {

			$id = $param2;
			$item_id = $param3;
			$pageData3['isEdit'] = 1;

			$this->db->where('id', $id);
			$this->db->delete('units_items');


		} else if($param == 'clear') {
			//in case user decides not to add item again after adding the units, 
			//we clear it
			
			$this->db->where('item_id', $item_id);
			$this->db->delete('units_items');

			if($param3 > 0) { //this can only happen on the edit page
				//we want to set the item to not been sold in units in the items table if user decides to clear or remove all added units
				$row = $this->db->get_where('units_items', ['item_id' => $param3])->num_rows();
				if($row < 1) {
					$this->db->where('item_id', $param3);
					$this->db->set('item_sold_in_units', '0');
					$this->db->update('items');
				}
			}

		}


		//let's try and hide the selected items from the user so he does not select them multiple times
			if($param == 'refresh') {
				
				//remaining units available for selection
				$pageData2['units_ids'] = $this->db->get('units')->result_array();


				$ajaxData['unit_list'] = $this->load->view('backend/admin/pages/sales/get_available_units_ids', $pageData2, true);

				$this->db->where('item_id', $item_id);
				$pageData3['list']  = $this->db->get('units_items')->result_array();

					
				$ajaxData['data']  = $this->load->view('backend/admin/pages/sales/get_added_units_list_for_item', $pageData3, true);

	
			} else {

				$this->db->select('unit_id');
				$this->db->distinct();
				$this->db->where('item_id', $item_id);
				$select_unit_ids_array = $this->db->get('units_items')->result_array();

				if(sizeof($select_unit_ids_array) > 0) {
					$ids_array = [];
					foreach($select_unit_ids_array as $unit) {
						$ids_array[] = $unit['unit_id'];
					}


				//remaining units available for selection
				$this->db->where_not_in('unit_id', $ids_array);
				$pageData2['units_ids'] = $this->db->get('units')->result_array();


				$ajaxData['unit_list'] = $this->load->view('backend/admin/pages/sales/get_available_units_ids', $pageData2, true);

				$this->db->where('item_id', $item_id);
				$pageData3['list']  = $this->db->get('units_items')->result_array();

					
				$ajaxData['data']  = $this->load->view('backend/admin/pages/sales/get_added_units_list_for_item', $pageData3, true);

				} else {
					$pageData2['units_ids'] = $this->db->get('units')->result_array();
					$ajaxData['unit_list'] = $this->load->view('backend/admin/pages/sales/get_available_units_ids', $pageData2, true);

					$ajaxData['data'] = null;
				}
			}


			echo json_encode($ajaxData);
	} 

