	//generate invoice codes
	function generateInvoiceCodes($start_code='', $end_code='') {

		//server side validation
    if(($start_code == '' && $end_code == '') || ($start_code < 1 || $end_code < 1) || $start_code == $end_code) {
      $errors['invalid'] = 'INVALID INVOICE CODES';

    }

    if($start_code > $end_code) {

      $errors['invalid'] = '<strong>INVALID INVOICE CODE RANGE:</strong><br/>MAKE SURE START CODE IS LESS THAN THE END CODE!';
    }

    //throw error and return
    if(!empty($errors)) {

    	echo json_encode($errors);
    	return;

    } else { //all is well

    	$codeRange = $start_code .'-'.$end_code;

    	$rangeDuplicate = invoiceDuplicateChecker($codeRange, 'code_range');

    	if($rangeDuplicate) {
    		//duplicate found
    		$ajaxData['success'] = 'duplicate';
    		$ajaxData['message'] = 'Same invoice range already exists.';
    	} else{

	    	$codesArray = array();
	    	

	    	$diff = $end_code - $start_code;

	    	for($i = 0; $i <= $diff; $i++) {

	    		$codes['code'] = $start_code + $i;

	    		$codeDuplicate = invoiceDuplicateChecker($codes['code'], 'code');

	    		//check individual code duplicate
	    		if($codeDuplicate) {

	    			$ajaxData['success'] = 'duplicate';
    				$ajaxData['message'] = 'Same invoice code already exists.';

    				break; //exit this loop


	    		} else {

	    			$codes['code_range'] = $codeRange;
		    		$codes['created_by'] = $this->session->userdata('login_user_id');

						$codesArray[] = $codes;
	    		}
	    		   		
	    	}

	    	//validate this too
	    	if(!$codeDuplicate) {

		    	$batchInsertResponse = $this->db->insert_batch('invoice_code', $codesArray);

		    	if($batchInsertResponse) {

		    		$ajaxData['success'] = true;

		    	} else {

		    		$ajaxData['success'] = false;
		    		$ajaxData['message'] = 'We are unable to execute this task. Please try again later.';

		    	}
		    }
			}

			echo json_encode($ajaxData);
			return;
    }

		
	}


