	//Update or insert reason for not using the invoice code
	function invoiceReasonUpdator($invoice_code) {
		$errors = array();
		$ajaxData = array();

		$reason = $this->input->post('reason');

		if($reason == '') {
			$errors['reason'] = 'Please specify the reason!';
		}
		if(strlen($reason) < 10) {
			$errors['reason_invalid'] = 'This does not seem to be a valid reason! Make sure you write more than 10 characters.';
		}

		if(!empty($errors)) {
			//error
			echo json_encode($errors);
			return;

		} else {

			//all is well
			$this->db->where('code', $invoice_code);
			$this->db->set('reason_not_used', $reason);
			$this->db->set('status', 'not used');
			$this->db->update('invoice_code');

			$ajaxData['status'] = 'success';
			$ajaxData['message'] = 'YOU CANCELLED THIS INVOICE CODE SUCCESSFULLY.';
			echo json_encode($ajaxData);

			return;
		}
	}


