	/*
************************************************************************
FOR RUNNING QUICK UPDATE IN THE DATABASE
************************************************************************
	*/
	function updateZeroBalanceItems() {

		$this->db->select('item_id');
		$this->db->from('items');
		$this->db->where('quantity', 0);
		$items_array = $this->db->get()->result_array();

		foreach($items_array as $item) {
			//for payment_with_goods table
			$this->db->select_max('date_timestamp');
			$this->db->where('item_id', $item['item_id']);
			$last_date_timestamp = $this->db->get('payment_with_goods')->row()->date_timestamp;

			//update now
			$this->db->where('item_id', $item['item_id']);
			$this->db->where('date_timestamp', $last_date_timestamp);
			$this->db->set('item_balance', 0);
			$this->db->update('payment_with_goods');

			//for items_transfers table
			$this->db->select_max('date_timestamp');
			$this->db->where('item_id', $item['item_id']);
			$last_date_timestamp = $this->db->get('items_transfers')->row()->date_timestamp;

			//update now
			$this->db->where('item_id', $item['item_id']);
			$this->db->where('date_timestamp', $last_date_timestamp);
			$this->db->set('item_balance', 0);
			$this->db->update('items_transfers');

		}

		echo 'success';

	}


	function batchPriceInsert() {
				//LET'S GET ALL THE AVAILABLE ACTIVE CUSTOMER SO WE CAN UPDATE THIS CUSTOMER'S PRICES IN THE PRICES TABLE WITH THE SELLING PRICE OF THIS ITEM(PRODUCT)

					//for all items
					/*$this->db->select('item_id, selling_price');
					$all_items = $this->db->get('items')->result_array();*/


					$this->db->select('customer_id');
          $this->db->distinct();
          $this->db->from('customers');
          $this->db->where('customer_active', 1);
          $this->db->where('guest', '0');
          $c_customer_query = $this->db->get();
          $c_customer_array = $c_customer_query->result_array();


          $customerData = [];

					foreach($c_customer_array as $customer) {

						
						//for all items
						/*foreach($all_items as $item) {
							$data['item_id'] = $item['item_id'];
							$data['customer_id'] = $customer['customer_id'];
							$data['item_price'] = $item['selling_price'];

							$customerData[] = $data;
						}*/

						//for only the items the customer has ever bought
						$this->db->select('item_id');
						$this->db->distinct();
						$this->db->from('sales_order');
						$this->db->where('customer_id', $customer['customer_id']);
						$items_bought = $this->db->get()->result_array();

						foreach($items_bought as $item) {
							$data['item_id'] = $item['item_id'];
							$data['customer_id'] = $customer['customer_id'];
							$data['item_price'] = $this->db->get_where('items', ['item_id' => $item['item_id']])->row()->selling_price;

							$customerData[] = $data;
						}
					}

					$resp = $this->db->insert_batch('items_prices', $customerData);
					if($resp) {
						echo 'success';
					} else {
						echo 'failed';
					}
	}

	function batchPriceUpdate() {
				//LET'S GET ALL THE AVAILABLE ACTIVE CUSTOMER SO WE CAN UPDATE THIS CUSTOMER'S PRICES IN THE PRICES TABLE WITH THE SELLING PRICE OF THIS ITEM(PRODUCT)
					$all_items = $this->db->get('items')->result_array();

	

					$this->db->select('customer_id');
          $this->db->distinct();
          $this->db->from('customers');
          $this->db->where('customer_active', 1);
          $this->db->where('guest', '0');
          $c_customer_query = $this->db->get();
          $c_customer_array = $c_customer_query->result_array();


          $customerData = [];

					foreach($c_customer_array as $customer) {
						foreach($all_items as $item) {
							$data['item_id'] = $item['item_id'];
							$data['customer_id'] = $customer['customer_id'];
							$data['item_price'] = $item['selling_price'];

							$customerData[] = $data;
						}
					}

					$this->db->insert_batch('items_prices', $customerData);
	}

	//update items unit quantity in the items table
	function updateUnitQuantity() {

		$this->db->select('item_id');
		$this->db->distinct();
		$this->db->from('unit_transfer');
		$item_ids = $this->db->get()->result_array();

		$batch_array = [];

		foreach($item_ids as $id) {

			$unit_quantity = $this->db->get_where('unit_transfer', ['item_id' => $id['item_id']])->last_row()->unit_quantity_balance;

			$query_array = [
				'item_id' => $id['item_id'],
				'unit_quantity' => $unit_quantity
			];

			$batch_array[] = $query_array;
		}

		$resp = $this->db->update_batch('items', $batch_array, 'item_id');

		if($resp) {
			$ajaxData['success'] = true;
			$ajaxData['message'] = 'Well Done. We have finished!';

		} else {
			$ajaxData['success'] = false;
			$ajaxData['message'] = 'Ooopz sorry, we couldn\'t execute your request. Try again.';
		}

		echo json_encode($ajaxData);

	}


